    pub struct DerivedArtifactAnalyzer<Spec: DerivedArtifactSpec>(std::marker::PhantomData<Spec>);

    impl<Spec: DerivedArtifactSpec> ArtifactAnalyzer for DerivedArtifactAnalyzer<Spec> {
