        pub schema: String,
        pub extension_id: String,
        pub manifest: FlowExtensionManifest,
        pub executable_identity: FlowExtensionExecutableIdentity,
    }

    /// 🌊️ Immutable `flow.extension` contribution; it carries no mutating installer function.
    #[derive(Clone, Debug)]
    pub struct FlowExtensionDeclaration {
        id: ArtifactIdentity,
        extension_id: ArtifactIdentity,
        manifest: FlowExtensionManifest,
        executable_identity: FlowExtensionExecutableIdentity,
    }

    impl FlowExtensionDeclaration {
        /// 🏗️ Declares a `flow.extension` manifest and its immutable native executable identity.
        pub fn new(id: impl Into<String>, manifest: FlowExtensionManifest, executable_identity: FlowExtensionExecutableIdentity) -> Result<Self, PluginAssemblyError> {
            let declaration = Self { id: ArtifactIdentity::parse(id).map_err(PluginAssemblyError::definition)?, extension_id: ArtifactIdentity::parse(manifest.id.clone()).map_err(PluginAssemblyError::definition)?, manifest, executable_identity };
            declaration.validate_shape()?;
            Ok(declaration)
        }

        /// 🪪️ Returns the stable contribution id.
        pub fn id(&self) -> &str {
            self.id.as_str()
        }

        fn validate_shape(&self) -> Result<(), PluginAssemblyError> {
            self.manifest.validate()
        }

        pub(crate) fn preflight(&self, owner: &str) -> Result<(), PluginAssemblyError> {
            ArtifactIdentity::parse(owner.to_string()).map_err(PluginAssemblyError::definition)?;
            self.validate_shape()
        }

        fn descriptor(&self, owner: &str) -> FlowExtensionDescriptor {
            FlowExtensionDescriptor {
                id: self.id.as_str().to_string(),
                owner: owner.to_string(),
                domain: "flow.extension".into(),
                schema: "flow.extension".into(),
                extension_id: self.extension_id.as_str().to_string(),
                manifest: self.manifest.clone(),
                executable_identity: self.executable_identity.clone(),
            }
        }
    }

    struct RegisteredHostMediaHandler {
        descriptor: HostMediaHandlerDescriptor,
        executable: HostMediaExecutable,
    }

    impl RegisteredHostMediaHandler {
        fn identical_to(&self, other: &Self) -> bool {
            self.descriptor == other.descriptor
                && match (self.executable, other.executable) {
                    (HostMediaExecutable::MeshImport(left), HostMediaExecutable::MeshImport(right)) => std::ptr::fn_addr_eq(left, right),
                    (HostMediaExecutable::TwoDSvgExport(left), HostMediaExecutable::TwoDSvgExport(right)) => std::ptr::fn_addr_eq(left, right),
                    _ => false,
                }
        }
    }

    struct HostMediaHandlerRegistry {
        by_id: BTreeMap<String, RegisteredHostMediaHandler>,
        by_target: BTreeMap<(HostMediaHandlerKind, String), String>,
    }

    impl HostMediaHandlerRegistry {
        fn new() -> Self {
            Self { by_id: BTreeMap::new(), by_target: BTreeMap::new() }
        }

        fn from_declarations(owner: &str, declarations: &[HostMediaHandlerDeclaration]) -> Result<Self, PluginAssemblyError> {
            let mut registry = Self::new();
            for declaration in declarations {
                registry.register(owner, declaration)?;
            }
            Ok(registry)
        }

        fn register(&mut self, owner: &str, declaration: &HostMediaHandlerDeclaration) -> Result<(), PluginAssemblyError> {
            let descriptor = declaration.descriptor(owner);
            let entry = RegisteredHostMediaHandler { descriptor: descriptor.clone(), executable: declaration.executable };
            if let Some(existing) = self.by_id.get(&descriptor.id) {
                if existing.identical_to(&entry) {
                    return Ok(());
                }
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-id", format!("host-media contribution {:?} has a conflicting descriptor or executable identity", descriptor.id)));
            }
            let target = (descriptor.kind, descriptor.artifact_kind.id.clone());
            if let Some(existing) = self.by_target.get(&target) {
                return Err(PluginAssemblyError::new("plugin-assembly.host-media-target", format!("host-media target {}:{} is already owned by {:?}", descriptor.kind.as_str(), descriptor.artifact_kind.id, existing)));
            }
            self.by_target.insert(target, descriptor.id.clone());
            self.by_id.insert(descriptor.id, entry);
            Ok(())
        }

        fn descriptors(&self) -> Vec<HostMediaHandlerDescriptor> {
            self.by_id.values().map(|entry| entry.descriptor.clone()).collect()
        }

        fn mesh_import(&self, request: &MeshImportRequest) -> Result<MeshImportResult, HostMediaRuntimeError> {
            let entry = self.lookup(HostMediaHandlerKind::MeshImport, &request.artifact_kind, &request.artifact_schema)?;
            let HostMediaExecutable::MeshImport(importer) = entry.executable else {
                return Err(HostMediaRuntimeError { code: "host-media.executable-kind".into(), message: format!("host-media target {:?} has no mesh executable", request.artifact_kind) });
            };
            importer(&request.mesh).map(|document| MeshImportResult { document }).map_err(|message| HostMediaRuntimeError { code: "host-media.mesh-import".into(), message })
        }

        fn two_d_svg_export(&self, request: &TwoDSvgExportRequest) -> Result<TwoDSvgExportResult, HostMediaRuntimeError> {
            let entry = self.lookup(HostMediaHandlerKind::TwoDSvgExport, &request.artifact_kind, &request.artifact_schema)?;
            let HostMediaExecutable::TwoDSvgExport(renderer) = entry.executable else {
                return Err(HostMediaRuntimeError { code: "host-media.executable-kind".into(), message: format!("host-media target {:?} has no 2D SVG executable", request.artifact_kind) });
            };
            let (svg, width, height) = renderer(&request.document).map_err(|message| HostMediaRuntimeError { code: "host-media.2d-svg".into(), message })?;
            Ok(TwoDSvgExportResult { file_stem: entry.descriptor.file_stem.clone().expect("2D SVG declaration requires a file stem"), svg, width, height })
        }

        fn lookup(&self, kind: HostMediaHandlerKind, artifact_kind: &str, artifact_schema: &str) -> Result<&RegisteredHostMediaHandler, HostMediaRuntimeError> {
            let kind_str = kind.as_str();
            let id = self.by_target.get(&(kind, artifact_kind.to_string())).ok_or_else(|| HostMediaRuntimeError { code: "host-media.not-declared".into(), message: format!("no {} declaration for artifact kind {:?}", kind_str, artifact_kind) })?;
            let entry = self.by_id.get(id).expect("host-media target index always points to an entry");
            if entry.descriptor.artifact_schema != artifact_schema {
                return Err(HostMediaRuntimeError {
                    code: "host-media.schema-mismatch".into(),
                    message: format!("host-media declaration {:?} expects schema {:?}, request supplied {:?}", entry.descriptor.id, entry.descriptor.artifact_schema, artifact_schema),
                });
            }
            Ok(entry)
        }
    }

    struct FlowExtensionRegistry {
        by_id: BTreeMap<String, FlowExtensionDescriptor>,
        by_extension_id: BTreeMap<String, String>,
    }

    impl FlowExtensionRegistry {
        fn new() -> Self {
            Self { by_id: BTreeMap::new(), by_extension_id: BTreeMap::new() }
        }

        fn from_declarations(owner: &str, declarations: &[FlowExtensionDeclaration]) -> Result<Self, PluginAssemblyError> {
            let mut registry = Self::new();
            for declaration in declarations {
                registry.register(owner, declaration)?;
            }
            Ok(registry)
        }

        fn register(&mut self, owner: &str, declaration: &FlowExtensionDeclaration) -> Result<(), PluginAssemblyError> {
            let descriptor = declaration.descriptor(owner);
            if let Some(existing) = self.by_id.get(&descriptor.id) {
                if existing == &descriptor {
                    return Ok(());
                }
                return Err(PluginAssemblyError::new("plugin-assembly.flow-extension-id", format!("flow extension contribution {:?} has a conflicting descriptor or executable identity", descriptor.id)));
            }
            if let Some(existing) = self.by_extension_id.get(&descriptor.extension_id) {
                return Err(PluginAssemblyError::new("plugin-assembly.flow-extension-target", format!("flow extension {:?} is already owned by {:?}", descriptor.extension_id, existing)));
            }
            self.by_extension_id.insert(descriptor.extension_id.clone(), descriptor.id.clone());
            self.by_id.insert(descriptor.id.clone(), descriptor);
            Ok(())
        }

        fn descriptors(&self) -> Vec<FlowExtensionDescriptor> {
            self.by_id.values().cloned().collect()
        }
    }
    //#endregion 🧭️RuntimeContributions

    /// 🧭️ One immutable plugin runtime catalogue assembled before any shared registry commit.
    pub(crate) struct ArtifactRegistrationPlan {
        schemas: Vec<::semio_framework_schema_registry::ArtifactSchemaDescriptor>,
        inferences: Vec<::semio_framework_schema_registry::ArtifactInferenceDescriptor>,
        inference_services: Vec<ArtifactInferenceService>,
        routed_inferences: Vec<ArtifactInferenceServiceMetadata>,
        formats: Vec<semio_framework::FormatDescriptor>,
        subset_validators: Vec<&'static SubsetValidatorEntry>,
        composers: Vec<&'static ComposerEntry>,
        languages: Vec<semio_framework_dsl::LanguageSpec>,
        document_codecs: Vec<store::ArtifactCodec>,
        native_snapshots: Vec<semio_framework::io::io_mechanism::NativeSnapshotRegistration>,
        migrations: Vec<store::DialectMigration>,
        schema_documents: Vec<::semio_framework_schema_registry::ScopeSchemaExports>,
        app_schemas: Vec<::semio_framework_schema_registry::AppSchemaDescriptor>,
        owner: String,
        host_media_handlers: Vec<HostMediaHandlerDeclaration>,
        flow_extensions: Vec<FlowExtensionDeclaration>,
    }

    impl ArtifactRegistrationPlan {
        /// 🧾️ Collects every channel of the owned `declarations` and of the `hosted` ones, except the hosted inference
        /// services: those stay listed and executed by their owner's assembly alone.
        pub(crate) fn from_declarations(
            declarations: &[ArtifactDeclaration],
            hosted: &[ArtifactDeclaration],
            app_schemas: Vec<::semio_framework_schema_registry::AppSchemaDescriptor>,
            foreign_document_codecs: &[DocumentCodecSpec],
            owner: impl Into<String>,
            host_media_handlers: Vec<HostMediaHandlerDeclaration>,
            flow_extensions: Vec<FlowExtensionDeclaration>,
            routed_inferences: Vec<ArtifactInferenceServiceMetadata>,
        ) -> Self {
            let mut plan = Self {
                schemas: Vec::new(),
                inferences: Vec::new(),
                inference_services: Vec::new(),
                routed_inferences,
                formats: Vec::new(),
                subset_validators: Vec::new(),
                composers: Vec::new(),
                languages: Vec::new(),
                document_codecs: Vec::new(),
                native_snapshots: Vec::new(),
                migrations: Vec::new(),
                schema_documents: Vec::new(),
                app_schemas,
                owner: owner.into(),
                host_media_handlers,
                flow_extensions,
            };
            for declaration in declarations {
                plan.inference_services.extend(declaration.inference_services.iter().copied());
            }
            for declaration in declarations.iter().chain(hosted) {
                plan.schemas.extend(declaration.schemas.iter().copied());
                plan.inferences.extend(declaration.inferences.iter().copied());
                plan.formats.extend(declaration.formats.iter().cloned());
                plan.subset_validators.extend(declaration.subset_validators.iter().copied());
                plan.composers.extend(declaration.composers.iter().copied());
                plan.languages.extend(declaration.languages.iter().map(|spec| **spec));
                for spec in declaration.document_codecs.iter() {
                    plan.document_codecs.push(spec.codec());
                    plan.native_snapshots.extend(semio_framework::io::io_mechanism::NativeSnapshotRegistration::from_capability(spec.dialect.into(), spec.codec()));
                }
                plan.migrations.extend(declaration.migrations.iter().cloned());
                plan.schema_documents.extend(declaration.schema_documents.iter().copied());
            }
            for spec in foreign_document_codecs.iter() {
                plan.document_codecs.push(spec.codec());
                plan.native_snapshots.extend(semio_framework::io::io_mechanism::NativeSnapshotRegistration::from_capability(spec.dialect.into(), spec.codec()));
            }
            plan
        }

        /// 🧬️ Freezes every definition, schema, app, language, and inference before external state changes.
        pub(crate) fn into_runtime(self, definitions: ArtifactDefinitionRegistry) -> Result<(PluginRuntimeRegistry, semio_framework::io::ArtifactAssemblyRegistryPlan), PluginAssemblyError> {
            let Self {
                schemas,
                inferences,
                inference_services: declared_inference_services,
                routed_inferences,
                formats,
                subset_validators,
                composers,
                languages,
                document_codecs,
                native_snapshots,
                migrations,
                schema_documents,
                app_schemas,
                owner,
                host_media_handlers,
                flow_extensions,
            } = self;
            let mut inference_services = ArtifactInferenceServiceRegistry::new();
            for service in &declared_inference_services {
                inference_services.register(*service).map_err(|error| PluginAssemblyError::new("plugin-assembly.inference", error.to_string()))?;
            }
            let mut inference_catalog: BTreeMap<ArtifactInferenceServiceKey, ArtifactInferenceServiceMetadata> = inference_services.metadata().into_iter().map(|metadata| (metadata.into(), metadata)).collect();
            for metadata in &routed_inferences {
                if metadata.owner != owner || metadata.artifact_kind.trim().is_empty() || metadata.artifact_schema.trim().is_empty() || metadata.artifact_schema.trim().is_empty() || metadata.inference_schema.trim().is_empty() {
                    return Err(PluginAssemblyError::new("plugin-assembly.routed-inference", format!("invalid routed inference metadata for {}/{}", metadata.artifact_kind, metadata.inference_schema)));
                }
                let key = (*metadata).into();
                if let Some(existing) = inference_catalog.get(&key) {
                    if existing != metadata {
                        return Err(PluginAssemblyError::new("plugin-assembly.routed-inference", format!("conflicting routed inference metadata for {}/{}", key.artifact_kind, key.inference_schema)));
                    }
                } else {
                    inference_catalog.insert(key, *metadata);
                }
            }
            let host_media_handlers = HostMediaHandlerRegistry::from_declarations(&owner, &host_media_handlers)?;
            let flow_extensions = FlowExtensionRegistry::from_declarations(&owner, &flow_extensions)?;
            semio_framework::io::io_mechanism::preflight_native_snapshots(&native_snapshots).map_err(|error| PluginAssemblyError::new("plugin-assembly.snapshot", error.to_string()))?;
            Ok((
                PluginRuntimeRegistry {
                    definitions,
                    schemas,
                    inferences,
                    schema_documents,
                    inference_services,
                    routed_inferences,
                    languages,
                    app_schemas,
                    host_media_handlers,
                    flow_extensions,
                    owner_mutations: BTreeMap::new(),
                    contributed_mutations: BTreeMap::new(),
                },
                semio_framework::io::ArtifactAssemblyRegistryPlan { composer_entries: composers, subset_validators, format_descriptors: formats, document_codecs, dialect_migrations: migrations, native_snapshots },
            ))
        }
    }

    /// 🧬️ Authoritative per-plugin runtime declarations. It is complete before global IO/store rows mutate.
    pub(crate) struct PluginRuntimeRegistry {
        definitions: ArtifactDefinitionRegistry,
        schemas: Vec<::semio_framework_schema_registry::ArtifactSchemaDescriptor>,
        inferences: Vec<::semio_framework_schema_registry::ArtifactInferenceDescriptor>,
        schema_documents: Vec<::semio_framework_schema_registry::ScopeSchemaExports>,
        inference_services: ArtifactInferenceServiceRegistry,
        routed_inferences: Vec<ArtifactInferenceServiceMetadata>,
        /// 🕳️ Collected at `into_runtime` time and never consumed. Languages: plugin inits also register grammars one by one
        /// (`dsl::register_language`, overwrite semantics, 51 sites) and the batch registry compares hook fn addresses, so
        /// publishing the declared set needs its own census first. App schemas: no OS-wide app-schema catalog exists yet.
        #[allow(dead_code, reason = "captured but unwired — see comment above")]
        languages: Vec<semio_framework_dsl::LanguageSpec>,
        #[allow(dead_code, reason = "captured but unwired — see comment above")]
        app_schemas: Vec<::semio_framework_schema_registry::AppSchemaDescriptor>,
        host_media_handlers: HostMediaHandlerRegistry,
        flow_extensions: FlowExtensionRegistry,
        owner_mutations: BTreeMap<String, WireMutationRosterEntry>,
        contributed_mutations: BTreeMap<String, ContributedMutationRuntimeEntry>,
    }

    impl PluginRuntimeRegistry {
        fn empty() -> Self {
            Self {
                definitions: ArtifactDefinitionRegistry::new(),
                schemas: Vec::new(),
                inferences: Vec::new(),
                schema_documents: Vec::new(),
                inference_services: ArtifactInferenceServiceRegistry::new(),
                routed_inferences: Vec::new(),
                languages: Vec::new(),
                app_schemas: Vec::new(),
                host_media_handlers: HostMediaHandlerRegistry::new(),
                flow_extensions: FlowExtensionRegistry::new(),
                owner_mutations: BTreeMap::new(),
                contributed_mutations: BTreeMap::new(),
            }
        }

        fn inference_services(&self) -> &ArtifactInferenceServiceRegistry {
            &self.inference_services
        }

        fn routed_inferences(&self) -> &[ArtifactInferenceServiceMetadata] {
            &self.routed_inferences
        }

        /// 🧾️ Reads the immutable definitions published by this plugin assembly.
        pub fn definitions(&self) -> &ArtifactDefinitionRegistry {
            &self.definitions
        }

        /// 📚️ Adds the plugin-level shared schema documents (`PluginBuilder::schema_documents`) to the ones
        /// [`Self::publish_declared_catalogs`] commits.
        pub(crate) fn share_schema_documents(&mut self, documents: Vec<::semio_framework_schema_registry::ScopeSchemaExports>) {
            self.schema_documents.extend(documents);
        }

        /// 📌️ Publishes the store's and io vocabulary's own schema documents, the declared shared schema documents, and the
        /// schema and inference descriptors the `.artifact(…)` declarations contributed into the OS-wide
        /// catalogs — the same two descriptor channels `commit_artifact_declarations` publishes for the declaration tree, each
        /// preflighted then committed, exact duplicates tolerated, a conflicting descriptor fatal. The snapshot-edit route
        /// resolves an editor's document schema there; unpublished, every stdio editor edit was refused
        /// `snapshot-edit.schema-unregistered`.
        pub(crate) fn publish_declared_catalogs(&self) -> Result<(), PluginAssemblyError> {
            let documents_error = |error: ::semio_framework_schema_registry::SchemaExportRegistryError| PluginAssemblyError::new("plugin-assembly.declaration-schema-documents", error.to_string());
            store::register_store_schema_exports().map_err(documents_error)?;
            store::io_schema::register_io_schema_exports().map_err(documents_error)?;
            for documents in &self.schema_documents {
                ::semio_framework_schema_registry::register_scope_schema_exports(*documents).map_err(documents_error)?;
            }
            ::semio_framework_schema_registry::register_artifact_schema_descriptors(self.schemas.clone()).map_err(|error| PluginAssemblyError::new("plugin-assembly.declaration-schema", error.to_string()))?;
            ::semio_framework_schema_registry::register_artifact_inference_descriptors(self.inferences.clone()).map_err(|error| PluginAssemblyError::new("plugin-assembly.declaration-inference", error.to_string()))
        }

        pub(crate) fn extend_contributions(
            &mut self,
            inference_services: Vec<ArtifactInferenceService>,
            owner_rosters: &[OwnerMutationRoster],
            contributed_mutations: Vec<(String, ContributedMutationRuntimeEntry)>,
        ) -> Result<(), PluginAssemblyError> {
            for service in inference_services {
                let metadata = service.metadata();
                if let Some(route) = self.routed_inferences.iter().find(|route| route.artifact_kind == metadata.artifact_kind && route.inference_schema == metadata.inference_schema) {
                    if route != &metadata {
                        return Err(PluginAssemblyError::new("plugin-assembly.contribution-inference", format!("contributed inference conflicts with routed inference {}/{}", metadata.artifact_kind, metadata.inference_schema)));
                    }
                }
                self.inference_services.register(service).map_err(|error| PluginAssemblyError::new("plugin-assembly.contribution-inference", error.to_string()))?;
            }
            for provider in owner_rosters {
                let (artifact_schema, kinds, input_schemas) = provider();
                for (index, descriptor) in kinds.iter().enumerate() {
                    let entry = WireMutationRosterEntry::owner(artifact_schema, descriptor, input_schemas.get(index).copied());
                    if let Some(existing) = self.owner_mutations.get(&entry.mutation_id) {
                        if existing != &entry {
                            return Err(PluginAssemblyError::new("plugin-assembly.owner-mutation-roster", format!("conflicting owner mutation roster entry for {:?}", entry.mutation_id)));
                        }
                    } else {
                        self.owner_mutations.insert(entry.mutation_id.clone(), entry);
                    }
                }
            }
            for (mutation_id, entry) in contributed_mutations {
                if let Some(existing) = self.contributed_mutations.get(&mutation_id) {
                    if existing.roster != entry.roster || !std::ptr::fn_addr_eq(existing.plan_cold, entry.plan_cold) {
                        return Err(PluginAssemblyError::new("plugin-assembly.contribution-mutation", format!("conflicting contributed mutation registration for {mutation_id:?}")));
                    }
                } else {
                    self.contributed_mutations.insert(mutation_id, entry);
                }
            }
            Ok(())
        }

        fn mutation_roster_entries(&self) -> Vec<WireMutationRosterEntry> {
            let mut entries: Vec<_> = self.owner_mutations.values().cloned().collect();
            entries.extend(self.contributed_mutations.values().map(|entry| entry.roster.clone()));
            entries.sort_by(|left, right| left.mutation_id.cmp(&right.mutation_id));
            entries
        }

        fn contributed_mutation_plan(&self, mutation_id: &str, artifact_kind: &str, snapshot_pack: &[u8], payload: &[u8]) -> Result<ContributedMutationPlanOutput, ContributedMutationExecutionError> {
            let entry = self.contributed_mutations.get(mutation_id).ok_or_else(|| ContributedMutationExecutionError::new("artifact-mutation.not-registered", format!("no contributed mutation service for {mutation_id:?}")))?;
            if entry.roster.artifact_kind.as_deref() != Some(artifact_kind) {
                return Err(ContributedMutationExecutionError::new("artifact-mutation.artifact-kind-mismatch", format!("mutation {mutation_id:?} targets {:?}, request claims {artifact_kind:?}", entry.roster.artifact_kind)));
            }
            (entry.plan_cold)(snapshot_pack, payload)
        }
    }

    /// 📌️ Atomically commits all external IO/store registry rows after the local runtime is frozen.
    pub(crate) fn commit_artifact_registration_plan(assembly: &store::ArtifactAssemblyTransaction, plan: semio_framework::io::ArtifactAssemblyRegistryPlan) -> Result<(), PluginAssemblyError> {
        semio_framework::io::commit_artifact_assembly_registry_plan(assembly, plan).map_err(|error| PluginAssemblyError::new("plugin-assembly.registry", error.to_string()))
    }
