            let hover = super::InteractionHoverState::new();
            let peers = super::PeerPresenceRoot::empty();
            E::handle(
                command,
                &super::ArtifactView::new(snapshot, &history),
                &super::ConfigView { snapshot: &config, window: None },
                &super::InteractionView { state: &state, hover: &hover, peers: &peers, draft_references: super::empty_draft_references() },
                None,
                &super::DraftView { snapshot: &draft },
                &semio_framework_2d::compute::EngineHandles::empty(),
            )
        }

        /// 👁️ Exercises the production ViewerApp adapter with a representative viewer command.
        /// The adapter must emit neither document nor draft mutations. A refusal emits nothing and so
        /// satisfies the law — a retained-route viewer refuses a direct `handle` by design. Command
        /// registration and admission are separate runtime contracts; a generic viewer fixture has no
        /// declared factory for its author-defined default command.
        ///
        /// 🧩️ Over the viewer's OWN roster (`V::Members`), never `new_viewer`'s `NoMembers`: the
        /// fixture forwards `genesis_child_pack`, so a viewer deriving composed children would
        /// otherwise refuse construction at `seed_genesis_children`.
        pub async fn assert_viewer_never_mutates<V>()
        where
            V: ArtifactViewer<Presence = super::NoPresence, PresenceMutation = super::NoPresenceMutation, Transient = super::NoTransient, TransientMutation = super::NoTransientMutation>,
            V::Command: Default,
        {
            use super::{ArtifactView, ConfigView, DraftView, InteractionHoverState, InteractionView, NoDraft, PeerPresenceRoot};
            let mut app: VcsArtifactApp<ViewerApp<BoundedViewerFixture<V>>, V::Members> = VcsArtifactApp::new(ViewerApp::<BoundedViewerFixture<V>>::default()).await;
            app.refresh_cache().await.expect("viewer fixture cache");
            let result = {
                let (_, snapshot, config, history) = app.cache.as_ref().expect("viewer fixture cache populated");
                let doc = ArtifactView::new(snapshot.as_ref(), history.as_ref());
                let cfg = ConfigView { snapshot: config.as_ref(), window: None };
                let draft = NoDraft::default();
                let draft = DraftView { snapshot: &draft };
                let state = protocol::InteractionState::default();
                let hover = InteractionHoverState::new();
                let peers = PeerPresenceRoot::empty();
                let interaction = InteractionView { state: &state, hover: &hover, peers: &peers, draft_references: super::empty_draft_references() };
                ViewerApp::<V>::handle(&V::Command::default(), &doc, &cfg, &interaction, None, &draft, &semio_framework_2d::compute::EngineHandles::empty()).await.map(|emit| (emit.artifact_mutations.is_empty(), emit.draft_mutations.is_empty()))
            };
            close_registered_fixture_app(&mut app);
            if let Ok((artifact_is_empty, draft_is_empty)) = result {
                assert!(artifact_is_empty, "a viewer must never emit document mutations");
                assert!(draft_is_empty, "a viewer must never emit draft mutations");
            }
        }

