    pub fn history_row_applied(has_parent_edit: bool, document_applied: bool, child_applied: bool) -> bool {
        if has_parent_edit {
            document_applied
        } else {
            child_applied
        }
    }

    impl<A: ArtifactApp, M: SpaceMember + MemberFactory + 'static> VcsArtifactApp<A, M> {
        #[cfg(test)]
        pub(crate) fn test_registered_tool_keys(&self) -> BTreeSet<(String, String)> {
            self.tool_jobs.keys().into_iter().map(|key| (key.controller_id, key.tool_id)).collect()
        }

