    pub fn install_plugin_bundle_result<PA: PluginApp>(runtime: &PluginRuntime<PA>, bundle: Result<Plugin<PA>, PluginAssemblyError>) {
        match bundle {
            Ok(bundle) => install_plugin_bundle(runtime, bundle),
            Err(error) => {
