        /// 🧷️ Keybinding-vs-action-registry consistency is only enforced for apps that declare
        /// actions via `.mutation()`/`.view_action()`/`.shell_action()` — apps with an empty action
        /// registry keybind directly against controller actions instead, so there is nothing to check.
        ///
        /// 🕰️ Unlike Document/Catalogue/Inspection/Parameters (per-app content, opt-in via
        /// `.panel_tab(...)`), the history panel's content is framework-generic (`HistoryView`), so
        /// every app gets it unconditionally — unless it already declared the reserved id itself.
        ///
        /// ⏯️ The framework ToolRun panel (contract §2.6) reaches the shell only as a panel tab: every app that
        /// declares a tool run gets it, so start/pause/step/abort/finalize, the progress bar and the step log are
        /// reachable — unless the app declared the reserved id itself.
        ///
        /// 🕹️ W3b: `transitive` (hover or selection) means "expand to descendant closure" — over
        ///
        /// `HierarchyProvider::Flat` there is no descendant relation to expand along at all, so a
        /// transitive `Flat` domain could only ever silently degrade to non-transitive behavior;
        /// reject it at build time instead.
        pub fn try_build_definition(mut self) -> Result<AppDefinition, PluginAssemblyError> {
            if !(!self.document.is_empty() && self.document.iter().all(|segment| !segment.trim().is_empty())) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} document must contain non-empty segments", self.id)));
            }
            for (terminology_id, document) in &self.terminology_breadcrumbs {
                if !(self.terminologies.iter().any(|id| id == terminology_id)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} declares terminology_document for undeclared terminology {}", self.id, terminology_id)));
                }
                if !(!document.is_empty() && document.iter().all(|segment| !segment.trim().is_empty())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} terminology_document for {} must contain non-empty segments", self.id, terminology_id)));
                }
            }
            if !(!self.window_kinds.is_empty()) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} must declare at least one window kind", self.id)));
            }
            if !(!self.modes.is_empty()) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} must declare at least one mode", self.id)));
            }
            let mut window_kind_ids = HashSet::new();
            for window in &self.window_kinds {
                if !(!window.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind id must be non-empty", self.id)));
                }
                if !(!window.body_key.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} body_key must be non-empty", self.id, window.id)));
                }
                if !(window_kind_ids.insert(window.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate window kind id {}", self.id, window.id)));
                }
            }
            let mut panel_tab_ids = HashSet::new();
            for tab in &self.panel_tabs {
                validate_panel_tab_spec(&self.id, tab, &mut panel_tab_ids);
            }
            if panel_tab_ids.insert(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_HISTORY_ID.to_string()) {
                self.panel_tabs.push(PanelTabSpec::framework(
                    PanelTabKind::App(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_HISTORY_ID.to_string()),
                    LocalizedLabel::native(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_HISTORY_LABEL, "Verlauf"),
                    PanelGroup::Settings,
                    Some(FRAMEWORK_HISTORY_BODY_KEY.to_string()),
                    Vec::new(),
                ));
            }
            let declares_tool_run = self.tools.iter().any(|tool| tool.run.is_some()) || self.utilities.iter().any(|utility| utility.run.is_some());
            if declares_tool_run && panel_tab_ids.insert(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_TOOL_RUN_ID.to_string()) {
                self.panel_tabs.push(PanelTabSpec::framework(
                    PanelTabKind::App(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_TOOL_RUN_ID.to_string()),
                    LocalizedLabel::native(ui_wgpu::wgpu::FRAMEWORK_PANEL_TAB_TOOL_RUN_LABEL, "Werkzeugläufe"),
                    PanelGroup::Details,
                    Some(FRAMEWORK_TOOL_RUN_BODY_KEY.to_string()),
                    Vec::new(),
                ));
            }
            let mut layout_window_ids = Vec::new();
            if let Some(layout) = &self.default_layout {
                layout_window_ids.extend(collect_window_kind_ids_from_layout(layout));
            }
            for named in &self.named_layouts {
                layout_window_ids.extend(collect_window_kind_ids_from_layout(&named.layout));
            }
            for window_kind_id in layout_window_ids {
                if !(window_kind_ids.contains(&window_kind_id)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} layout references undeclared window kind {}", self.id, window_kind_id)));
                }
            }
            let default_mode_id = self.default_mode_id.clone().unwrap_or_else(|| self.modes[0].id.clone());
            if !(self.modes.iter().any(|mode| mode.id == default_mode_id)) {
                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} default_mode_id {} does not reference a declared mode", self.id, default_mode_id)));
            }
            let mut declared_action_ids = HashSet::new();
            for action in &self.actions {
                if !(declared_action_ids.insert(action.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate action id {}", self.id, action.id)));
                }
                validate_arg_defs(&self.id, &format!("action {}", action.id), &action.args);
            }
            for action in self.actions.iter().chain(self.window_kinds.iter().flat_map(|window| window.actions.iter())) {
                if let Some(expected) = semio_framework::framework_fixed_audience_violation(action) {
                    return Err(PluginAssemblyError::new(
                        "app-definition.invalid",
                        format!("app {} declares the framework gumball verb {} with audience {:?}; the one rule for every gumball user is {:?}", self.id, action.id, semio_framework::resolve_audience(action), expected),
                    ));
                }
            }
            let mut declared_utility_ids = HashSet::new();
            for utility in &self.utilities {
                if !(!utility.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} utility id must be non-empty", self.id)));
                }
                if !(declared_utility_ids.insert(utility.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate utility id {}", self.id, utility.id)));
                }
            }
            let mut declared_interaction_ids = HashSet::new();
            for interaction in &self.interactions {
                if !(!interaction.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction id must be non-empty", self.id)));
                }
                if !(declared_interaction_ids.insert(interaction.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate interaction id {}", self.id, interaction.id)));
                }
                if !(!interaction.granularities.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one granularity", self.id, interaction.id)));
                }
                if !(!interaction.selection.modes.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one selection mode", self.id, interaction.id)));
                }
                if !(!interaction.selection.methods.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one selection method", self.id, interaction.id)));
                }
                if !(!interaction.selection.merges.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} must declare at least one merge mode", self.id, interaction.id)));
                }
                if !(!interaction.hover.transitive || !matches!(interaction.hierarchy, semio_framework::HierarchyProvider::Flat)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} declares hover.transitive with HierarchyProvider::Flat (transitive requires a real hierarchy)", self.id, interaction.id)));
                }
                if !(!interaction.selection.transitive || !matches!(interaction.hierarchy, semio_framework::HierarchyProvider::Flat)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} interaction {} declares selection.transitive with HierarchyProvider::Flat (transitive requires a real hierarchy)", self.id, interaction.id)));
                }
            }
            let entity_kinds = self.interactions.iter().flat_map(|interaction| interaction.granularities.iter().map(|granularity| semio_framework::interaction_entity_kind(&interaction.id, &granularity.id))).collect::<HashSet<_>>();
            for action in self.actions.iter().chain(self.window_kinds.iter().flat_map(|window| window.actions.iter())) {
                if let Some(entity_kind) = action.args.iter().flat_map(|arg| arg.schema.entity_kinds()).find(|entity_kind| !entity_kinds.contains(*entity_kind)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} action {} names entity kind {entity_kind}, which no granularity of a declared interaction answers", self.id, action.id)));
                }
            }
            let mut declared_tool_ids = HashSet::new();
            for tool in &self.tools {
                if !(!tool.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tool id must be non-empty", self.id)));
                }
                if !(declared_tool_ids.insert(tool.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate tool id {}", self.id, tool.id)));
                }
            }
            let mut declared_command_ids = HashSet::new();
            for command in &self.commands {
                if !(!command.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} command id must be non-empty", self.id)));
                }
                if !(declared_command_ids.insert(command.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate app command id {}", self.id, command.id)));
                }
                validate_arg_defs(&self.id, &format!("command {}", command.id), &command.args);
            }
            let (dialect, role) = semio_framework::parse_surface_app_id(&self.id).map_err(|error| PluginAssemblyError::new("app-definition.invalid", format!("app id {} must be a canonical surface id: {error}", self.id)))?;
            let app_declared_actions = !self.actions.is_empty();
            let mut actions = self.actions;
            for framework_action in history_action_definitions().into_iter().chain(clipboard_action_definitions()).filter(|action| role != AppRole::Viewer || !viewer_rejects_action(&action.id)) {
                if declared_action_ids.insert(framework_action.id.clone()) {
                    actions.push(framework_action);
                }
            }
            if !self.utilities.is_empty() && declared_action_ids.insert(SET_ACTIVE_UTILITY_ACTION_ID.to_string()) {
                actions.push(set_active_utility_action_definition());
            }
            if !self.tools.is_empty() && declared_action_ids.insert(SET_ACTIVE_TOOL_ACTION_ID.to_string()) {
                actions.push(set_active_tool_action_definition());
            }
            if self.introduction.is_some() && declared_action_ids.insert(START_INTRODUCTION_ACTION_ID.to_string()) {
                actions.push(start_introduction_action_definition());
            }
            if !self.tutorials.is_empty() && declared_action_ids.insert(START_TUTORIAL_ACTION_ID.to_string()) {
                actions.push(start_tutorial_action_definition(&self.tutorials));
            }
            if declared_action_ids.insert(RECORD_TUTORIAL_ACTION_ID.to_string()) {
                actions.push(record_tutorial_action_definition());
            }
            if declared_action_ids.insert(SET_HISTORY_COMMAND_FILTER_ACTION_ID.to_string()) {
                actions.push(set_history_command_filter_action_definition());
            }
            if declared_action_ids.insert(NOTE_SHELL_COMMAND_ACTION_ID.to_string()) {
                actions.push(note_shell_command_action_definition());
            }
            let explicitly_owned_action_ids: HashSet<String> = self.window_kinds.iter().flat_map(|window| window.actions.iter().map(|action| action.id.clone()).chain(window.action_refs.iter().map(|action| action.as_str().to_string()))).collect();
            for window in &mut self.window_kinds {
                for action_ref in &window.action_refs {
                    let action = actions
                        .iter()
                        .find(|action| action.id == action_ref.as_str())
                        .ok_or_else(|| PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} references undeclared action {}", self.id, window.id, action_ref.as_str())))?;
                    window.actions.push(action.clone());
                }
                let mut window_action_ids = HashSet::new();
                for action in &window.actions {
                    if !(!action.id.trim().is_empty()) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} action id must be non-empty", self.id, window.id)));
                    }
                    if !(window_action_ids.insert(action.id.clone())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} duplicate action id {}", self.id, window.id, action.id)));
                    }
                    declared_action_ids.insert(action.id.clone());
                    validate_arg_defs(&self.id, &format!("window kind {} action {}", window.id, action.id), &action.args);
                }
            }
            let app_roster: Vec<ActionDefinition> = actions.iter().filter(|action| !explicitly_owned_action_ids.contains(&action.id)).cloned().collect();
            let mut bound_keys: HashSet<String> = self.keybindings.iter().map(|binding| binding.keys.clone()).collect();
            let mut keybindings: Vec<Keybinding> =
                self.keybindings.into_iter().map(|binding| Keybinding { keys: binding.keys, action: KeybindingActionDescriptor { controller_id: binding.controller_id, action: binding.action, args: None } }).collect();
            for history_action in actions.iter().filter(|action| matches!(action.kind, ActionKind::History | ActionKind::Clipboard)) {
                if let Some(keys) = &history_action.keys {
                    if bound_keys.insert(keys.clone()) {
                        keybindings.push(Keybinding { keys: keys.clone(), action: KeybindingActionDescriptor { controller_id: self.controller_id.clone(), action: history_action.id.clone(), args: None } });
                    }
                }
            }
            for utility in &self.utilities {
                if let Some(keys) = &utility.keys {
                    if bound_keys.insert(keys.clone()) {
                        keybindings.push(Keybinding {
                            keys: keys.clone(),
                            action: KeybindingActionDescriptor {
                                controller_id: self.controller_id.clone(),
                                action: SET_ACTIVE_UTILITY_ACTION_ID.to_string(),
                                args: Some(semio_framework_value::DslValue::Object(vec![("utilityId".into(), semio_framework_value::DslValue::String(utility.id.clone()))])),
                            },
                        });
                    }
                }
            }
            for tool in &self.tools {
                if let Some(keys) = &tool.keys {
                    if bound_keys.insert(keys.clone()) {
                        keybindings.push(Keybinding {
                            keys: keys.clone(),
                            action: KeybindingActionDescriptor { controller_id: self.controller_id.clone(), action: SET_ACTIVE_TOOL_ACTION_ID.to_string(), args: Some(semio_framework_value::DslValue::Object(vec![("toolId".into(), semio_framework_value::DslValue::String(tool.id.clone()))])) },
                        });
                    }
                }
            }
            if app_declared_actions {
                for binding in &keybindings {
                    if !(declared_action_ids.contains(&binding.action.action)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} keybinding {} references undeclared action {}", self.id, binding.keys, binding.action.action)));
                    }
                }
            }
            for window in &self.window_kinds {
                for utility_ref in &window.utilities {
                    let utility_ref_str = utility_ref.as_str();
                    if !(declared_utility_ids.contains(utility_ref_str)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} references undeclared utility {}", self.id, window.id, utility_ref_str)));
                    }
                }
                for interaction_ref in &window.interactions {
                    let interaction_ref_str = interaction_ref.as_str();
                    if !(declared_interaction_ids.contains(interaction_ref_str)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} window kind {} references undeclared interaction {}", self.id, window.id, interaction_ref_str)));
                    }
                }
            }
            for mode in &self.modes {
                let mut mode_command_ids = HashSet::new();
                for command in &mode.commands {
                    if !(!command.id.trim().is_empty()) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} mode {} command id must be non-empty", self.id, mode.id)));
                    }
                    if !(mode_command_ids.insert(command.id.clone())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} mode {} duplicate command id {}", self.id, mode.id, command.id)));
                    }
                    declared_command_ids.insert(command.id.clone());
                    validate_arg_defs(&self.id, &format!("mode {} command {}", mode.id, command.id), &command.args);
                }
                for tool_ref in &mode.tools {
                    if !(declared_tool_ids.contains(tool_ref.as_str())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} mode {} references undeclared tool {}", self.id, mode.id, tool_ref.as_str())));
                    }
                }
            }
            let mode_referenced_tools: HashSet<&str> = self.modes.iter().flat_map(|mode| mode.tools.iter().map(|tool_ref| tool_ref.as_str())).collect();
            for tool in &self.tools {
                if !(mode_referenced_tools.contains(tool.id.as_str())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tool {} is not referenced by any mode", self.id, tool.id)));
                }
            }
            if let Some(introduction) = &self.introduction {
                if !(!introduction.steps.is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction must declare at least one step", self.id)));
                }
                let mut step_ids = HashSet::new();
                for step in &introduction.steps {
                    if !(!step.id.trim().is_empty()) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step id must be non-empty", self.id)));
                    }
                    if !(step_ids.insert(step.id.clone())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate introduction step id {}", self.id, step.id)));
                    }
                    let step_context = format!("introduction step {}", step.id);
                    if let Some(id) = &step.introduce {
                        validate_referenced_element_id(&self.id, &step_context, "introduce", id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids);
                    }
                    for id in &step.show {
                        validate_referenced_element_id(&self.id, &step_context, "show", id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids);
                    }
                    for interaction in &step.interactions {
                        if !(!interaction.label.trim().is_empty()) {
                            return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction has an empty label", self.id, step.id)));
                        }
                        match &interaction.on {
                            IntroductionInteractionKind::Action(action_ref) => {
                                let action_ref_str = action_ref.as_str();
                                if !(declared_action_ids.contains(action_ref_str)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared action {}", self.id, step.id, action_ref_str)));
                                }
                            }
                            IntroductionInteractionKind::Utility(utility_ref) => {
                                let utility_ref_str = utility_ref.as_str();
                                if !(declared_utility_ids.contains(utility_ref_str)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared utility {}", self.id, step.id, utility_ref_str)));
                                }
                            }
                            IntroductionInteractionKind::Tool(tool_ref) => {
                                let tool_ref_str = tool_ref.as_str();
                                if !(declared_tool_ids.contains(tool_ref_str)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared tool {}", self.id, step.id, tool_ref_str)));
                                }
                            }
                            IntroductionInteractionKind::Panel(panel_tab_id) => validate_referenced_element_id(&self.id, &step_context, "interaction.panel", panel_tab_id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids),
                            IntroductionInteractionKind::Expand(tree_id) => validate_referenced_element_id(&self.id, &step_context, "interaction.expand", tree_id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids),
                            IntroductionInteractionKind::Pan(window_kind_id) | IntroductionInteractionKind::Zoom(window_kind_id) | IntroductionInteractionKind::Orbit(window_kind_id) => {
                                if !(window_kind_ids.contains(window_kind_id)) {
                                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} introduction step {} interaction references undeclared window kind {}", self.id, step.id, window_kind_id)));
                                }
                            }
                        }
                    }
                }
            }
            let mut tutorial_ids = HashSet::new();
            for tutorial in &self.tutorials {
                if !(!tutorial.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tutorial id must be non-empty", self.id)));
                }
                if !(tutorial_ids.insert(tutorial.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate tutorial id {}", self.id, tutorial.id)));
                }
                if let Err(reason) = semio_framework::validate_tutorial(tutorial) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} tutorial {} failed validation: {}", self.id, tutorial.id, reason)));
                }
                let owner = format!("tutorial {}", tutorial.id);
                let mut ui_changes: Vec<&semio_framework::TutorialUiChange> = Vec::new();
                for keyframe in &tutorial.tracks.ui {
                    if let semio_framework::TutorialUiSample::Delta { changes } = &keyframe.sample {
                        ui_changes.extend(changes.iter());
                    }
                }
                for change in ui_changes {
                    match change {
                        semio_framework::TutorialUiChange::ActiveUtility { utility_id: Some(utility_id), .. } if !declared_utility_ids.contains(utility_id) => {
                            return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} references undeclared utility {}", self.id, owner, utility_id)));
                        }
                        semio_framework::TutorialUiChange::ActiveTool { id: Some(tool_id) } if !declared_tool_ids.contains(tool_id) => {
                            return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} references undeclared tool {}", self.id, owner, tool_id)));
                        }
                        _ => {}
                    }
                }
                for utility_id in tutorial.base.ui.active_utility_by_window_id.values() {
                    if !(declared_utility_ids.contains(utility_id)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} base.ui references undeclared utility {}", self.id, owner, utility_id)));
                    }
                }
                if let Some(tool_id) = &tutorial.base.ui.active_tool_id {
                    if !(declared_tool_ids.contains(tool_id)) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} base.ui references undeclared tool {}", self.id, owner, tool_id)));
                    }
                }
                for event in &tutorial.tracks.events {
                    match &event.kind {
                        semio_framework::TutorialEventKind::Action { action, .. } => {
                            if !(declared_action_ids.contains(action)) {
                                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} event references undeclared action {}", self.id, owner, action)));
                            }
                        }
                        semio_framework::TutorialEventKind::Command { command, .. } => {
                            if !(declared_command_ids.contains(command)) {
                                return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} {} event references undeclared command {}", self.id, owner, command)));
                            }
                        }
                        semio_framework::TutorialEventKind::Key { .. } => {}
                    }
                }
                for gesture_cue in &tutorial.tracks.gestures {
                    for point in introduction_gesture_points(&gesture_cue.gesture) {
                        if let semio_framework::IntroductionPoint::Element { id, .. } = point {
                            validate_referenced_element_id(&self.id, &owner, "gesture", id, &declared_utility_ids, &panel_tab_ids, &window_kind_ids);
                        }
                    }
                }
            }
            if role != AppRole::Viewer && !self.dialogs.iter().any(|dialog| dialog.id == semio_framework::HISTORY_EDIT_FINALIZE_DIALOG_ID) {
                self.dialogs.push(semio_framework::history_edit_finalize_dialog());
            }
            let mut dialog_ids = HashSet::new();
            for dialog in &self.dialogs {
                if !(!dialog.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog id must be non-empty", self.id)));
                }
                if !(dialog_ids.insert(dialog.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate dialog id {}", self.id, dialog.id)));
                }
                if !(declared_action_ids.contains(dialog.submit_action.as_str())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog {} submit_action references undeclared action {}", self.id, dialog.id, dialog.submit_action.as_str())));
                }
                if let Some(cancel_action) = &dialog.cancel_action {
                    if !(declared_action_ids.contains(cancel_action.as_str())) {
                        return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog {} cancel_action references undeclared action {}", self.id, dialog.id, cancel_action.as_str())));
                    }
                }
                if let Err(reason) = dialog.validate_choices() {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog {} {reason}", self.id, dialog.id)));
                }
                if let Some(choice) = dialog.choices.iter().find(|choice| !declared_action_ids.contains(choice.action.as_str())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} dialog {} choice {} references undeclared action {}", self.id, dialog.id, choice.id, choice.action.as_str())));
                }
                validate_arg_defs(&self.id, &format!("dialog {}", dialog.id), &dialog.args);
            }
            let mut media_port_ids = HashSet::new();
            for port in self.media_inputs.iter().chain(self.media_outputs.iter()) {
                if !(!port.id.trim().is_empty()) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media port id must be non-empty", self.id)));
                }
                if !(media_port_ids.insert(port.id.clone())) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} duplicate media port id {}", self.id, port.id)));
                }
            }
            for port in &self.media_inputs {
                if !(port.direction == MediaPortDirection::In) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media input {} must declare direction In", self.id, port.id)));
                }
            }
            for port in &self.media_outputs {
                if !(port.direction == MediaPortDirection::Out) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media output {} must declare direction Out", self.id, port.id)));
                }
                if !(!matches!(port.media_type.form, MediaForm::Any)) {
                    return Err(PluginAssemblyError::new("app-definition.invalid", format!("app {} media output {} must not declare MediaForm::Any (Any is only legal on inputs, see media_types_compatible)", self.id, port.id)));
                }
            }
            let classification_result = semio_framework::validate_interactive_job_classification(
                actions.iter().map(|action| (self.id.as_str(), action)).chain(self.window_kinds.iter().flat_map(|window| window.actions.iter().map(move |action| (window.id.as_str(), action)))),
                self.commands.iter().map(|command| (self.id.as_str(), command)).chain(self.modes.iter().flat_map(|mode| mode.commands.iter().map(move |command| (mode.id.as_str(), command)))),
            );
            if let Err(errors) = classification_result {
                let message = errors.into_iter().map(|error| error.to_string()).collect::<Vec<_>>().join("; ");
                return Err(PluginAssemblyError::new("app-definition.interactive-job-classification", message));
            }
            let mut definition = AppDefinition {
                id: self.id,
                role,
                dialect,
                label: self.label,
                breadcrumb: self.document,
                icon_id: self.icon_id,
                controller_id: self.controller_id,
                modes: Modes::try_from(self.modes.into_iter().map(|mode| ModeDefinition { id: mode.id, label: mode.label, icon_id: mode.icon_id, tools: mode.tools, layout_id: mode.layout_id, commands: mode.commands }).collect::<Vec<_>>())
                    .map_err(|_| PluginAssemblyError::new("app-definition.invalid", "app definition must declare at least one mode (checked above)"))?,
                default_mode_id,
                window_kinds: WindowKinds::try_from(
                    self.window_kinds
                        .into_iter()
                        .map(|window| WindowKindDefinition {
                            id: window.id,
                            label: window.label,
                            body_key: window.body_key,
                            surface_kind: legacy_surface_kind(window.surface_kind),
                            icon_id: window.icon_id,
                            options: WindowOptions { measures: window.measures, engagement: window.engagement.map_or(WindowEngagementSlot::None, WindowEngagementSlot::Some) },
                            actions: window.actions,
                            utilities: window.utilities,
                            interactions: window.interactions,
                            params_schema: window.params_schema,
                            artifact_snapshot_schema: window.artifact_snapshot_schema,
                            input_event_schema: window.input_event_schema,
                            output_schema: window.output_schema,
                            capabilities: window.capabilities,
                        })
                        .collect::<Vec<_>>(),
                )
                .map_err(|_| PluginAssemblyError::new("app-definition.invalid", "app definition must declare at least one window kind (checked above)"))?,
                actions: app_roster,
                panel_tabs: self.panel_tabs.into_iter().map(panel_tab_spec_to_definition).collect(),
                keybindings,
                utilities: self.utilities,
                interactions: self.interactions,
                tools: self.tools,
                commands: self.commands,
                named_layouts: self.named_layouts,
                default_layout: self.default_layout,
                terminologies: self.terminologies,
                terminology_breadcrumbs: self.terminology_breadcrumbs,
                introduction: self.introduction,
                tutorials: self.tutorials,
                dialogs: self.dialogs,
                media_inputs: self.media_inputs,
                media_outputs: self.media_outputs,
                artifact_kinds: self.artifact_kinds,
                config: self.config,
                command_grammar: self.command_grammar,
                io: self.io,
                fault_notices: Vec::new(),
            };
            for action in semio_framework::interaction_action_definitions(&definition)
                .into_iter()
                .chain(semio_framework::tool_run_action_definitions(&definition))
                .chain([crate::app::operation_progress::cancellation_action_definition(), semio_framework::host_event_action_definition()])
                .chain(semio_framework::document_transfer_action_definitions())
            {
                if declared_action_ids.insert(action.id.clone()) {
                    if let Some(keys) = &action.keys {
                        if bound_keys.insert(keys.clone()) {
                            definition.keybindings.push(Keybinding { keys: keys.clone(), action: KeybindingActionDescriptor { controller_id: definition.controller_id.clone(), action: action.id.clone(), args: None } });
                        }
                    }
                    for window in definition.window_kinds.iter_mut() {
                        if !window.actions.iter().any(|entry| entry.id == action.id) {
                            window.actions.push(action.clone());
                        }
                    }
                }
            }
            Ok(definition)
        }

        /// 🧷️ Panicking convenience wrapper over `try_build_definition` for callers that construct
        /// `AppDefinition`s from static, author-controlled data (the overwhelming majority) and are
        /// not yet migrated onto the fallible path — a malformed definition here is a programming
        /// error, not runtime user input, and existing tests already assert on the panic message.
        /// Plugin `plugin()` entry points that assemble an `AppDefinition` from anything that could
        /// legitimately fail at runtime should call `try_build_definition` directly and propagate the
        /// `PluginAssemblyError` via `?` instead — see `✏️s/🔌️plugins/📖️playbook/🧩️extensions/🌀️procedural/🦀️.rs`.
        pub fn build_definition(self) -> AppDefinition {
            self.try_build_definition().unwrap_or_else(|error| panic!("{error}"))
        }
    }

    //#region 🔖️PanelKit
    // 🌳️ Shared panel-tree builders — lifts the verbatim-duplicated `tree_item*`/`selection_ids` helpers
    // and the `build_document_tree`/`build_inspector_tree`/`build_catalogue_tree` skeleton found across
    // ~15 plugin crates (flow, procedural, layout, gis, puzzle, sequence, trinity, dag, …) into the SDK.

    /// 🌳️ A bare tree item — thin wrapper over [`ui::tree_item`], `id` becoming the row's own key.
    pub fn tree_item<I: AsRef<str>, L: TryInto<Label>>(id: I, label: L) -> UiAssemblyResult<BuiltNode> {
        let builder = ui::tree_item(ui_label(label, "tree-item.label")?);
        let builder = builder.try_id(id).map_err(|_| ui_assembly_error("tree-item.id"))?;
        builder.try_build().map_err(|_| ui_assembly_error("tree-item.build"))
    }

    /// 🌳️ A tree item with a description line.
    pub fn tree_item_desc<I: AsRef<str>, L: TryInto<Label>>(id: I, label: L, description: Option<String>) -> UiAssemblyResult<BuiltNode> {
        let builder = ui::tree_item(ui_label(label, "tree-item-description.label")?);
        let mut builder = builder.try_id(id).map_err(|_| ui_assembly_error("tree-item-description.id"))?;
        if let Some(description) = description {
            builder = builder.description(ui_text(description, "tree-item-description.description")?);
        }
        builder.try_build().map_err(|_| ui_assembly_error("tree-item-description.build"))
    }

    /// 🌳️ A non-interactive grouping row that owns nested children — a disclosure header inside a
    /// section. It binds no action and carries no argument map, so unlike an interactive row it costs
    /// nothing of the process-wide `UiValue` arena (see [`TreeWindows`]): grouping a windowed listing
    /// by category is free, only the leaf rows are charged.
    pub fn tree_group<I: AsRef<str>, L: TryInto<Label>>(id: I, label: L, default_open: bool, children: UiFixedList<BuiltNode>) -> UiAssemblyResult<BuiltNode> {
        let builder = ui::tree_item(ui_label(label, "tree-group.label")?);
        let builder = builder.try_id(id).map_err(|_| ui_assembly_error("tree-group.id"))?.default_open(default_open);
        builder.try_children(children).map_err(|_| ui_assembly_error("tree-group.children"))?.try_build().map_err(|_| ui_assembly_error("tree-group.build"))
    }

    /// 🌳️ A tree item that dispatches `action` on activation while preserving its typed args — the row's ONE target,
    /// the action's verb its activation.
    pub fn tree_item_with_action<I: AsRef<str>, L: TryInto<Label>>(id: I, label: L, description: Option<String>, action: (ActionId, Option<UiValue>)) -> UiAssemblyResult<BuiltNode> {
        let builder = ui::tree_item(ui_label(label, "tree-item-action.label")?);
        let mut builder = builder.try_id(id).map_err(|_| ui_assembly_error("tree-item-action.id"))?.target(activation_target(action)?);
        if let Some(description) = description {
            builder = builder.description(ui_text(description, "tree-item-action.description")?);
        }
        builder.try_build().map_err(|_| ui_assembly_error("tree-item-action.build"))
    }

    /// 🌳️ A draggable tree item: `drag_data` is a JSON object whose entries become the item's
    /// MIME-type -> payload drag-data map (string values are used verbatim; non-string values are
    /// serialized), e.g. `json!({ "application/x-my-widget": descriptor.to_string() })`. Generalizes the
    /// single-hardcoded-MIME-key pattern duplicated per app (each app previously baked its own MIME
    /// constant into this function) — the caller now supplies the key(s) explicitly.
    pub fn tree_item_with_action_draggable<I: AsRef<str>, L: TryInto<Label>>(id: I, label: L, description: Option<String>, action: (ActionId, Option<UiValue>), drag_data: &semio_framework_pack_json::Value) -> UiAssemblyResult<BuiltNode> {
        let builder = ui::tree_item(ui_label(label, "draggable-tree-item.label")?);
        let mut builder = builder.try_id(id).map_err(|_| ui_assembly_error("draggable-tree-item.id"))?.target(activation_target(action)?).draggable(true);
        if let Some(description) = description {
            builder = builder.description(ui_text(description, "draggable-tree-item.description")?);
        }
        if let Some(entries) = drag_data.as_object() {
            let mut fixed = UiFixedMap::default();
            let mut last = UiText::default();
            while fixed.len() < entries.len() {
                let Some((key, value)) = entries.iter().filter(|(key, _)| *key > last.as_str()).min_by_key(|(key, _)| *key) else { break };
                let key = ui_text(key.to_string(), "draggable-tree-item.drag-key")?;
                let value = ui_text(value.as_str().map_or_else(|| value.to_string(), str::to_string), "draggable-tree-item.drag-value")?;
                last = key.clone();
                fixed.try_push(key, value).map_err(|_| ui_assembly_error("draggable-tree-item.drag-data"))?;
            }
            if fixed.len() != entries.len() {
                return Err(ui_assembly_error("draggable-tree-item.drag-data"));
            }
            builder = builder.drag_data(fixed);
        }
        builder.try_build().map_err(|_| ui_assembly_error("draggable-tree-item.build"))
    }

    /// 🎯️ Parses a selection-action's `ids` array arg into a plain `Vec<String>` — the one selection-argument shape
    /// every app's selection actions accept.
    pub fn selection_ids(args: Option<&DslValue>) -> Vec<String> {
        args.and_then(|value| value.get("ids")).and_then(semio_framework_value::DslValue::as_array).and_then(|items| items.iter().map(|item| item.as_str().map(str::to_string)).collect::<Option<Vec<String>>>()).unwrap_or_default()
    }

    /// 🌳️ Fluent builder for the `build_document_tree`/`build_inspector_tree`/`build_catalogue_tree`
    /// skeleton duplicated across plugin crates: namespaced item ids, sections (optionally substituting a
    /// single "(none)" placeholder item for the empty state), a selected/highlighted id set, an
    /// `interaction_domain` binding, and a drop action — ending in `.build()` -> a [`BuiltNode`] (a
    /// `Component::Tree`; wrap with the crate's own `built_to_tree` + `ComponentTree::new` at the one
    /// place `Present::present` actually returns, per `📓️recipe-plugin.md` §5).
    ///
    /// ⚠️ Gap (SEMANTIC-UI-CONTRACT-AND-RENDERER-FAMILY packet `sdk-helpers` — see
    /// `📓️terra-sdk-helpers-report.md`): `.selected()`/`.highlighted()` used to stamp
    /// `presence.selected`/`.hovered` directly onto matching items via the old `ui_tree_stamp_presence`.
    /// That field no longer exists on a built node — selection/hover is now
    /// `semio_framework_ui_contract::PresenceUpdate`, a separate TTL-scoped channel published through a
    /// live `transact()` call this SDK layer does not have (`📓️recipe-plugin.md` §6; `sdk-flip`'s own
    /// decision 1 — the reactor embeds `SurfaceReconciler` only, not the full `UiRuntime` a
    /// `PresenceHub` publish needs). `selected_ids`/`highlighted_ids` are still recorded here — a
    /// future packet wiring a real per-app `Present`/`HandleIntent` can read them straight off this
    /// builder to publish the equivalent `PresenceUpdate` — but `.build()` cannot render them onto the
    /// tree this wave. Framework-owned interaction-domain trees lose the identical capability at
    /// `stamp_and_cache_interaction_ui`, for the identical reason — see that method's own doc comment.
    pub struct PanelTreeBuilder {
        namespace: UiText,
        sections: UiFixedList<BuiltNode>,
        selected_ids: Option<UiFixedList<UiText>>,
        highlighted_ids: Option<UiFixedList<UiText>>,
        interaction_domain: Option<UiText>,
        interaction_select: Option<(ActionId, Option<UiValue>)>,
        drop_action: Option<ActionId>,
    }

    impl PanelTreeBuilder {
        /// 🌳️ `namespace` prefixes every id built via `.item_id()`, e.g. `"flow-play-document"`.
        pub fn new(namespace: impl TryInto<UiText>) -> UiAssemblyResult<Self> {
            Ok(Self { namespace: ui_text(namespace, "panel-tree.namespace")?, sections: UiFixedList::default(), selected_ids: None, highlighted_ids: None, interaction_domain: None, interaction_select: None, drop_action: None })
        }

        /// 🌳️ Builds a namespaced item id: `"{namespace}.{kind}.{id}"`.
        pub fn item_id(&self, kind: &str, id: &str) -> UiAssemblyResult<UiText> {
            UiText::try_format(format_args!("{}.{kind}.{id}", self.namespace)).ok_or_else(|| ui_assembly_error("panel-tree.item-id"))
        }

        /// 🌳️ Adds a section verbatim. ⚠️ Its rows are OUTSIDE the [`TreeWindows`] node ledger — see
        /// that type and [`TREE_WINDOW_FIXED_NODE_HEADROOM`] — so this spelling is for small fixed
        /// lists only; an entity list belongs on [`Self::window_section`].
        /// ⚠️ Decision: a `None` label becomes an empty [`Label`] —
        /// [`ui::tree_section`] has no optional-label constructor; [`TreeSectionProps::label`] itself
        /// stays `Option` on the record, so only this convenience path loses the "omit entirely"
        /// spelling.
        pub fn section<I: AsRef<str>>(mut self, id: I, label: Option<Label>, default_open: bool, items: UiFixedList<BuiltNode>) -> UiAssemblyResult<Self> {
            let builder = tree_section(label.unwrap_or_default()).default_open(default_open);
            let builder = builder.try_id(id).map_err(|_| ui_assembly_error("panel-tree.section-id"))?;
            let builder = builder.try_children(items).map_err(|_| ui_assembly_error("panel-tree.section-items"))?;
            let node = builder.try_build().map_err(|_| ui_assembly_error("panel-tree.section-build"))?;
            self.sections.try_push(node).map_err(|_| ui_assembly_error("panel-tree.sections"))?;
            Ok(self)
        }

        /// 🌳️ Adds a section, substituting a single "(none)"-style placeholder item when `items` is empty —
        /// the empty-state pattern duplicated in `build_document_tree`/`build_catalogue_tree` across apps.
        pub fn section_or_placeholder<I: AsRef<str>, L: TryInto<Label>>(self, id: I, label: Option<Label>, default_open: bool, mut items: UiFixedList<BuiltNode>, placeholder_label: L) -> UiAssemblyResult<Self> {
            if items.is_empty() {
                let empty_id = UiText::try_format(format_args!("{}.empty", id.as_ref())).ok_or_else(|| ui_assembly_error("panel-tree.placeholder-id"))?;
                items.try_push(tree_item(empty_id, placeholder_label)?).map_err(|_| ui_assembly_error("panel-tree.placeholder"))?;
            }
            self.section(id, label, default_open, items)
        }

        /// 🪟️ Adds a windowed section — see [`tree_window_section`]. The panel hands the same
        /// [`TreeWindows`] to every container it builds, so the shared first-paint budget is spent in
        /// document order.
        pub fn window_section<T>(mut self, windows: &TreeWindows<'_>, id: &str, label: Option<Label>, default_open: bool, entries: &[T], row: impl FnMut(&T) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<Self> {
            let node = tree_window_section(windows, id, label.unwrap_or_default(), default_open, entries, row)?;
            self.sections.try_push(node).map_err(|_| ui_assembly_error("panel-tree.sections"))?;
            Ok(self)
        }

        /// 🪟️ [`Self::window_section`] with an empty-state placeholder row — see
        /// [`tree_window_section_or_placeholder`].
        pub fn window_section_or_placeholder<T, L: TryInto<Label>>(
            mut self,
            windows: &TreeWindows<'_>,
            id: &str,
            label: Option<Label>,
            default_open: bool,
            entries: &[T],
            row: impl FnMut(&T) -> UiAssemblyResult<BuiltNode>,
            placeholder_label: L,
        ) -> UiAssemblyResult<Self> {
            let node = tree_window_section_or_placeholder(windows, id, label.unwrap_or_default(), default_open, entries, row, placeholder_label)?;
            self.sections.try_push(node).map_err(|_| ui_assembly_error("panel-tree.sections"))?;
            Ok(self)
        }

        pub fn selected<I: IntoIterator<Item = String>>(mut self, ids: I) -> UiAssemblyResult<Self> {
            let mut admitted = UiFixedList::default();
            for id in ids {
                let id = ui_text(id, "panel-tree.selected-id")?;
                admitted.try_push(id).map_err(|_| ui_assembly_error("panel-tree.selected"))?;
            }
            self.selected_ids = Some(admitted);
            Ok(self)
        }

        pub fn highlighted<I: IntoIterator<Item = String>>(mut self, ids: I) -> UiAssemblyResult<Self> {
            let mut admitted = UiFixedList::default();
            for id in ids {
                let id = ui_text(id, "panel-tree.highlighted-id")?;
                admitted.try_push(id).map_err(|_| ui_assembly_error("panel-tree.highlighted"))?;
            }
            self.highlighted_ids = Some(admitted);
            Ok(self)
        }

        /// 🕹️ Binds the built tree to an app-declared `InteractionDefinition` domain id — the framework
        /// then owns this domain's selection/hover, replacing the deleted per-app `selection_change` action
        /// — AND stamps the one tree-level `Trigger::Activate` binding
        /// (`interactionSelect { domainId }`) every pick row in the tree dispatches through. A row marked
        /// with [`TreeItemBuilder::granularity`] therefore needs no binding and no argument map of its
        /// own: it costs zero `UiValue` arena, which is what lets a window of 128 rows exist at all.
        pub fn interaction_domain(mut self, controller_id: &'static str, domain: impl TryInto<UiText>) -> UiAssemblyResult<Self> {
            let domain = ui_text(domain, "panel-tree.interaction-domain")?;
            let mut args = UiMapBuilder::try_new().ok_or_else(|| ui_assembly_error("panel-tree.interaction-args"))?;
            args.push("domainId".to_owned(), UiValue::Text(domain.clone())).map_err(|_| ui_assembly_error("panel-tree.interaction-args"))?;
            self.interaction_select = Some(ActionFactory::new(controller_id).action(INTERACTION_SELECT_ACTION_ID, Some(UiValue::Map(args.finish())))?);
            self.interaction_domain = Some(domain);
            Ok(self)
        }

        pub fn drop_action(mut self, action: ActionId) -> Self {
            self.drop_action = Some(action);
            self
        }

        /// 🌳️ Terminal — see this struct's own doc for why `.selected()`/`.highlighted()` no longer
        /// reach the built tree this wave.
        pub fn build(self) -> UiAssemblyResult<BuiltNode> {
            let builder = tree().try_id(&self.namespace).map_err(|_| ui_assembly_error("panel-tree.root-id"))?;
            let mut builder = builder.try_children(self.sections).map_err(|_| ui_assembly_error("panel-tree.root-sections"))?;
            if let Some(domain) = self.interaction_domain {
                builder = builder.interaction_domain(domain);
            }
            if let Some((action, args)) = self.interaction_select {
                builder = match args {
                    Some(args) => builder.try_on_with(Trigger::Activate, action, args).map_err(|_| ui_assembly_error("panel-tree.interaction-binding"))?,
                    None => builder.try_on(Trigger::Activate, action).map_err(|_| ui_assembly_error("panel-tree.interaction-binding"))?,
                };
            }
            if let Some(action) = self.drop_action {
                builder = builder.try_on(Trigger::Drop, action).map_err(|_| ui_assembly_error("panel-tree.drop-binding"))?;
            }
            builder.try_build().map_err(|_| ui_assembly_error("panel-tree.root-build"))
        }
    }

    //#region 🔖️PanelWindowing
    // 🪟️ Shared virtualised-panel windowing — a panel body is NOT a row per entity, and it is not a
    // page with a `+N` tail either. Every container reports its FULL extent through
    // `TreeWindow { total, offset }` and materialises only the rows the host asked for, so the host's
    // scrollbar spans the whole document while the built tree stays inside `UI_BUILT_CHILDREN_MAX`
    // children and the process-wide `UiValue` argument arena. Open state and scroll offset are
    // host-owned and arrive per render through `ViewModel::tree_windows`; the guest keeps no cursor.

    /// 🪟️ Rows one first paint materialises across a body's containers together, before the host has
    /// measured its viewport (`ViewModel::tree_viewport_rows`).
    pub const TREE_WINDOW_DEFAULT_ROWS: u32 = 48;

    /// 🧾️ The body-wide node budget and its fixed-node reserve live ONCE, in the UI contract, because
    /// the React host spends the same number from the other side of the wire
    /// (`🌳️Tree/🟦️.tsx`'s `capTreeWindowRequests`). See
    /// [`semio_framework_ui_contract::TREE_WINDOW_BODY_NODE_BUDGET`] for the cost model both sides
    /// implement; [`TreeWindows`] is this side of it.
    pub use semio_framework_ui_contract::{TREE_WINDOW_BODY_NODE_BUDGET, TREE_WINDOW_FIXED_NODE_HEADROOM, TREE_WINDOW_PATH_SEPARATOR};

    /// 🧾️ Items one fixed (unwindowed) record or windowed container record of a body may charge the surface
    /// reconciliation — the item-side price of [`TREE_WINDOW_FIXED_NODE_HEADROOM`].
    pub const TREE_WINDOW_FIXED_NODE_ITEMS: usize = 32;

    /// 🧾️ The body-wide ITEM budget windowed rows spend: the surface reconciler's item ceiling
    /// ([`semio_framework_ui_runtime::SURFACE_RECONCILE_MAX_ITEMS`], less its one root seed) less what the fixed
    /// records may charge. Rows carrying their own argument maps reach this long before the node budget — 28
    /// Home rows with five row actions each do — so [`TreeWindows`] prices every materialised row with
    /// [`semio_framework_ui_runtime::surface_subtree_items`] and ends a window early rather than letting the
    /// reconciler refuse the whole surface (ticket 26/09/23 U5: 138 Home spaces faulted `items 4098 > 4097`).
    pub const TREE_WINDOW_BODY_ITEM_BUDGET: usize = semio_framework_ui_runtime::SURFACE_RECONCILE_MAX_ITEMS - 1 - TREE_WINDOW_FIXED_NODE_HEADROOM * TREE_WINDOW_FIXED_NODE_ITEMS;

    /// 🪟️ What one container materialises this render: `len` rows starting at `offset` out of `total`.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct TreeSlice {
        pub open: bool,
        pub offset: usize,
        pub len: usize,
        pub total: usize,
    }

    /// 🪟️ The host's windows for one panel body, read once per render off `ViewModel::tree_windows`.
    /// Containers the host has never seen share `budget` — the first-paint allowance spent in
    /// document order, nested containers included — so a cold render draws about one viewport and
    /// stops, instead of the whole document.
    ///
    /// 🧾️ `nodes` is the body-wide **node ledger**, and it is the reason per-container clamps are not
    /// enough. The reconciler admits at most [`semio_framework_ui_contract::UI_DOCUMENT_NODES`] node
    /// records per PRESENTED BODY — the tree root, every section node, every group item, every row and
    /// every placeholder counts once (`SurfaceReconcileLimits::max_nodes`, enforced per admitted node
    /// in `🧠️runtime/♻️reconcile/🦀️.rs`). A body whose containers each stayed inside
    /// `UI_BUILT_CHILDREN_MAX` could still sum past that ceiling and fault the whole refresh — fem3d
    /// House did, at `nodes: 129 > max_nodes: 128`.
    ///
    /// 🧾️ **Cost model — one budget, one arithmetic, both sides of the wire.** The ledger opens on
    /// [`semio_framework_ui_contract::TREE_WINDOW_BODY_NODE_BUDGET`], the SAME number the React host
    /// caps its requests with, and one windowed container costs `1 + its materialised rows`. Every
    /// node is charged EXACTLY ONCE: a nested [`tree_window_item`] built as a row of an enclosing
    /// window is the row its parent already paid for, so it does not charge its own `1` again (the
    /// helpers track that they are inside a parent's row closure). So a request the host is allowed to
    /// file — it caps `Σ(1 + rows) ≤ TREE_WINDOW_BODY_NODE_BUDGET` — is always one this side can
    /// honour in full.
    ///
    /// 🥇️ **Request priority — order independence.** A first-paint default must never eat the records
    /// a container the user actually scrolled to needs, and the host's request order is its node keys
    /// sorted alphabetically (wire byte-stability), NOT document order. So the ledger is split the
    /// moment it is built, before any container exists: each host request reserves
    /// `1 + min(rows, UI_BUILT_CHILDREN_MAX)`, in request order, until the budget is spent — a host
    /// that over-asks is clamped there, deterministically, tail last. A container the host has NOT
    /// addressed is then served out of the UNRESERVED remainder only, and additionally out of the
    /// shared viewport `budget`, in document order. A container the host HAS addressed releases its
    /// own reservation when the render reaches it and is served out of the whole remaining ledger,
    /// wherever it sits in the body. `rows: 0` with `open: true` is a valid request — a measured but
    /// off-screen container — and materialises nothing; it never falls back to the first-paint default.
    /// A stale `offset` past the end clamps to the LAST window (`total - rows`), never to an empty
    /// slice of a non-empty container.
    ///
    /// 🔑️ **A container is addressed by its window PATH, never by its bare node key.** The path is the
    /// enclosing windowed containers' keys, outermost first, then its own key, joined by
    /// [`semio_framework_ui_contract::TREE_WINDOW_PATH_SEPARATOR`] — see [`Self::path_of`]. A
    /// top-level section's path IS its key, so a flat body is byte-identical to a bare-key one; a
    /// nested one is `"…load-cases\u{1f}dead"`. This is what makes container identity collision-free
    /// BY CONSTRUCTION without touching node keys or pick target ids: a load case and a combination
    /// both called `uls`, or one object id repeated across four cad pane sections, differ in their
    /// parents and therefore in their paths, and keep independent open and window state.
    ///
    /// 🔑️ Two containers can then collide only as TRUE SIBLINGS under one parent — which the UI
    /// document itself already refuses (`DuplicateSiblingKey`). The second sibling to claim a path is
    /// refused here first, with `ui.tree-window.duplicate-key`, so the author sees the cause rather
    /// than the symptom. A container with no entries the host has never addressed publishes no window,
    /// is not addressable, and therefore claims nothing: a tree whose leaves are built through
    /// [`tree_window_item`] (a JSON document, an AST) is bound by this rule only at the nodes that
    /// actually have children.
    ///
    /// 🧾️ Running out is not a fault. A container the ledger cannot seat still builds and still stamps
    /// its full `TreeWindow { total, offset }` with a shorter — possibly empty — materialised run, so
    /// the host's scrollbar keeps spanning the whole document and the next scroll streams the rows in.
    ///
    /// ⚠️ Rows built any other way are OUTSIDE the ledger: [`PanelTreeBuilder::section`],
    /// [`PanelTreeBuilder::section_or_placeholder`], bare [`tree_item`]/[`tree_section`] children and
    /// [`ui_node_list`] admissions are invisible to it, because they carry no window and no node key
    /// for the host to address. Those are the small fixed lists apps legitimately still build, and
    /// [`TREE_WINDOW_FIXED_NODE_HEADROOM`] is what pays for them. A panel that builds MORE than the
    /// headroom in fixed rows must move them onto a window. A container's own node is debited
    /// unconditionally — it is not optional once the panel decided to build it — so an overdrawn
    /// ledger simply grants nothing to everything after it.
    pub struct TreeWindows<'a> {
        requests: Vec<(&'a TreeWindowRequest, std::cell::Cell<usize>)>,
        budget: std::cell::Cell<u32>,
        nodes: std::cell::Cell<isize>,
        items: std::cell::Cell<usize>,
        reserved: std::cell::Cell<usize>,
        claimed: std::cell::RefCell<Vec<String>>,
        path: std::cell::RefCell<Vec<String>>,
    }

    impl<'a> TreeWindows<'a> {
        /// 🪟️ Every request the host filed for `body_key`, plus its measured viewport budget.
        pub fn for_body(view: &'a ViewModel, body_key: &str) -> Self {
            Self::seated(view.tree_windows.iter().filter(|request| request.body_key == body_key), view.tree_viewport_rows.unwrap_or(TREE_WINDOW_DEFAULT_ROWS))
        }

        /// 🪟️ No host state at all (tests, a body the host has never rendered): author defaults and
        /// the default first-paint budget.
        pub fn unhosted() -> Self {
            Self::seated(std::iter::empty(), TREE_WINDOW_DEFAULT_ROWS)
        }

        /// 🥇️ Seats the host's requests on the ledger in request order — see this type's doc. A key the
        /// host filed twice is seated once: only the first is ever read back, so reserving for the
        /// second would hold records nothing can release.
        fn seated(requests: impl IntoIterator<Item = &'a TreeWindowRequest>, viewport_rows: u32) -> Self {
            let mut unreserved = TREE_WINDOW_BODY_NODE_BUDGET;
            let mut seen: Vec<&str> = Vec::new();
            let requests: Vec<_> = requests
                .into_iter()
                .map(|request| {
                    let want = match request.open {
                        Some(false) => 0,
                        _ if seen.contains(&request.node_key.as_str()) => 0,
                        _ => (1 + (request.rows as usize).min(UI_BUILT_CHILDREN_MAX)).min(unreserved),
                    };
                    seen.push(request.node_key.as_str());
                    unreserved -= want;
                    (request, std::cell::Cell::new(want))
                })
                .collect();
            Self {
                requests,
                budget: std::cell::Cell::new(viewport_rows),
                nodes: std::cell::Cell::new(TREE_WINDOW_BODY_NODE_BUDGET as isize),
                items: std::cell::Cell::new(TREE_WINDOW_BODY_ITEM_BUDGET),
                reserved: std::cell::Cell::new(TREE_WINDOW_BODY_NODE_BUDGET - unreserved),
                claimed: std::cell::RefCell::new(Vec::new()),
                path: std::cell::RefCell::new(Vec::new()),
            }
        }

        /// 🔑️ The **window path** `node_key` is addressed by from where the render currently stands:
        /// the enclosing windowed containers' keys, outermost first, then `node_key`, joined by
        /// [`semio_framework_ui_contract::TREE_WINDOW_PATH_SEPARATOR`]. At the top level this is
        /// `node_key` itself, so a flat body's requests and laws are byte-identical to before.
        ///
        /// 🔑️ A path is a **view-context identifier**: printable, at most 256 code points, because it
        /// crosses the process boundary inside `ViewModel::tree_windows` and both sides admit it with
        /// the same law (`parseResolvedPluginViewState`, `🛂️manifest/🟦️.ts`). A path longer than that
        /// is one the host never files a request for, so the container it names simply renders as
        /// UNREQUESTED — the author's default plus the shared first-paint budget — which is already
        /// what an absent seat means here.
        pub fn path_of(&self, node_key: &str) -> String {
            let path = self.path.borrow();
            if path.is_empty() {
                return node_key.to_owned();
            }
            let mut joined = String::new();
            for segment in path.iter() {
                joined.push_str(segment);
                joined.push_str(TREE_WINDOW_PATH_SEPARATOR);
            }
            joined.push_str(node_key);
            joined
        }

        /// 🧾️ Whether the render currently stands inside an enclosing window's row closure — the
        /// container being built there is that row, already charged by its parent.
        fn is_nested(&self) -> bool {
            !self.path.borrow().is_empty()
        }

        /// 🧾️ Node records this body may still materialise — every container and every row this
        /// [`TreeWindows`] has served has already been charged. Zero once the ledger is spent, including
        /// when unconditional container debits drove it past zero.
        pub fn nodes_remaining(&self) -> usize {
            self.nodes.get().max(0) as usize
        }

        /// 🥇️ Records still held back for host requests this render has not reached yet.
        pub fn nodes_reserved(&self) -> usize {
            self.reserved.get()
        }

        /// 🧾️ Reconciliation items windowed rows may still charge — see [`TREE_WINDOW_BODY_ITEM_BUDGET`].
        pub fn items_remaining(&self) -> usize {
            self.items.get()
        }

        /// 🧾️ Gives back the node records of `rows` a window was granted but did not materialise.
        fn refund(&self, rows: usize) {
            self.nodes.set(self.nodes.get() + rows as isize);
        }

        /// 🔑️ Registers `node_key` as this body's, refusing the second container to claim it — see
        /// this type's doc. Only a container that PUBLISHES a window claims: one with no entries the
        /// host has never addressed stamps nothing, so it is not addressable and two of them cannot
        /// steer each other. That is what keeps a tree of leaf rows (a JSON document, an AST) out of
        /// the uniqueness requirement — it binds containers, not rows.
        /// 🔑️ A container key carrying the path separator would make its own path ambiguous — it could
        /// not be told from a parent/child pair — so it is refused at assembly rather than mis-addressed.
        fn admit_key(node_key: &str) -> UiAssemblyResult<()> {
            if node_key.contains(TREE_WINDOW_PATH_SEPARATOR) {
                return Err(PluginAssemblyError::new("ui.tree-window.separator-in-key", format!("[tree-window] node key {node_key:?} contains the window-path separator {TREE_WINDOW_PATH_SEPARATOR:?}, which would make its path ambiguous")));
            }
            Ok(())
        }

        fn claim_window(&self, path: &str, entries: usize) -> UiAssemblyResult<()> {
            if entries == 0 && self.seat(path).is_none() {
                return Ok(());
            }
            self.claim(path)
        }

        fn claim(&self, node_key: &str) -> UiAssemblyResult<()> {
            let mut claimed = self.claimed.borrow_mut();
            if claimed.iter().any(|key| key == node_key) {
                return Err(PluginAssemblyError::new(
                    "ui.tree-window.duplicate-key",
                    format!("[tree-window] duplicate key {node_key:?} in this panel body — two windowed containers share one window and one open state; give every windowed container its own node key"),
                ));
            }
            claimed.push(node_key.to_owned());
            Ok(())
        }

        /// 🧾️ Takes `nodes` records off the ledger whether or not it can afford them — a container's
        /// own node is not optional once the panel decided to build it.
        fn debit(&self, nodes: usize) {
            self.nodes.set(self.nodes.get() - nodes as isize);
        }

        /// 🧾️ Charges the node of a container that is about to be built — nothing when the container is
        /// itself a row of an enclosing window, which already paid for it (charged exactly once).
        fn debit_container(&self) {
            if !self.is_nested() {
                self.debit(1);
            }
        }

        /// 🧾️ Takes up to `want` records off the ledger, returning what it could actually afford.
        fn grant(&self, want: usize) -> usize {
            let spent = want.min(self.nodes_remaining());
            self.debit(spent);
            spent
        }

        /// 🥇️ [`Self::grant`] out of the records no host request is holding — the first-paint path.
        fn grant_unreserved(&self, want: usize) -> usize {
            let spent = want.min(self.nodes_remaining().saturating_sub(self.reserved.get()));
            self.debit(spent);
            spent
        }

        fn seat(&self, node_key: &str) -> Option<&(&'a TreeWindowRequest, std::cell::Cell<usize>)> {
            self.requests.iter().find(|(request, _)| request.node_key == node_key)
        }

        fn request(&self, node_key: &str) -> Option<&'a TreeWindowRequest> {
            self.seat(node_key).map(|(request, _)| *request)
        }

        /// 🔽️ Whether `node_key` is expanded — a host `open` wins over the author's default. The key
        /// is resolved against the current [`Self::path_of`] scope, so callers pass the plain id.
        pub fn is_open(&self, node_key: &str, default_open: bool) -> bool {
            self.request(&self.path_of(node_key)).and_then(|request| request.open).unwrap_or(default_open)
        }

        /// 🪟️ The slice `node_key` materialises this render out of `total` logical entries, charged to
        /// the body-wide node ledger. A container the host asked for is served out of its own
        /// reservation and cannot be starved by the containers before it, wherever it sits in the body;
        /// a container on its first paint gets only what no request is holding, and only as much as the
        /// shared viewport budget still allows.
        pub fn slice(&self, node_key: &str, default_open: bool, total: usize) -> TreeSlice {
            self.sliced(&self.path_of(node_key), default_open, total)
        }

        fn sliced(&self, path: &str, default_open: bool, total: usize) -> TreeSlice {
            self.sliced_capped(path, default_open, total, usize::MAX)
        }

        fn sliced_capped(&self, path: &str, default_open: bool, total: usize, maximum: usize) -> TreeSlice {
            let seat = self.seat(path);
            if let Some((_, reservation)) = seat {
                self.reserved.set(self.reserved.get().saturating_sub(reservation.replace(0)));
            }
            let request = seat.map(|(request, _)| *request);
            if !request.and_then(|request| request.open).unwrap_or(default_open) {
                return TreeSlice { open: false, offset: 0, len: 0, total };
            }
            let Some(request) = request else {
                let len = self.grant_unreserved(total.min(maximum).min(UI_BUILT_CHILDREN_MAX).min(self.budget.get() as usize));
                self.budget.set(self.budget.get() - len as u32);
                return TreeSlice { open: true, offset: 0, len, total };
            };
            let rows = (request.rows as usize).min(maximum).min(UI_BUILT_CHILDREN_MAX);
            let offset = (request.offset as usize).min(total.saturating_sub(rows.max(1)));
            let len = self.grant(rows.min(total - offset));
            TreeSlice { open: true, offset, len, total }
        }

        fn projection_slice(&self, path: &str, default_open: bool, total: usize, first_paint: usize, maximum: usize) -> TreeSlice {
            let seat = self.seat(path);
            if let Some((_, reservation)) = seat {
                self.reserved.set(self.reserved.get().saturating_sub(reservation.replace(0)));
            }
            let request = seat.map(|(request, _)| *request);
            if !request.and_then(|request| request.open).unwrap_or(default_open) {
                return TreeSlice { open: false, offset: 0, len: 0, total };
            }
            let rows = request.map_or(first_paint, |request| request.rows as usize).min(maximum).min(UI_BUILT_CHILDREN_MAX).min(total);
            let offset = request.map_or(0, |request| request.offset as usize).min(total.saturating_sub(rows.max(1)));
            TreeSlice { open: true, offset, len: rows.min(total - offset), total }
        }

        /// 🪟️ The contract stamp a slice publishes to the host.
        pub fn window(slice: &TreeSlice) -> TreeWindow {
            TreeWindow { total: slice.total as u32, offset: slice.offset as u32, row_extent: TreeWindowRowExtent::Standard }
        }

        fn stamp(&self, path: &str, slice: &TreeSlice) -> Option<TreeWindow> {
            (slice.total > 0 || self.seat(path).is_some()).then(|| Self::window(slice))
        }
    }

    thread_local! {
        /// 🎟️ Rows the windows of the render in progress left unbuilt because the process-wide `UiValue` arena had no
        /// credit for them — see [`take_arena_unbuilt_rows`].
        static ARENA_UNBUILT_ROWS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    }

    /// 🎟️ Takes (and resets) the rows the renders since the last call left unbuilt for want of `UiValue` arena credit.
    /// The reactor reads it after every surface render and renders that surface once more when the arena can price
    /// them again; a law reads it to prove a short window was cut by the arena, not by the host's request.
    pub fn take_arena_unbuilt_rows() -> usize {
        ARENA_UNBUILT_ROWS.with(|rows| rows.replace(0))
    }

    /// 🪟️ Pushes a slice's rows straight into a container builder's children. A row refused with
    /// `ui.fixed-capacity` — the process-global argument arena taken by another panel mid-build, or a
    /// full `BuiltChildren` — or one whose whole subtree the remaining [`TREE_WINDOW_BODY_ITEM_BUDGET`]
    /// cannot pay for ends the window early with a shorter materialised run, and gives back the records
    /// and items it and the unbuilt rest held; any other error propagates. A row the process-wide `UiValue`
    /// arena can no longer price is not started at all: [`semio_framework_ui_contract::ui_value_headroom`] must
    /// still admit one row of [`semio_framework_ui_contract::UI_VALUE_ROW_COLLECTIONS`] collections, because the
    /// arena is ONE page shared by every panel and by the previous generations the reactor is still retiring, and
    /// a window that stops there stamps its full extent like any other short run. Rows are built with the
    /// ledger's `nested` flag raised, so a row that is itself a windowed container does not charge its own
    /// node twice, and its subtree's item price replaces what its nested windows charged.
    fn tree_window_indexed_rows<B: HasChildren>(mut builder: B, windows: &TreeWindows<'_>, id: &str, slice: &TreeSlice, mut row: impl FnMut(usize) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<B> {
        for (built, index) in (slice.offset..slice.offset + slice.len).enumerate() {
            let (nodes, items) = (windows.nodes.get(), windows.items.get());
            let unbuilt = || {
                windows.nodes.set(nodes);
                windows.items.set(items);
                windows.refund(slice.len - built);
            };
            if semio_framework_ui_contract::ui_value_headroom().rows() == 0 {
                windows.refund(slice.len - built);
                ARENA_UNBUILT_ROWS.with(|rows| rows.set(rows.get() + slice.len - built));
                break;
            }
            windows.path.borrow_mut().push(id.to_owned());
            let materialised = row(index);
            windows.path.borrow_mut().pop();
            let node = match materialised {
                Ok(node) => node,
                Err(error) if error.code == "ui.fixed-capacity" => {
                    unbuilt();
                    if semio_framework_ui_contract::ui_value_headroom().rows() == 0 {
                        ARENA_UNBUILT_ROWS.with(|rows| rows.set(rows.get() + slice.len - built));
                    }
                    break;
                }
                Err(error) => return Err(error),
            };
            let Some(cost) = semio_framework_ui_runtime::surface_subtree_items(&node).ok().filter(|cost| *cost <= items) else {
                unbuilt();
                break;
            };
            windows.items.set(items - cost);
            builder = match builder.try_child(node) {
                Ok(builder) => builder,
                Err((builder, _)) => {
                    unbuilt();
                    return Ok(builder);
                }
            };
        }
        Ok(builder)
    }

    fn tree_window_rows<B: HasChildren, T>(builder: B, windows: &TreeWindows<'_>, id: &str, entries: &[T], slice: &TreeSlice, mut row: impl FnMut(&T) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<B> {
        tree_window_indexed_rows(builder, windows, id, slice, |index| row(&entries[index]))
    }

    /// 🪟️ One windowed section node: only the host's slice is built, `window` carries the full extent,
    /// never a `+N` continuation row. The section node itself is charged to the body-wide node ledger
    /// before its rows are — see [`TreeWindows`].
    pub fn tree_window_section<T>(windows: &TreeWindows<'_>, id: &str, label: Label, default_open: bool, entries: &[T], row: impl FnMut(&T) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<BuiltNode> {
        TreeWindows::admit_key(id)?;
        let path = windows.path_of(id);
        windows.claim_window(&path, entries.len())?;
        windows.debit_container();
        let slice = windows.sliced(&path, default_open, entries.len());
        let builder = tree_section(label).default_open(default_open).try_id(id).map_err(|_| ui_assembly_error("tree-window.section-id"))?;
        let builder = tree_window_rows(builder, windows, id, entries, &slice, row)?;
        let builder = match windows.stamp(&path, &slice) {
            Some(window) => builder.window(window),
            None => builder,
        };
        builder.try_build().map_err(|_| ui_assembly_error("tree-window.section-build"))
    }

    /// 🪟️ One windowed section whose logical rows are addressed by ordinal, keeping large lazy
    /// projections reachable without allocating a temporary entry collection.
    pub fn tree_window_indexed_section(windows: &TreeWindows<'_>, id: &str, label: Label, default_open: bool, total: usize, row: impl FnMut(usize) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<BuiltNode> {
        TreeWindows::admit_key(id)?;
        let path = windows.path_of(id);
        windows.claim_window(&path, total)?;
        windows.debit_container();
        let slice = windows.sliced(&path, default_open, total);
        let builder = tree_section(label).default_open(default_open).try_id(id).map_err(|_| ui_assembly_error("tree-window.section-id"))?;
        let builder = tree_window_indexed_rows(builder, windows, id, &slice, row)?;
        let builder = match windows.stamp(&path, &slice) {
            Some(window) => builder.window(window),
            None => builder,
        };
        builder.try_build().map_err(|_| ui_assembly_error("tree-window.section-build"))
    }

    /// 🪟️ [`tree_window_section`], substituting one "(none)"-style placeholder row when `entries` is
    /// empty — an empty container has no window to publish.
    pub fn tree_window_section_or_placeholder<T, L: TryInto<Label>>(
        windows: &TreeWindows<'_>,
        id: &str,
        label: Label,
        default_open: bool,
        entries: &[T],
        row: impl FnMut(&T) -> UiAssemblyResult<BuiltNode>,
        placeholder_label: L,
    ) -> UiAssemblyResult<BuiltNode> {
        if !entries.is_empty() {
            return tree_window_section(windows, id, label, default_open, entries, row);
        }
        TreeWindows::admit_key(id)?;
        windows.debit_container();
        windows.debit(1);
        let empty_id = UiText::try_format(format_args!("{id}.empty")).ok_or_else(|| ui_assembly_error("tree-window.placeholder-id"))?;
        let builder = tree_section(label).default_open(default_open).try_id(id).map_err(|_| ui_assembly_error("tree-window.section-id"))?;
        builder.try_child(tree_item(empty_id, placeholder_label)?).map_err(|_| ui_assembly_error("tree-window.placeholder"))?.try_build().map_err(|_| ui_assembly_error("tree-window.section-build"))
    }

    /// 🪟️ A windowed group row (object › vortices, load case › loads) — `item` already carries its id,
    /// label and icon, `id` is the node key the host addresses it by. Built as a row of an enclosing
    /// window, the group item's own node is the row its parent already charged; built standalone it
    /// charges its own. Either way its rows come off the same body-wide ledger as the sections around
    /// it — see [`TreeWindows`].
    pub fn tree_window_item<T>(windows: &TreeWindows<'_>, item: TreeItemBuilder, id: &str, default_open: bool, entries: &[T], row: impl FnMut(&T) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<BuiltNode> {
        TreeWindows::admit_key(id)?;
        let path = windows.path_of(id);
        windows.claim_window(&path, entries.len())?;
        windows.debit_container();
        let slice = windows.sliced(&path, default_open, entries.len());
        let builder = tree_window_rows(item.default_open(default_open), windows, id, entries, &slice, row)?;
        let builder = match windows.stamp(&path, &slice) {
            Some(window) => builder.window(window),
            None => builder,
        };
        builder.try_build().map_err(|_| ui_assembly_error("tree-window.item-build"))
    }

    /// 🪟️ One windowed group whose logical rows are addressed by ordinal without first allocating a
    /// collection of row records. Lazy artifact projections use this for byte, pixel, vertex, and
    /// document collections whose complete cardinality must remain reachable without materialisation.
    pub fn tree_window_indexed_item(windows: &TreeWindows<'_>, item: TreeItemBuilder, id: &str, default_open: bool, total: usize, row: impl FnMut(usize) -> UiAssemblyResult<BuiltNode>) -> UiAssemblyResult<BuiltNode> {
        TreeWindows::admit_key(id)?;
        let path = windows.path_of(id);
        windows.claim_window(&path, total)?;
        windows.debit_container();
        let slice = windows.sliced(&path, default_open, total);
        let builder = tree_window_indexed_rows(item.default_open(default_open), windows, id, &slice, row)?;
        let builder = match windows.stamp(&path, &slice) {
            Some(window) => builder.window(window),
            None => builder,
        };
        builder.try_build().map_err(|_| ui_assembly_error("tree-window.item-build"))
    }

    /// 🌳️ Admits fallibly assembled UI nodes into fixed child storage — the fleet's one copy, replacing
    /// the per-app duplicates. ⚠️ These rows are OUTSIDE the [`TreeWindows`] node ledger: they carry no
    /// window and no node key, so only [`TREE_WINDOW_FIXED_NODE_HEADROOM`] pays for them. Use it for the
    /// small fixed lists a panel genuinely owns, never for an entity list.
    pub fn ui_node_list(values: impl IntoIterator<Item = UiAssemblyResult<BuiltNode>>) -> UiAssemblyResult<UiFixedList<BuiltNode>> {
        let mut nodes = UiFixedList::default();
        for value in values {
            nodes.try_push(value?).map_err(|_| ui_assembly_error("ui-node-list.admission"))?;
        }
        Ok(nodes)
    }
    //#endregion 🔖️PanelWindowing

    #[cfg(test)]
    include!("🧪️tests/🔬️app-panel-kit/🦀️.rs");
    //#endregion 🔖️PanelKit

    //#region 🔖️FormKit
    // 📋️ Shared form-panel builder — lifts the `Section > labeled Field rows > submit Button` skeleton
    // (and the sibling `entity_detail` read-only `KeyValue` summary block) duplicated across plugin crates
    // that render declarative forms/detail panels, mirroring `PanelTreeBuilder`'s namespaced builder-pattern
    // shape above (`namespace` prefixes every id, method chaining ends in `.build() -> BuiltNode`).

    /// 📋️ Fluent builder for a `Section` of labeled `Field` rows ending in an optional submit `Button` —
    /// same namespaced-id / method-chaining shape as `PanelTreeBuilder`.
    pub struct FormPanelBuilder {
        namespace: UiText,
        fields: UiFixedList<BuiltNode>,
        submit: Option<BuiltNode>,
    }

    impl FormPanelBuilder {
        /// 📋️ `namespace` prefixes every field id built via `.field_id()`/`.field()`/`.from_dictionary()`.
        pub async fn new(namespace: impl TryInto<UiText>) -> UiAssemblyResult<Self> {
            Ok(Self { namespace: ui_text(namespace, "form-panel.namespace")?, fields: UiFixedList::default(), submit: None })
        }

        /// 📋️ Builds a namespaced field id: `"{namespace}.field.{id}"` — mirrors `PanelTreeBuilder::item_id`.
        pub async fn field_id(&self, id: &str) -> UiAssemblyResult<UiText> {
            UiText::try_format(format_args!("{}.field.{id}", self.namespace)).ok_or_else(|| ui_assembly_error("form-panel.field-id"))
        }

        /// 📋️ Adds one labeled field row: `control` is any already-built child node. The old
        /// `UiControlNode` wrapper enum this took is retired outright (`📓️recipe-plugin.md`'s own
        /// call: every one of its variants is already a `Component` variant in its own right, so a
        /// control-as-child needs no separate wrapper type) — callers build `control` with the plain
        /// `ui::*` DSL (`ui::input(..).build()`, `ui::toggle(..).build()`, …) instead.
        pub async fn field<L: TryInto<Label>>(mut self, id: &str, label: L, description: Option<String>, control: BuiltNode) -> UiAssemblyResult<Self> {
            let field_id = self.field_id(id).await?;
            let builder = field(ui_label(label, "form-panel.field-label")?);
            let builder = builder.try_id(&field_id).map_err(|_| ui_assembly_error("form-panel.field-id"))?;
            let mut builder = builder.try_child(control).map_err(|_| ui_assembly_error("form-panel.field-control"))?;
            if let Some(description) = description {
                builder = builder.description(ui_text(description, "form-panel.field-description")?);
            }
            let field = builder.try_build().map_err(|_| ui_assembly_error("form-panel.field-build"))?;
            self.fields.try_push(field).map_err(|_| ui_assembly_error("form-panel.fields"))?;
            Ok(self)
        }

        /// 📋️ Routes the OS `form.dictionary` resource shape (see the `ArtifactKindSpec { id:
        /// "form.dictionary", source_format: "forms.dictionary", .. }` registered by `forms/plugin`'s
        /// `create_forms_app`) into a sequence of text-input field rows: each top-level entry in the
        /// `dictionary_json` array — `{ "id", "label"?, "description"?, "value"? }` — becomes one field
        /// dispatching the shared `on_change` action (its `args` are left to the caller; the emitted input's
        /// own id already carries which field changed).
        pub async fn from_dictionary(mut self, dictionary_json: &Value, on_change: ActionId) -> UiAssemblyResult<Self> {
            let Some(entries) = dictionary_json.as_array() else { return Ok(self) };
            for entry in entries {
                let Some(id) = entry.get("id").and_then(Value::as_str) else { continue };
                let label = ui_label(entry.get("label").and_then(Value::as_str).unwrap_or(id), "form-panel.dictionary-label")?;
                let description = entry.get("description").and_then(Value::as_str).map(str::to_string);
                let value = ui_text(entry.get("value").and_then(Value::as_str).unwrap_or_default(), "form-panel.dictionary-value")?;
                let field_id = self.field_id(id).await?;
                let builder = input(InputKind::Text).value(value);
                let builder = builder.try_id(&field_id).map_err(|_| ui_assembly_error("form-panel.dictionary-id"))?;
                let builder = builder.try_on(Trigger::Change, on_change.clone()).map_err(|_| ui_assembly_error("form-panel.dictionary-binding"))?;
                let control = builder.try_build().map_err(|_| ui_assembly_error("form-panel.dictionary-control"))?;
                self = self.field(id, label, description, control).await?;
            }
            Ok(self)
        }

        /// 📋️ Sets the trailing submit `Button` row. ⚠️ Decision: narrowed from `action: ActionDescriptor`
        /// to a bare [`ActionId`] bound as [`Trigger::Activate`] — same call as `tree_item_with_action`'s,
        /// same reasoning (see that function's doc).
        pub async fn submit<L: TryInto<Label>>(mut self, label: L, action: ActionId) -> UiAssemblyResult<Self> {
            let id = self.field_id("submit").await?;
            let icon = ui_text(IconName::CircleDot.as_str(), "form-panel.submit-icon")?;
            let builder = button(ui_label(label, "form-panel.submit-label")?).icon(icon);
            let builder = builder.try_id(&id).map_err(|_| ui_assembly_error("form-panel.submit-id"))?;
            let builder = builder.try_on(Trigger::Activate, action).map_err(|_| ui_assembly_error("form-panel.submit-binding"))?;
            self.submit = Some(builder.try_build().map_err(|_| ui_assembly_error("form-panel.submit-build"))?);
            Ok(self)
        }

        /// 📋️ Builds `Fields -> optional submit Button` under one wrapper, id'd by the builder's
        /// namespace. ⚠️ Decision: the old outer wrapper was `UiSectionNode { label: None, .. }` — mapped
        /// here to `ui::column()` (`ContainerRole::Plain`), not `ui::section("")`: a genuinely unlabeled
        /// box is exactly what `Plain` means, whereas `Section`'s whole point is a real header, so forcing
        /// an empty label through it would be the wrong component, not a faithful rename. `default_open`
        /// is dropped for the same reason — it only means something on a collapsible header this wrapper
        /// no longer has.
        pub async fn build(self) -> UiAssemblyResult<BuiltNode> {
            let builder = column().try_id(&self.namespace).map_err(|_| ui_assembly_error("form-panel.root-id"))?;
            let mut builder = builder.try_children(self.fields).map_err(|_| ui_assembly_error("form-panel.fields"))?;
            if let Some(submit) = self.submit {
                builder = builder.try_child(submit).map_err(|_| ui_assembly_error("form-panel.submit"))?;
            }
            builder.try_build().map_err(|_| ui_assembly_error("form-panel.root-build"))
        }
    }

    /// 📋️ A read-only entity-detail panel: `title`/`subtitle` header text, a `KeyValue` summary block built
    /// from `entries`, and trailing action buttons. Mirrors `📓️recipe-plugin.md` §7's own worked example
    /// verbatim: `Component::KeyValueList` has no `ui::*` builder yet (§4), so its `BuiltNode` is
    /// hand-assembled; `actions` takes already-built nodes (`Vec<BuiltNode>`) rather than a bare props
    /// struct, since a `Component::Button`'s `action`/`style` now live on the node, not `ButtonProps`.
    pub async fn entity_detail<L: TryInto<Label>, E: IntoIterator<Item = KeyValueEntry>, A: IntoIterator<Item = BuiltNode>>(title: L, subtitle: Option<Label>, entries: E, actions: A) -> UiAssemblyResult<BuiltNode> {
        let mut children = BuiltChildren::default();
        let title = text(ui_label(title, "entity-detail.title")?).try_build().map_err(|_| ui_assembly_error("entity-detail.title-build"))?;
        children.try_push(title).map_err(|_| ui_assembly_error("entity-detail.children"))?;
        if let Some(subtitle) = subtitle {
            let subtitle = text(subtitle).try_build().map_err(|_| ui_assembly_error("entity-detail.subtitle-build"))?;
            children.try_push(subtitle).map_err(|_| ui_assembly_error("entity-detail.children"))?;
        }
        let mut fixed_entries = UiFixedList::default();
        for entry in entries {
            fixed_entries.try_push(entry).map_err(|_| ui_assembly_error("entity-detail.entries"))?;
        }
        let summary = BuiltNode::try_new("summary", Component::KeyValueList(KeyValueListProps { entries: fixed_entries })).map_err(|_| ui_assembly_error("entity-detail.summary"))?;
        children.try_push(summary).map_err(|_| ui_assembly_error("entity-detail.children"))?;
        for action in actions {
            children.try_push(action).map_err(|_| ui_assembly_error("entity-detail.actions"))?;
        }
        let builder = column().try_children(children).map_err(|_| ui_assembly_error("entity-detail.children"))?;
        builder.try_build().map_err(|_| ui_assembly_error("entity-detail.build"))
    }

