    struct ChildMemberRetirement<M> {
        entry: std::mem::ManuallyDrop<Option<ChildMemberEntry<M>>>,
    }

    struct ChildStoreAdmission {
        key: (String, String),
        expected: ArtifactRef,
        owner: store::OwnerRef,
