    /// to a document passthrough rather than requiring any `media_ports()` declaration at all.
    #[derive(Clone, Debug)]
    pub struct MediaArtifact {
        pub descriptor: MediaArtifactDescriptor,
        pub data: Vec<u8>,
    }

