    pub(crate) const TOOL_CANCELLATION_SLOTS: usize = 1_024;
    const TOOL_CANCELLATION_WORDS: usize = TOOL_CANCELLATION_SLOTS / u64::BITS as usize;

    struct ToolPublicationClaim {
        state: std::sync::atomic::AtomicU8,
    }

    impl ToolPublicationClaim {
        fn new() -> std::sync::Arc<Self> {
            std::sync::Arc::new(Self { state: std::sync::atomic::AtomicU8::new(0) })
        }

        fn cancel(&self) {
            self.state.fetch_or(2, std::sync::atomic::Ordering::AcqRel);
        }

        fn is_cancelled(&self) -> bool {
            self.state.load(std::sync::atomic::Ordering::Acquire) & 2 != 0
        }

        fn finish(&self) {
            self.state.fetch_or(4, std::sync::atomic::Ordering::AcqRel);
        }

        fn is_finished(&self) -> bool {
            self.state.load(std::sync::atomic::Ordering::Acquire) & 4 != 0
        }

        fn try_claim(self: &std::sync::Arc<Self>) -> Option<ToolPublicationPermit> {
            self.state.compare_exchange(0, 1, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).ok()?;
            Some(ToolPublicationPermit { claim: self.clone() })
        }
    }

    struct ToolPublicationPermit {
        claim: std::sync::Arc<ToolPublicationClaim>,
    }

    struct ToolPublicationScopePermit {
        _app: ToolPublicationPermit,
        _document: Option<ToolPublicationPermit>,
        _operation: ToolPublicationPermit,
    }

    impl Drop for ToolPublicationPermit {
        fn drop(&mut self) {
            let previous = self.claim.state.fetch_and(!1, std::sync::atomic::Ordering::AcqRel);
            assert_ne!(previous & 1, 0, "publication claim is released by its exact sole permit");
        }
    }

    struct ToolDocumentCancellationScope {
        document: ArtifactDocumentAuthority,
        generation: u64,
        token: semio_framework_job::CancelToken,
        publication_claim: std::sync::Arc<ToolPublicationClaim>,
        operation: ToolOperationKey,
    }

    struct ToolKeyedDocumentCancellationScope {
        token: semio_framework_job::CancelToken,
        publication_claim: std::sync::Arc<ToolPublicationClaim>,
        active: usize,
    }

    pub(crate) struct ToolCancellationState {
        slots: Box<[std::mem::MaybeUninit<ToolDocumentCancellationScope>]>,
        occupied: [u64; TOOL_CANCELLATION_WORDS],
        allocation_admitted: bool,
        keyed_operations: ArtifactFixedRegistry<ToolDocumentCancellationScope>,
        keyed_documents: ArtifactFixedRegistry<ToolKeyedDocumentCancellationScope>,
    }

    impl ToolCancellationState {
        fn occupied(&self, index: usize) -> bool {
            self.occupied[index / u64::BITS as usize] & (1u64 << (index % u64::BITS as usize)) != 0
        }

        fn set_occupied(&mut self, index: usize, occupied: bool) {
            let word = &mut self.occupied[index / u64::BITS as usize];
            let mask = 1u64 << (index % u64::BITS as usize);
            if occupied {
                *word |= mask;
            } else {
                *word &= !mask;
            }
        }

        /// 🗝️ SAFETY: occupancy is set only after `write` and cleared before `assume_init_read`.
        fn get(&self, index: usize) -> Option<&ToolDocumentCancellationScope> {
            if !self.occupied(index) {
                return None;
            }
            self.slots.get(index).map(|slot| unsafe { slot.assume_init_ref() })
        }

        fn insert_admitted(&mut self, index: usize, value: ToolDocumentCancellationScope) {
            debug_assert!(self.allocation_admitted && !self.occupied(index));
            self.slots[index].write(value);
            self.set_occupied(index, true);
        }

        /// 🫳️ SAFETY: occupancy was checked and is now cleared before the exact initialized read.
        fn take(&mut self, index: usize) -> Option<ToolDocumentCancellationScope> {
            if !self.occupied(index) {
                return None;
            }
            self.set_occupied(index, false);
            Some(unsafe { self.slots[index].assume_init_read() })
        }
    }

    impl Drop for ToolCancellationState {
        fn drop(&mut self) {}
    }

    #[derive(Clone)]
    pub struct ToolCancellationHandle {
        pub(crate) state: std::sync::Arc<std::sync::Mutex<ToolCancellationState>>,
        app_scope: semio_framework_job::CancelToken,
        publication_scope: std::sync::Arc<ToolPublicationClaim>,
        app_generation: std::sync::Arc<std::sync::atomic::AtomicU64>,
        active: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    }

    impl Default for ToolCancellationHandle {
        fn default() -> Self {
            let mut slots = Vec::new();
            let allocation_admitted = slots.try_reserve_exact(TOOL_CANCELLATION_SLOTS).is_ok();
            if allocation_admitted {
                slots.resize_with(TOOL_CANCELLATION_SLOTS, std::mem::MaybeUninit::uninit);
            }
            Self {
                state: std::sync::Arc::new(std::sync::Mutex::new(ToolCancellationState {
                    slots: slots.into_boxed_slice(),
                    occupied: [0; TOOL_CANCELLATION_WORDS],
                    allocation_admitted,
                    keyed_operations: ArtifactFixedRegistry::new(),
                    keyed_documents: ArtifactFixedRegistry::new(),
                })),
                app_scope: semio_framework_job::CancelToken::root_now(),
                publication_scope: ToolPublicationClaim::new(),
                app_generation: std::sync::Arc::new(std::sync::atomic::AtomicU64::new(0)),
                active: std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0)),
            }
        }
    }

    impl ToolCancellationHandle {
        fn slot(document: ArtifactDocumentAuthority) -> usize {
            document.0 as usize % TOOL_CANCELLATION_SLOTS
        }

        fn try_state(&self) -> Result<std::sync::MutexGuard<'_, ToolCancellationState>, Fault> {
            self.state.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancellation-busy"), "cancellation authority is contended or poisoned"))
        }

        fn begin(&self, key: ToolOperationKey) -> Result<ToolCancellationLease, Fault> {
            let document_token = self.app_scope.child_now();
            let token = document_token.child_now();
            let publication_claim = ToolPublicationClaim::new();
            let index = Self::slot(key.document);
            let (superseded, generation) = {
                let mut state = self.try_state()?;
                if !state.allocation_admitted {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancellation-capacity"), "fixed cancellation slots were not admitted"));
                }
                if state.get(index).is_some_and(|scope| scope.document != key.document) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancellation-collision"), "fixed cancellation authority slot collision"));
                }
                let superseded = state.take(index);
                let generation = superseded.as_ref().map_or(0, |scope| scope.generation.saturating_add(1));
                state.insert_admitted(index, ToolDocumentCancellationScope { document: key.document, generation, token: document_token, publication_claim: publication_claim.clone(), operation: key.clone() });
                drop(state);
                (superseded, generation)
            };
            if let Some(scope) = superseded {
                scope.publication_claim.cancel();
                scope.token.cancel_now();
            } else {
                self.active.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
            }
            Ok(ToolCancellationLease { handle: self.clone(), document: key.document, document_generation: generation, key, token, publication_claim, document_claim: None, keyed: false, finished: false })
        }

        fn begin_keyed(&self, key: ToolOperationKey) -> Result<ToolCancellationLease, Fault> {
            let mut state = self.try_state()?;
            if !state.keyed_operations.can_insert(key.operation_id.0) {
                return Err(plugin_sdk_fault("keyed cancellation operation has no exact pre-admitted slot"));
            }
            let document_id = u64::from(key.document.0);
            if state.keyed_documents.get(document_id).is_none() {
                if !state.keyed_documents.can_insert(document_id) {
                    return Err(plugin_sdk_fault("keyed cancellation document has no exact pre-admitted slot"));
                }
                state.keyed_documents.insert_admitted(document_id, ToolKeyedDocumentCancellationScope { token: self.app_scope.child_now(), publication_claim: ToolPublicationClaim::new(), active: 0 });
            }
            let document = state.keyed_documents.get_mut(document_id).expect("exact keyed document was admitted");
            if document.token.is_cancelled_now() {
                document.token = self.app_scope.child_now();
                document.publication_claim = ToolPublicationClaim::new();
            }
            let token = document.token.child_now();
            let document_claim = document.publication_claim.clone();
            document.active += 1;
            let publication_claim = ToolPublicationClaim::new();
            state
                .keyed_operations
                .insert_admitted(key.operation_id.0, ToolDocumentCancellationScope { document: key.document, generation: key.generation.0, token: token.clone(), publication_claim: publication_claim.clone(), operation: key.clone() });
            self.active.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
            Ok(ToolCancellationLease { handle: self.clone(), document: key.document, document_generation: key.generation.0, key, token, publication_claim, document_claim: Some(document_claim), keyed: true, finished: false })
        }

        #[cfg(test)]
        pub(crate) fn test_begin(&self, key: ToolOperationKey) -> Result<TestToolCancellationLease, Fault> {
            self.begin(key).map(TestToolCancellationLease)
        }

        pub fn cancel(&self, key: &ToolOperationKey) -> Result<bool, Fault> {
            let detached = {
                let mut state = self.try_state()?;
                if let Some(scope) = state.keyed_operations.get(key.operation_id.0).filter(|scope| scope.operation == *key) {
                    scope.publication_claim.cancel();
                    scope.token.cancel_now();
                    return Ok(true);
                }
                let index = Self::slot(key.document);
                let detached = if state.get(index).is_some_and(|scope| scope.document == key.document && scope.operation == *key) { state.take(index) } else { None };
                drop(state);
                detached
            };
            if let Some(scope) = detached {
                self.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
                scope.publication_claim.cancel();
                scope.token.cancel_now();
                Ok(true)
            } else {
                Ok(false)
            }
        }

        pub fn active_operation_count(&self) -> usize {
            self.active.load(std::sync::atomic::Ordering::Acquire)
        }

        pub fn scope_generation(&self) -> u64 {
            self.app_generation.load(std::sync::atomic::Ordering::Acquire)
        }

        pub fn cancel_document(&self, document: ArtifactDocumentAuthority) -> Result<bool, Fault> {
            let (detached, keyed) = {
                let mut state = self.try_state()?;
                let keyed = if let Some(scope) = state.keyed_documents.get(u64::from(document.0)) {
                    scope.publication_claim.cancel();
                    scope.token.cancel_now();
                    true
                } else {
                    false
                };
                let index = Self::slot(document);
                let detached = if state.get(index).is_some_and(|scope| scope.document == document) { state.take(index) } else { None };
                drop(state);
                (detached, keyed)
            };
            if let Some(scope) = detached {
                self.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
                scope.publication_claim.cancel();
                scope.token.cancel_now();
                Ok(true)
            } else {
                Ok(keyed)
            }
        }

        fn renew_scope_generation(&mut self) {
            self.cancel_scope_generation();
            self.app_scope = semio_framework_job::CancelToken::root_now();
            self.publication_scope = ToolPublicationClaim::new();
        }

        pub fn cancel_scope_generation(&self) {
            self.publication_scope.cancel();
            self.app_scope.cancel_now();
            let _ = self.app_generation.try_update(std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire, |generation| Some(generation.saturating_add(1)));
        }

        fn cleanup_slot(&self, index: usize) -> Result<bool, Fault> {
            if index >= TOOL_CANCELLATION_SLOTS {
                let mut state = self.try_state()?;
                let Some(operation) = state.keyed_operations.id_at(index - TOOL_CANCELLATION_SLOTS) else {
                    return Ok(false);
                };
                let scope = state.keyed_operations.remove(operation).expect("exact keyed cancellation cleanup slot");
                scope.publication_claim.cancel();
                scope.token.cancel_now();
                let document_id = u64::from(scope.document.0);
                let document = state.keyed_documents.get_mut(document_id).expect("keyed cancellation cleanup retains document authority");
                document.active -= 1;
                if document.active == 0 {
                    drop(state.keyed_documents.remove(document_id));
                }
                self.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
                return Ok(true);
            }
            let detached = {
                let mut state = self.try_state()?;
                let detached = state.take(index);
                drop(state);
                detached
            };
            if let Some(scope) = detached {
                self.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
                scope.publication_claim.cancel();
                scope.token.cancel_now();
                Ok(true)
            } else {
                Ok(false)
            }
        }

        fn cleanup_finished_slot(&self, index: usize) -> Result<Option<bool>, Fault> {
            let mut state = match self.state.try_lock() {
                Ok(state) => state,
                Err(std::sync::TryLockError::WouldBlock) => return Ok(None),
                Err(std::sync::TryLockError::Poisoned(_)) => return Err(plugin_sdk_fault("finished cancellation authority is poisoned")),
            };
            let detached = if index < TOOL_CANCELLATION_SLOTS {
                if !state.get(index).is_some_and(|scope| scope.publication_claim.is_finished()) {
                    return Ok(Some(false));
                }
                state.take(index)
            } else {
                let Some(operation) = state.keyed_operations.id_at(index - TOOL_CANCELLATION_SLOTS) else {
                    return Ok(Some(false));
                };
                if !state.keyed_operations.get(operation).is_some_and(|scope| scope.publication_claim.is_finished()) {
                    return Ok(Some(false));
                }
                let scope = state.keyed_operations.remove(operation).expect("finished exact keyed cancellation owner");
                let document_id = u64::from(scope.document.0);
                let document = state.keyed_documents.get_mut(document_id).expect("finished keyed operation retains document count");
                document.active -= 1;
                if document.active == 0 {
                    drop(state.keyed_documents.remove(document_id));
                }
                Some(scope)
            };
            if detached.is_some() {
                self.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            }
            Ok(Some(detached.is_some()))
        }
    }

    struct ToolCancellationLease {
        handle: ToolCancellationHandle,
        document: ArtifactDocumentAuthority,
        document_generation: u64,
        key: ToolOperationKey,
        token: semio_framework_job::CancelToken,
        publication_claim: std::sync::Arc<ToolPublicationClaim>,
        document_claim: Option<std::sync::Arc<ToolPublicationClaim>>,
        keyed: bool,
        finished: bool,
    }

    impl ToolCancellationLease {
        async fn is_cancelled(&self) -> bool {
            self.token.is_cancelled().await
        }

        fn cancel_token(&self) -> semio_framework_job::CancelToken {
            self.token.child_now()
        }

        fn cancel(&self) {
            self.publication_claim.cancel();
            self.token.cancel_now();
        }

        fn rebind_keyed(&mut self, base_revision: semio_framework_job::RevisionId, generation: semio_framework_job::Generation) -> Result<bool, Fault> {
            let mut state = match self.handle.state.try_lock() {
                Ok(state) => state,
                Err(std::sync::TryLockError::WouldBlock) => return Ok(false),
                Err(std::sync::TryLockError::Poisoned(_)) => return Err(plugin_sdk_fault("keyed cancellation authority is poisoned")),
            };
            if !self.keyed || self.finished || self.publication_claim.is_cancelled() || self.token.is_cancelled_now() {
                return Err(plugin_sdk_fault("only a live exact keyed lease may rebind its revision"));
            }
            let scope = state.keyed_operations.get_mut(self.key.operation_id.0).ok_or_else(|| plugin_sdk_fault("keyed rebase lost its registered cancellation authority"))?;
            if scope.operation != self.key || !std::sync::Arc::ptr_eq(&scope.publication_claim, &self.publication_claim) {
                return Err(plugin_sdk_fault("keyed rebase does not own the registered cancellation authority"));
            }
            scope.operation.base_revision = base_revision;
            scope.operation.generation = generation;
            scope.generation = generation.0;
            self.key.base_revision = base_revision;
            self.key.generation = generation;
            self.document_generation = generation.0;
            Ok(true)
        }

        fn try_claim_publication(&self) -> Option<ToolPublicationScopePermit> {
            let app = self.handle.publication_scope.try_claim()?;
            let document = match self.document_claim.as_ref() {
                Some(claim) => Some(claim.try_claim()?),
                None => None,
            };
            let operation = self.publication_claim.try_claim()?;
            Some(ToolPublicationScopePermit { _app: app, _document: document, _operation: operation })
        }

        fn release_current(&self) {
            let Ok(mut state) = self.handle.state.try_lock() else { return };
            if self.keyed {
                if !state.keyed_operations.get(self.key.operation_id.0).is_some_and(|scope| scope.operation == self.key && std::sync::Arc::ptr_eq(&scope.publication_claim, &self.publication_claim)) {
                    return;
                }
                let detached = state.keyed_operations.remove(self.key.operation_id.0);
                if detached.is_some() {
                    let document_id = u64::from(self.document.0);
                    let document = state.keyed_documents.get_mut(document_id).expect("keyed operation retains its exact document scope");
                    document.active -= 1;
                    if document.active == 0 {
                        drop(state.keyed_documents.remove(document_id));
                    }
                    self.handle.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
                }
                return;
            }
            let index = ToolCancellationHandle::slot(self.document);
            let detached = if state.get(index).is_some_and(|scope| scope.document == self.document && scope.generation == self.document_generation && scope.operation == self.key) { state.take(index) } else { None };
            drop(state);
            if detached.is_some() {
                self.handle.active.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            }
        }

        fn finish(mut self) {
            self.publication_claim.finish();
            self.release_current();
            self.finished = true;
        }

        fn finish_in_place(&mut self) {
            self.publication_claim.finish();
            self.release_current();
            self.finished = true;
        }
    }

    #[cfg(test)]
    pub(crate) struct TestToolCancellationLease(ToolCancellationLease);

    #[cfg(test)]
    impl TestToolCancellationLease {
        pub(crate) fn cancel_token(&self) -> semio_framework_job::CancelToken {
            self.0.cancel_token()
        }

        pub(crate) fn finish(self) {
            self.0.finish();
        }
    }

    impl Drop for ToolCancellationLease {
        fn drop(&mut self) {
            if !self.finished {
                self.cancel();
            }
            self.publication_claim.finish();
            self.release_current();
        }
    }

    //#region 🗝️RetainedLatestWinsKeys
    use semio_framework_value::ordered as latest_wins_ordered;
    struct ToolLatestWinsKeyCopy {
        key: Option<String>,
        instance: u32,
        part: usize,
        offset: usize,
        prefix: usize,
    }

    impl ToolLatestWinsKeyCopy {
        fn new(instance: u32, parts: [&str; 4]) -> Result<Self, Fault> {
            let size = parts.iter().try_fold(8usize + 4 * 16, |size, part| part.len().checked_mul(2).and_then(|bytes| size.checked_add(bytes))).ok_or_else(|| plugin_sdk_fault("latest-wins exact key length overflow"))?;
            let mut key = String::new();
            key.try_reserve_exact(size).map_err(|_| plugin_sdk_fault("latest-wins exact key allocation was not admitted"))?;
            Ok(Self { key: Some(key), instance, part: 0, offset: 0, prefix: 0 })
        }

        fn advance(&mut self, parts: [&str; 4], maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 || maximum_bytes < 3 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            const HEX: &[u8; 16] = b"0123456789abcdef";
            let key = self.key.as_mut().expect("key copy retains its exact output until handoff");
            if self.part == 0 {
                let count = (8 - self.prefix).min(maximum_bytes);
                for _ in 0..count {
                    key.push(HEX[((self.instance >> (28 - self.prefix * 4)) & 15) as usize] as char);
                    self.prefix += 1;
                }
                if self.prefix == 8 {
                    self.part = 1;
                    self.prefix = 0;
                }
                return PluginCloseStep::Pending { released_items: 0, released_bytes: count };
            }
            if self.part > 4 {
                return PluginCloseStep::Complete;
            }
            let part = parts[self.part - 1].as_bytes();
            if self.prefix < 16 {
                let count = (16 - self.prefix).min(maximum_bytes);
                for _ in 0..count {
                    key.push(HEX[((part.len() as u64 >> (60 - self.prefix * 4)) & 15) as usize] as char);
                    self.prefix += 1;
                }
                return PluginCloseStep::Pending { released_items: 0, released_bytes: count };
            }
            if self.offset < part.len() {
                let count = (part.len() - self.offset).min(maximum_bytes / 3);
                for byte in &part[self.offset..self.offset + count] {
                    key.push(HEX[(byte >> 4) as usize] as char);
                    key.push(HEX[(byte & 15) as usize] as char);
                }
                self.offset += count;
                return PluginCloseStep::Pending { released_items: 0, released_bytes: count * 3 };
            }
            self.part += 1;
            self.offset = 0;
            self.prefix = 0;
            PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
        }

        fn take_key(&mut self) -> Option<std::sync::Arc<String>> {
            (self.part > 4).then(|| self.key.take()).flatten().map(std::sync::Arc::new)
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 || maximum_bytes == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(key) = self.key.as_mut() {
                if key.pop().is_some() {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 1 };
                }
                self.key = None;
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            PluginCloseStep::Complete
        }
    }

    struct ToolLatestWinsScope {
        key: std::sync::Arc<String>,
        operation: u64,
        token: semio_framework_job::CancelToken,
        claim: std::sync::Weak<ToolPublicationClaim>,
    }

    impl ToolLatestWinsScope {
        fn cancel(&self) {
            if let Some(claim) = self.claim.upgrade() {
                claim.cancel();
            }
            self.token.cancel_now();
        }
    }

    struct ToolLatestWinsRegistry {
        map: Option<semio_framework_value::ordered::OrderedMap<ToolLatestWinsScope>>,
        update: Option<semio_framework_value::ordered::UpdateCursor<ToolLatestWinsScope>>,
        retirement: Option<semio_framework_value::ordered::Retirement<ToolLatestWinsScope>>,
        retired_key: Option<String>,
        active_operation: Option<u64>,
        outcome: Option<(u64, bool)>,
        scan: usize,
        admission_scan: Option<usize>,
        update_closing: bool,
        closing: bool,
    }

    impl ToolLatestWinsRegistry {
        fn new() -> Self {
            Self { map: Some(semio_framework_value::ordered::OrderedMap::new()), update: None, retirement: None, retired_key: None, active_operation: None, outcome: None, scan: 0, admission_scan: None, update_closing: false, closing: false }
        }

        fn can_begin(&self) -> bool {
            !self.closing && self.update.is_none() && self.retirement.is_none() && self.retired_key.is_none() && self.outcome.is_none()
        }

        fn begin(&mut self, operation: u64, key: std::sync::Arc<String>, lease: &ToolCancellationLease) -> bool {
            if !self.can_begin() {
                return false;
            }
            if self.map.as_ref().expect("live key map").len() >= ARTIFACT_LIVE_OUTPUT_SLOTS {
                match self.admission_scan {
                    None => {
                        self.admission_scan = Some(ARTIFACT_LIVE_OUTPUT_SLOTS);
                        return false;
                    }
                    Some(0) => {}
                    Some(_) => return false,
                }
            }
            let scope = ToolLatestWinsScope { key: key.clone(), operation, token: lease.token.clone(), claim: std::sync::Arc::downgrade(&lease.publication_claim) };
            self.update = Some(self.map.as_ref().expect("live key map").begin_set_shared(key, std::sync::Arc::new(scope)));
            self.active_operation = Some(operation);
            self.update_closing = false;
            true
        }

        fn take_outcome(&mut self, operation: u64) -> Option<bool> {
            if self.outcome.is_some_and(|(owner, _)| owner == operation) {
                self.outcome.take().map(|(_, accepted)| accepted)
            } else {
                None
            }
        }

        fn cancel(&mut self, operation: u64) {
            if self.active_operation == Some(operation) && !self.update_closing {
                if let Some(update) = self.update.as_mut() {
                    update.begin_close();
                }
                self.update_closing = true;
                self.outcome = Some((operation, false));
            }
        }

        fn retire_scope(&mut self, scope: ToolLatestWinsScope) {
            self.retired_key = std::sync::Arc::into_inner(scope.key);
        }

        fn retirement_step(&mut self, step: semio_framework_value::ordered::RetirementStep<ToolLatestWinsScope>) -> PluginCloseStep {
            match step {
                semio_framework_value::ordered::RetirementStep::Blocked => PluginCloseStep::Blocked { reason: "latest-wins key retirement has no grant" },
                semio_framework_value::ordered::RetirementStep::Progress { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                semio_framework_value::ordered::RetirementStep::OwnedValue(scope) => {
                    self.retire_scope(scope);
                    PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
                }
                semio_framework_value::ordered::RetirementStep::Complete => PluginCloseStep::Complete,
            }
        }

        fn advance(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 || maximum_bytes == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            let grant = semio_framework_value::ordered::Grant { maximum_items: maximum_items.min(1), maximum_bytes };
            if let Some(key) = self.retired_key.as_mut() {
                if key.pop().is_some() {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 1 };
                }
                self.retired_key = None;
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(retirement) = self.retirement.as_mut() {
                let step = retirement.advance(grant);
                if matches!(step, semio_framework_value::ordered::RetirementStep::Complete) {
                    self.retirement = None;
                }
                return self.retirement_step(step);
            }
            if let Some(update) = self.update.as_mut() {
                if self.update_closing {
                    let step = update.close_step(grant);
                    if matches!(step, semio_framework_value::ordered::RetirementStep::Complete) {
                        assert!(update.terminal_is_empty());
                        self.update = None;
                        self.active_operation = None;
                        self.update_closing = false;
                    }
                    return self.retirement_step(step);
                }
                if !update.is_complete() {
                    return match update.advance(grant) {
                        semio_framework_value::ordered::Step::Blocked => PluginCloseStep::Blocked { reason: "latest-wins exact comparison has no grant" },
                        semio_framework_value::ordered::Step::Progress { completed_items, completed_bytes } => PluginCloseStep::Pending { released_items: completed_items, released_bytes: completed_bytes },
                        semio_framework_value::ordered::Step::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                    };
                }
                let candidate = update.take_result().expect("complete exact key update retains its candidate");
                self.admission_scan = None;
                if candidate.len() > ARTIFACT_LIVE_OUTPUT_SLOTS {
                    self.retirement = Some(candidate.retire());
                    if let Some(operation) = self.active_operation {
                        self.outcome = Some((operation, false));
                    }
                } else {
                    let previous = self.map.replace(candidate).expect("live exact key map");
                    self.retirement = Some(previous.retire());
                    if let Some(scope) = update.take_removed() {
                        if self.active_operation.is_some_and(|operation| operation != scope.operation) {
                            scope.cancel();
                        }
                    }
                    if let Some(operation) = self.active_operation {
                        self.outcome = Some((operation, true));
                    }
                }
                update.begin_close();
                self.update_closing = true;
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.closing {
                if let Some(map) = self.map.take() {
                    self.retirement = Some(map.retire());
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                return PluginCloseStep::Complete;
            }
            let map = self.map.as_ref().expect("live exact key map");
            if map.is_empty() {
                self.scan = 0;
                return PluginCloseStep::Complete;
            }
            self.scan %= map.len();
            let (_, scope) = map.entry_at_rank(self.scan).expect("fixed metadata rank within key map");
            self.scan += 1;
            if let Some(remaining) = self.admission_scan.as_mut() {
                *remaining = remaining.saturating_sub(1);
            }
            if scope.claim.strong_count() == 0 {
                self.update = Some(map.begin_remove_shared(scope.key.clone()));
                self.update_closing = false;
            }
            PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
        }

        fn begin_close(&mut self) {
            self.closing = true;
            if let Some(update) = self.update.as_mut() {
                update.begin_close();
                self.update_closing = true;
            }
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.map.is_none() && self.update.is_none() && self.retirement.is_none() && self.retired_key.is_none()
        }
    }
    //#endregion 🗝️RetainedLatestWinsKeys

    struct FrameworkReservedCommitPermit {
        operation: semio_framework_job::Operation,
        lease: ToolCancellationLease,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ActiveMediaExportCloseStage {
        Live,
        Worker,
        DisposeJob,
        DrainChunks,
        DrainCompletion,
        Complete,
    }

    struct ActiveMediaExport {
        handle: ArtifactMediaExportHandle,
        port: String,
        operation: semio_framework_job::Operation,
        contract: semio_framework::ToolExecutionContract,
        session: Option<semio_framework_job::MountedWorkerJobSession<semio_framework::ErasedToolJob>>,
        session_rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<semio_framework::ErasedToolJob>>,
        closing_job: Option<ArtifactReservedToolJob>,
        retained_outcome: Option<semio_framework_job::StepOutcome>,
        output_credit: ArtifactMediaExportCredit,
        output_chunks: ArtifactOutputChunks,
        completion: ArtifactMediaExportCompletion,
        lease: ToolCancellationLease,
        checkpoint_available: bool,
        applied_progress: u64,
        close_stage: ActiveMediaExportCloseStage,
    }

    impl ActiveMediaExport {
        fn running_poll(&self) -> ArtifactMediaExportPoll {
            ArtifactMediaExportPoll::Running { applied_progress: self.applied_progress, checkpoint_available: self.checkpoint_available }
        }

        fn retire_nonterminal_outcome(&mut self) -> Result<PluginCloseStep, Fault> {
            let Some(outcome) = self.retained_outcome.as_mut() else {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            };
            if outcome.is_terminal() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-terminal-retirement"), "terminal media outcome cannot resume its mounted job"));
            }
            let step = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if outcome.terminal_is_empty() {
                self.retained_outcome = None;
                let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-session-missing"), "media outcome handback lost its mounted session"))?;
                session.resume().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-resume-contention"), "media outcome handback is contended"))?;
            }
            Ok(match step {
                semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                semio_framework_job::JobPayloadCloseStep::Complete => PluginCloseStep::Pending { released_items: 0, released_bytes: 0 },
            })
        }

        fn terminal_is_empty(&self) -> Result<bool, Fault> {
            Ok(self.close_stage == ActiveMediaExportCloseStage::Complete
                && self.session.is_none()
                && self.session_rejected.is_none()
                && self.retained_outcome.as_ref().is_none_or(semio_framework_job::StepOutcome::terminal_is_empty)
                && self.closing_job.as_ref().is_none_or(ArtifactReservedToolJob::terminal_is_empty)
                && self.output_chunks.chunks_remaining() == 0
                && self.output_chunks.bytes_remaining() == 0
                && self.completion.terminal_is_empty()?
                && !self.checkpoint_available)
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            match self.close_stage {
                ActiveMediaExportCloseStage::Live => {
                    self.lease.cancel();
                    if let Some(session) = self.session.as_mut() {
                        session.begin_close();
                    }
                    self.close_stage = ActiveMediaExportCloseStage::Worker;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                ActiveMediaExportCloseStage::Worker => {
                    if let Some(outcome) = self.retained_outcome.as_mut() {
                        let step = outcome.close_step(maximum_items.min(1), maximum_bytes);
                        if outcome.terminal_is_empty() {
                            self.retained_outcome = None;
                        }
                        return Ok(match step {
                            semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                            semio_framework_job::JobPayloadCloseStep::Complete => PluginCloseStep::Pending { released_items: 0, released_bytes: 0 },
                        });
                    }
                    if let Some(rejected) = self.session_rejected.as_mut() {
                        let step = rejected.close_step(maximum_items.min(1), maximum_bytes);
                        if rejected.terminal_is_empty() {
                            self.session_rejected = None;
                        }
                        return Ok(match step {
                            semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                            semio_framework_job::InteractiveJobCloseStep::Blocked => PluginCloseStep::Blocked { reason: "media export rejected session close is blocked" },
                            semio_framework_job::InteractiveJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                        });
                    }
                    if let Some(session) = self.session.as_mut() {
                        let step = session.close_step(maximum_items.min(1), maximum_bytes);
                        if session.terminal_is_empty() {
                            self.session = None;
                        }
                        return Ok(match step {
                            semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                            semio_framework_job::WorkerJobCloseStep::Blocked => PluginCloseStep::Blocked { reason: "media export mounted session close is blocked" },
                            semio_framework_job::WorkerJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                        });
                    }
                    self.close_stage = ActiveMediaExportCloseStage::DisposeJob;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                ActiveMediaExportCloseStage::DisposeJob => {
                    let Some(job) = self.closing_job.as_mut() else {
                        self.close_stage = ActiveMediaExportCloseStage::DrainChunks;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    };
                    match job.close_step(maximum_items, maximum_bytes)? {
                        PluginCloseStep::Complete => {
                            drop(self.closing_job.take());
                            self.close_stage = ActiveMediaExportCloseStage::DrainChunks;
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                        step => Ok(step),
                    }
                }
                ActiveMediaExportCloseStage::DrainChunks => {
                    if maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    match self.output_chunks.close_take_chunk()? {
                        Some(chunk) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: chunk.len() }),
                        None => {
                            self.close_stage = ActiveMediaExportCloseStage::DrainCompletion;
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                    }
                }
                ActiveMediaExportCloseStage::DrainCompletion => match self.completion.close_step(maximum_items, maximum_bytes)? {
                    PluginCloseStep::Complete => {
                        self.checkpoint_available = false;
                        self.close_stage = ActiveMediaExportCloseStage::Complete;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    step => Ok(step),
                },
                ActiveMediaExportCloseStage::Complete => Ok(PluginCloseStep::Complete),
            }
        }
    }

    pub(crate) const ARTIFACT_LIVE_OUTPUT_SLOTS: usize = 64;

    pub(crate) struct ArtifactFixedRegistry<T> {
        slots: Box<[std::mem::MaybeUninit<(u64, T)>]>,
        occupied: u64,
        allocation_admitted: bool,
    }

    impl<T> ArtifactFixedRegistry<T> {
        /// 🪹️ Reserves every slot on the heap while leaving the occupied mask as the sole
        /// initialization witness. A successful exact reservation provides capacity for all slots;
        /// `MaybeUninit` permits extending their length without values. Insertion writes before setting
        /// a bit, removal clears the bit before reading, and the zero initial mask prevents every read.
        fn new() -> Self {
            let mut slots = Vec::<std::mem::MaybeUninit<(u64, T)>>::new();
            let allocation_admitted = slots.try_reserve_exact(ARTIFACT_LIVE_OUTPUT_SLOTS).is_ok();
            if allocation_admitted {
                unsafe { slots.set_len(ARTIFACT_LIVE_OUTPUT_SLOTS) };
            }
            Self { slots: slots.into_boxed_slice(), occupied: 0, allocation_admitted }
        }

        fn occupied(&self, index: usize) -> bool {
            self.occupied & (1u64 << index) != 0
        }

        /// 🧿️ SAFETY: the occupied bit is set only after `write` and cleared before `assume_init_read`.
        fn entry(&self, index: usize) -> Option<&(u64, T)> {
            if !self.occupied(index) {
                return None;
            }
            self.slots.get(index).map(|slot| unsafe { slot.assume_init_ref() })
        }

        /// 🖋️ SAFETY: the occupied bit is set only after `write` and cleared before `assume_init_read`.
        fn entry_mut(&mut self, index: usize) -> Option<&mut (u64, T)> {
            if !self.occupied(index) {
                return None;
            }
            self.slots.get_mut(index).map(|slot| unsafe { slot.assume_init_mut() })
        }

        #[cfg(test)]
        pub(crate) fn insert(&mut self, id: u64, value: T) -> Result<(), T> {
            if !self.allocation_admitted {
                return Err(value);
            }
            let index = id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS;
            if self.entry(index).is_some() {
                return Err(value);
            }
            self.slots[index].write((id, value));
            self.occupied |= 1u64 << index;
            Ok(())
        }

        fn can_insert(&self, id: u64) -> bool {
            self.slot_is_vacant(id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS)
        }

        /// 🎰️ Whether one residue class of this direct-mapped table owns no live value — the per-slot
        /// question an admitting caller asks before it mints an id for that slot.
        fn slot_is_vacant(&self, slot: usize) -> bool {
            self.allocation_admitted && self.entry(slot).is_none()
        }

        pub(crate) fn insert_admitted(&mut self, id: u64, value: T) {
            let index = id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS;
            assert!(self.can_insert(id), "fixed artifact registry admission changed before exact owner insertion");
            self.slots[index].write((id, value));
            self.occupied |= 1u64 << index;
        }

        pub(crate) fn get(&self, id: u64) -> Option<&T> {
            self.entry(id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS).and_then(|(candidate, value)| (*candidate == id).then_some(value))
        }

        fn get_mut(&mut self, id: u64) -> Option<&mut T> {
            self.entry_mut(id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS).and_then(|(candidate, value)| (*candidate == id).then_some(value))
        }

        fn has_capacity(&self) -> bool {
            self.allocation_admitted && self.occupied != u64::MAX
        }

        /// ➖️ SAFETY: exact identity and occupied state were checked, and the bit is now cleared.
        fn remove(&mut self, id: u64) -> Option<T> {
            let index = id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS;
            if self.entry(index).is_none_or(|(candidate, _)| *candidate != id) {
                return None;
            }
            self.occupied &= !(1u64 << index);
            Some(unsafe { self.slots[index].assume_init_read().1 })
        }

        fn id_at(&self, index: usize) -> Option<u64> {
            self.entry(index).map(|(id, _)| *id)
        }

        fn each_id(&self, mut visit: impl FnMut(u64)) {
            for index in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
                if let Some(id) = self.id_at(index) {
                    visit(id);
                }
            }
        }

        fn next_id_from(&self, cursor: usize) -> Option<(usize, u64)> {
            if self.occupied == 0 {
                return None;
            }
            let offset = self.occupied.rotate_right(cursor as u32).trailing_zeros() as usize;
            let index = (cursor + offset) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            self.id_at(index).map(|id| (index, id))
        }

        pub(crate) fn is_empty(&self) -> bool {
            self.occupied == 0
        }

        /// 🔢️ Admitted entries — the occupied mask's population.
        pub(crate) fn len(&self) -> usize {
            self.occupied.count_ones() as usize
        }

        #[cfg(test)]
        pub(crate) fn contains(&self, id: u64) -> bool {
            self.get(id).is_some()
        }
    }

    impl<T> Drop for ArtifactFixedRegistry<T> {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.is_empty(), "fixed artifact owner registry reached Drop before every exact owner was transferred to bounded retirement");
        }
    }

