    /// 🧾️ A framework-reserved route whose spawned job finished and whose commit the app now owns.
    /// [`VcsArtifactApp::step_framework_reserved_commit`] advances it one bounded unit per call from the
    /// reactor's typed-operation continuation, so a commit that fans out over composed children
    /// (checkpoint pins, checkout cascade) or walks history (revert) is driven across turns instead of
    /// having to finish inside the turn that saw its `JobCompleted`. Every unit re-reads the
    /// operation's cancellation lease, and `applied`/`total` is its progress.
    struct FrameworkReservedCommit {
        action: String,
        args: Option<DslValue>,
        meta: ActionMeta,
        permit: FrameworkReservedCommitPermit,
        log_generation_before: u64,
        stage: FrameworkReservedCommitStage,
        applied: u64,
        total: u64,
    }

    /// 🪜️ The next unit a [`FrameworkReservedCommit`] runs.
    enum FrameworkReservedCommitStage {
        Validate,
        CheckpointChildren { message: String, authors: Vec<vcs::Author>, keys: Vec<(String, String)>, next: usize, pins: Vec<vcs::CompositionPin> },
        Route { pins: Vec<vcs::CompositionPin> },
        CheckoutChildren { pins: Vec<vcs::CompositionPin>, next: usize, result: InvocationResult },
        Revert { edit_id: String },
    }

    /// 📊️ Progress of the framework-reserved commit at the head of an app's commit queue: `applied` of
    /// `total` bounded units, for the operation that admitted it.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct FrameworkReservedCommitProgress {
        pub operation: u64,
        pub applied: u64,
        pub total: u64,
    }

    /// ⏱️ The whole-run wall budget of one agent-lane preview. A preview answers an agent's `action_prepare` inside one
    /// guest call, so a job still running past it is refused by name (`interactive-job.preview-budget`) instead of
    /// holding the gateway; its human runs it from the shell, where the job keeps its progress and cancellation.
    pub(crate) const AGENT_LANE_PREVIEW_WALL_US: u64 = 2_000_000;

    /// 🔢️ The turn budget of one agent-lane preview — the same refusal on a host whose clock cannot be read, and the
    /// bound of every close loop the preview runs.
    pub(crate) const AGENT_LANE_PREVIEW_TURNS: u64 = 65_536;

    /// 🧭️ The refusal for a verb whose previewed result publishes `lanes` an agent transaction cannot carry.
    fn agent_lane_uncarried_fault(verb: &str, lanes: &str) -> Fault {
        Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.agent-lane-uncarried"), format!("action '{verb}' publishes {lanes} that an agent transaction cannot carry; it runs only from the shell"))
    }

    /// 🫥️ The refusal for a verb whose previewed result carries no operation and only presents something to the human who
    /// ran it (a notice, a selection): in this state the command changes nothing. Each notice the app would have shown
    /// rides the fault as its own structured cause (`app.notice`), never concatenated into the message, so a host renders
    /// the app's own words beside its localized text for `app.command.no-effect`.
    fn agent_lane_no_effect_fault(verb: &str, effects: &[Effect]) -> Fault {
        let mut fault = Fault::new(FaultOrigin::App, FaultCode::new("app.command.no-effect"), format!("action '{verb}' changes nothing here"));
        fault.causes = effects.iter().filter_map(|effect| if let Effect::Notify { message } = effect { Some(semio_framework::FaultCause { message: message.clone(), code: Some(FaultCode::new("app.notice")) }) } else { None }).collect();
        fault
    }

    /// ⚖️ What the agent lane answers for one previewed publication ([`agent_lane_carriage`]).
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub(crate) enum AgentLaneCarriage {
        /// ✅️ Everything it publishes rides the transaction; presentation beside carried operations is omitted.
        Carried,
        /// 🫥️ It carries no operation and only presents something to the human who ran it — refused `app.command.no-effect`.
        NoEffect,
        /// 🚧️ It publishes these lanes the transaction cannot carry — refused `interactive-job.agent-lane-uncarried`.
        Uncarried(Vec<&'static str>),
    }

    /// ⚖️ The agent lane's verdict on one previewed publication: carried when [`agent_lane_uncarried_lanes`] names nothing,
    /// no effect when it names only [`AGENT_LANE_PRESENTATION_LANES`] and nothing is carried, uncarried otherwise.
    pub(crate) fn agent_lane_carriage(publication: &AgentLanePublication<'_>) -> AgentLaneCarriage {
        let lanes = agent_lane_uncarried_lanes(publication);
        if lanes.is_empty() {
            AgentLaneCarriage::Carried
        } else if publication.carried_ops == 0 && lanes.iter().all(|lane| AGENT_LANE_PRESENTATION_LANES.contains(lane)) {
            AgentLaneCarriage::NoEffect
        } else {
            AgentLaneCarriage::Uncarried(lanes)
        }
    }

    /// 📦️ What one previewed command publishes: how many operations an agent transaction carries (its document, config
    /// and draft ops and owned-child groups), its host effects and the size of every other lane — the shape
    /// [`agent_lane_uncarried_lanes`] judges.
    pub(crate) struct AgentLanePublication<'a> {
        pub carried_ops: usize,
        pub effects: &'a [Effect],
        pub window_config_ops: usize,
        pub extension_calls: usize,
        pub events: usize,
        pub selection_writes: usize,
        pub tasks: usize,
        pub presence: usize,
        pub transient: usize,
        pub window_transient: usize,
    }

    /// 🪞️ The lanes that only present a command's result to the human who ran it — a notice, a selection of what it made.
    /// Beside operations the transaction carries they are omitted (an agent reads its result from the prepared report);
    /// on their own they are the command's whole effect, and the agent lane refuses them like any other uncarried lane.
    pub(crate) const AGENT_LANE_PRESENTATION_LANES: [&str; 2] = ["a notice", "selection changes"];

    /// 🏷️ Every lane an agent transaction cannot carry, in the order a refusal names them.
    pub(crate) const AGENT_LANE_UNCARRIED_LANES: [&str; 17] = [
        "a whole-document replacement",
        "a file download",
        "a file request",
        "a follow-up dispatch",
        "a dialog",
        "a notice",
        "a clipboard write",
        "a shell change",
        "a host request",
        "extension calls",
        "app events",
        "selection changes",
        "window configuration changes",
        "follow-up tasks",
        "presence changes",
        "transient state changes",
        "window transient state changes",
    ];

    /// 🚧️ The agent lane fails closed: the lanes of one previewed command its transaction cannot carry, each once, in
    /// [`AGENT_LANE_UNCARRIED_LANES`] order. The carried set is enumerated, not inferred — only document, config, draft and
    /// owned-child ops ride an agent transaction — so every host effect is named by an exhaustive match (a new [`Effect`]
    /// variant does not compile until it is classified; a guest-emitted interaction verb, [`is_inline_interaction_verb`], is
    /// a selection change whichever effect carries it) and every other non-empty lane is named too, except the
    /// [`AGENT_LANE_PRESENTATION_LANES`] beside carried operations. The preview settles only on an empty answer; anything
    /// else is refused `interactive-job.agent-lane-uncarried`, so an agent is never told "done" for a verb whose shell run
    /// acts where its transaction would do nothing. Language-agnostic fixture: `🧫️fixtures/🤖️agent-lane-carriage.json`.
    pub(crate) fn agent_lane_uncarried_lanes(publication: &AgentLanePublication<'_>) -> Vec<&'static str> {
        let effect_lanes = publication.effects.iter().map(|effect| match effect {
            _ if is_inline_interaction_verb(effect) => "selection changes",
            Effect::LoadDocument { .. } => "a whole-document replacement",
            Effect::DownloadMediaExport { .. } | Effect::IconRenderExport { .. } | Effect::VideoRenderExport { .. } => "a file download",
            Effect::RequestFileOpen { .. } | Effect::RequestMediaFrames { .. } => "a file request",
            Effect::DispatchAction { .. } => "a follow-up dispatch",
            Effect::OpenDialog { .. } => "a dialog",
            Effect::Notify { .. } => "a notice",
            Effect::ClipboardWrite { .. } => "a clipboard write",
            Effect::OpenWindow { .. }
            | Effect::CloseWindow { .. }
            | Effect::SetPanel { .. }
            | Effect::Navigate { .. }
            | Effect::OpenExternalUrl { .. }
            | Effect::SpawnPluginInstance { .. }
            | Effect::OpenPluginInstance { .. }
            | Effect::SetActiveUtility { .. }
            | Effect::SetActiveTool { .. }
            | Effect::ReplayShellCommand { .. } => "a shell change",
            Effect::RequestSync
            | Effect::SendMessage { .. }
            | Effect::PublishEvent { .. }
            | Effect::BlobWrite { .. }
            | Effect::BlobLoad { .. }
            | Effect::HttpRequest { .. }
            | Effect::DocumentRead { .. }
            | Effect::DocumentWrite { .. }
            | Effect::LinkResolve { .. }
            | Effect::RegistryQuery { .. }
            | Effect::IoCompose { .. }
            | Effect::CacheDerive { .. }
            | Effect::CacheRead { .. }
            | Effect::SetTimer { .. }
            | Effect::SpawnJob { .. }
            | Effect::CancelJob { .. }
            | Effect::Respond { .. }
            | Effect::StorageRead { .. }
            | Effect::StorageWrite { .. }
            | Effect::StorageDelete { .. }
            | Effect::RequestCapability { .. }
            | Effect::ReleaseCapability { .. }
            | Effect::Subscribe { .. }
            | Effect::Unsubscribe { .. }
            | Effect::RequestServiceOperation { .. } => "a host request",
            Effect::InvokeExtension { .. } => "extension calls",
        });
        let counted = [
            ("extension calls", publication.extension_calls),
            ("app events", publication.events),
            ("selection changes", publication.selection_writes),
            ("window configuration changes", publication.window_config_ops),
            ("follow-up tasks", publication.tasks),
            ("presence changes", publication.presence),
            ("transient state changes", publication.transient),
            ("window transient state changes", publication.window_transient),
        ]
        .into_iter()
        .filter(|(_, count)| *count != 0)
        .map(|(lane, _)| lane);
        let found = effect_lanes.chain(counted).collect::<std::collections::BTreeSet<_>>();
        AGENT_LANE_UNCARRIED_LANES.into_iter().filter(|lane| found.contains(lane) && (publication.carried_ops == 0 || !AGENT_LANE_PRESENTATION_LANES.contains(lane))).collect()
    }

    /// 🏃️ Drives one previewed job on the calling turn through the SAME [`semio_framework_job::BatchJobSession`] step,
    /// checkpoint and close protocol a worker runs: every step is bounded by the job's own contract (`params.config`),
    /// the run by [`AGENT_LANE_PREVIEW_WALL_US`], [`AGENT_LANE_PREVIEW_TURNS`] and `params.cancel`, and every progress,
    /// checkpoint or yield payload is released before the next step. Answers how many outcomes the job reported up to
    /// and including its completion. A job fault answers what the shell's fault page carries
    /// ([`decode_typed_operation_fault_page`] over the job's bounded detail), except that a retained reducer refusal
    /// answers the reducer's own code ([`crate::retained_command::reducer_fault_of_detail`]); a cancellation, an
    /// exhausted budget or a lost step is refused by name. The session is closed on every path: to terminal-empty, or
    /// handed to the worker-session retirement pump when its close stalls.
    struct ChildEmissionPreviewJob<A:ArtifactApp>{
        emit:Option<Emit<A::Mutation,A::ConfigMutation,A::DraftMutation>>,
        ephemeral:Option<EphemeralEmit<A>>,
        completion:Option<ArtifactToolCompletion<A>>,
        maximum_bytes:usize,
        closing:bool,
    }
    impl<A:ArtifactApp> semio_framework_job::InteractiveJob for ChildEmissionPreviewJob<A>{
        fn step(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->semio_framework_job::StepOutcome{
            use semio_framework_job::{StepOutcome,JobPayloadStream,RetainedJobPayload,CommitCandidate,JobFault};
            if cx.is_cancelled(){return StepOutcome::Cancelled;}
            if cx.should_yield(){return StepOutcome::Yield;}
            let Some(emit)=self.emit.as_mut()else{return StepOutcome::Complete(CommitCandidate{state:RetainedJobPayload::empty(JobPayloadStream::CommitState),output:RetainedJobPayload::empty(JobPayloadStream::CommitOutput)})};
            cx.set_stage("agent-child-emission-preparation");
            let demand=emit.next_child_preparation_byte_demand().max(1);
            let step=if demand>self.maximum_bytes{Err(plugin_sdk_fault("child emission exceeds its captured preview output allocation authority"))}else{emit.prepare_child_one(1,demand)};
            cx.consume_fuel(1);
            match step{
                Ok(ChildEmitPreparationStep::Pending)=>StepOutcome::Yield,
                Ok(ChildEmitPreparationStep::Ready)=>{
                    let Some(completion)=self.completion.as_ref()else{return StepOutcome::Cancelled};
                    let Some(ephemeral)=self.ephemeral.take()else{return StepOutcome::Cancelled};
                    let emit=self.emit.take().expect("ready preview retains its complete emission");
                    if let Err(rejected)=completion.complete(Ok(emit),ephemeral){
                        self.emit=rejected.emit.ok();self.ephemeral=Some(rejected.ephemeral);
                        return child_emission_preview_fault(cx,&rejected.fault);
                    }
                    StepOutcome::Complete(CommitCandidate{state:RetainedJobPayload::empty(JobPayloadStream::CommitState),output:RetainedJobPayload::empty(JobPayloadStream::CommitOutput)})
                },
                Ok(ChildEmitPreparationStep::Refused(fault))|Err(fault)=>child_emission_preview_fault(cx,&fault),
            }
        }
        fn begin_close(&mut self){self.closing=true;}
        fn close_step(&mut self,maximum_items:usize,maximum_bytes:usize)->semio_framework_job::InteractiveJobCloseStep{
            use semio_framework_job::InteractiveJobCloseStep;
            if !self.closing{return InteractiveJobCloseStep::Blocked;}
            if maximum_items==0||maximum_bytes==0{return InteractiveJobCloseStep::Pending{released_items:0,released_bytes:0};}
            if let Some(emit)=self.emit.as_mut(){
                if let Some(step)=emit.close_child_one(maximum_items.min(1),maximum_bytes){
                    return match step{PluginCloseStep::Pending{released_items,released_bytes}=>InteractiveJobCloseStep::Pending{released_items,released_bytes},PluginCloseStep::Complete=>InteractiveJobCloseStep::Pending{released_items:0,released_bytes:0},_=>InteractiveJobCloseStep::Blocked};
                }
                self.emit.take();return InteractiveJobCloseStep::Pending{released_items:1,released_bytes:0};
            }
            if self.ephemeral.take().is_some(){return InteractiveJobCloseStep::Pending{released_items:1,released_bytes:0};}
            if self.completion.take().is_some(){return InteractiveJobCloseStep::Pending{released_items:1,released_bytes:0};}
            InteractiveJobCloseStep::Complete
        }
        fn terminal_is_empty(&self)->bool{self.emit.is_none()&&self.ephemeral.is_none()&&self.completion.is_none()}
    }
    fn child_emission_preview_fault(cx:&mut semio_framework_job::StepContext<'_>,fault:&Fault)->semio_framework_job::StepOutcome{
        let detail=crate::retained_command::reducer_fault_detail(fault);
        let payload=cx.payload_from_bytes(semio_framework_job::JobPayloadStream::Fault,&detail).unwrap_or_else(|_|semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::Fault));
        semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault{detail:payload})
    }

    fn drive_agent_lane_preview<J: semio_framework_job::InteractiveJob + 'static>(job: J, params: semio_framework_job::BatchJobParams, verb: &str) -> Result<u64, Fault> {
        let now_us = params.now_us;
        let started_us = now_us();
        let mut session = match semio_framework_job::BatchJobSession::try_new(job, params) {
            Ok(session) => session,
            Err(mut rejected) => {
                for _ in 0..AGENT_LANE_PREVIEW_TURNS {
                    if rejected.terminal_is_empty() {
                        break;
                    }
                    let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
                }
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.admission-capacity"), format!("the preview of action '{verb}' found every worker session slot in use")));
            }
        };
        let lost_step =
            |contention: semio_framework_job::WorkerJobContention| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.preview-step"), format!("the previewed job of action '{verb}' lost its caller-driven step: {contention:?}"));
        let mut outcomes = 0_u64;
        let mut turns = 0_u64;
        let verdict = loop {
            turns += 1;
            if turns > AGENT_LANE_PREVIEW_TURNS || started_us.zip(now_us()).is_some_and(|(started, now)| now.saturating_sub(started) >= AGENT_LANE_PREVIEW_WALL_US) {
                break Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.preview-budget"), format!("the previewed job of action '{verb}' did not complete within the agent lane's budget; it runs only from the shell")));
            }
            if let Err(contention) = session.step() {
                break Err(lost_step(contention));
            }
            let Some(mut outcome) = session.take_outcome() else { continue };
            outcomes += 1;
            let terminal = match &outcome {
                semio_framework_job::StepOutcome::Complete(_) => Some(Ok(outcomes)),
                semio_framework_job::StepOutcome::Cancelled => Some(Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancelled"), format!("the preview of action '{verb}' was cancelled")))),
                semio_framework_job::StepOutcome::Fault(fault) => {
                    let payload = ArtifactBoundedToolFault::from_payload(&fault.detail);
                    Some(Err(crate::retained_command::reducer_fault_of_detail(payload.as_bytes()).unwrap_or_else(|| decode_typed_operation_fault_page(payload.as_bytes()))))
                }
                semio_framework_job::StepOutcome::Yield | semio_framework_job::StepOutcome::PreviewReady(_) | semio_framework_job::StepOutcome::CheckpointReady(_) => None,
            };
            for _ in 0..AGENT_LANE_PREVIEW_TURNS {
                if outcome.terminal_is_empty() {
                    break;
                }
                let _ = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            }
            if let Some(verdict) = terminal {
                break verdict;
            }
            if let Err(contention) = session.resume() {
                break Err(lost_step(contention));
            }
        };
        session.begin_close();
        for _ in 0..AGENT_LANE_PREVIEW_TURNS {
            if session.terminal_is_empty() {
                return verdict;
            }
            let _ = session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
        }
        verdict.and(Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.preview-close"), format!("the previewed job of action '{verb}' did not close; the worker-session retirement pump finishes it"))))
    }

