    /// 🧩️ UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM (C1): what ONE composed gesture's linearized
    /// publication actually produced — the parent's `KernelMutation`s under its own
    /// `ArtifactHandle` PLUS one per touched child under the child's content-addressed handle, and
    /// the single `UndoGroup` whose `member_edits` name every document the gesture committed to.
    ///
    /// 🎯️ Why it is retained instead of returned: on the migrated route `dispatch_typed` only
    /// ADMITS, so the composed dispatch happens turns later inside the publication ladder, long
    /// after the caller's `InvocationResult` was handed back. `dispatch_emit_group` builds this
    /// whole thing and the ladder used to keep three scalars of it
    /// (`ChildPublicationResultV1`) and DROP the rest, so the child lane of a composite gesture
    /// existed in the documents and in history but was invisible to every host-visible result
    /// (`📓️fp10-plugin-lib-and-lanes.md` §2.3). It now rides the same bounded host outbox the
    /// effect, event, UI-scope and terminal-completion lanes ride, and is drained by the app's own
    /// close ladder.
    ///
    /// 🚫️ Deliberately NOT counted by `has_pending_typed_operations`: the composed result is
    /// published in the SAME unit that queues the `Child` result page, so the operation's own ACK
    /// already keeps the actor runnable until a host that wants it has had its turn to take it — and
    /// a driver that loops until nothing is pending while never reading this lane (the live-cleanup
    /// pump does exactly that) would otherwise spin forever on a lane it does not own.
    pub struct ComposedGestureResult {
        pub operation: u64,
        pub mutations: Vec<KernelMutation>,
        pub inverse_group: UndoGroup,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum PendingChildGroupPublicationPhase {
        Ready,
        Dispatching,
        Committed,
        Acknowledged,
        Faulted,
        Closing,
    }

    struct PendingChildGroupPublication<A: ArtifactApp> {
        artifact_mutations: Vec<A::Mutation>,
        child_emits: Vec<ChildEmit>,
        transaction: Option<protocol::TransactionRef>,
        receipt: Option<ChildPublicationResultV1>,
        fault: Option<ArtifactBoundedToolFault>,
        phase: PendingChildGroupPublicationPhase,
    }

    impl<A: ArtifactApp> PendingChildGroupPublication<A> {
        fn new(artifact_mutations: Vec<A::Mutation>, child_emits: Vec<ChildEmit>, transaction: Option<protocol::TransactionRef>) -> Result<Self, Fault> {
            if child_emits.is_empty() {
                return Err(plugin_sdk_fault("retained child-group publication requires at least one exact child output"));
            }
            Ok(Self { artifact_mutations, child_emits, transaction, receipt: None, fault: None, phase: PendingChildGroupPublicationPhase::Ready })
        }

        fn begin_dispatch(&mut self) -> Result<(), Fault> {
            if self.phase != PendingChildGroupPublicationPhase::Ready {
                return Err(plugin_sdk_fault("retained child-group publication lost its single dispatch authority"));
            }
            self.phase = PendingChildGroupPublicationPhase::Dispatching;
            Ok(())
        }

        fn commit(&mut self, receipt: ChildPublicationResultV1) -> Result<(), Fault> {
            if self.phase != PendingChildGroupPublicationPhase::Dispatching || self.receipt.is_some() || self.fault.is_some() {
                return Err(plugin_sdk_fault("retained child-group publication attempted a duplicate commit"));
            }
            self.receipt = Some(receipt);
            self.phase = PendingChildGroupPublicationPhase::Committed;
            Ok(())
        }

        fn reject(&mut self, fault: &Fault) {
            self.fault = Some(ArtifactBoundedToolFault::from_fault(fault));
            self.phase = PendingChildGroupPublicationPhase::Faulted;
        }

        fn reject_and_fault(&mut self, fault: &Fault) -> Fault {
            self.reject(fault);
            self.fault().expect("rejected child publication retains one bounded fault")
        }

        fn fault(&self) -> Option<Fault> {
            self.fault.as_ref().map(|fault| ArtifactBoundedToolFault { bytes: fault.bytes, len: fault.len }.into_fault())
        }

        fn acknowledge(&mut self) -> bool {
            if self.phase != PendingChildGroupPublicationPhase::Committed {
                return false;
            }
            self.phase = PendingChildGroupPublicationPhase::Acknowledged;
            true
        }

        fn begin_close(&mut self) {
            self.phase = PendingChildGroupPublicationPhase::Closing;
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            self.phase = PendingChildGroupPublicationPhase::Closing;
            if let Some(child) = self.child_emits.last_mut() {
                let step = child.close_one(maximum_items, maximum_bytes);
                if step == PluginCloseStep::Complete {
                    self.child_emits.pop();
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                return step;
            }
            if maximum_items != 0 && self.artifact_mutations.pop().is_some() {
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(receipt) = self.receipt.as_mut() {
                if !receipt.invocation_id.is_empty() {
                    return MountedTypedCommandFullOperation::<A>::retire_string_scalar(&mut receipt.invocation_id, maximum_bytes).expect("nonempty child-group invocation id");
                }
            }
            if maximum_items != 0 && self.receipt.take().is_some() {
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if maximum_items != 0 && self.fault.take().is_some() {
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            PluginCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.phase == PendingChildGroupPublicationPhase::Closing && self.artifact_mutations.is_empty() && self.child_emits.is_empty() && self.receipt.is_none() && self.fault.is_none()
        }
    }

    impl<A: ArtifactApp> PendingArtifactStorePublication<A> {
        fn acknowledge(&mut self) -> bool {
            match self {
                Self::Artifact(publication) => publication.acknowledge(),
                Self::Config(publication) => publication.acknowledge(),
                Self::Draft(publication) => publication.acknowledge(),
                Self::Presence(publication) => publication.acknowledge(),
                Self::Transient(publication) => publication.acknowledge(),
                Self::WindowConfig(publication) => publication.acknowledge(),
                Self::WindowTransient(publication) => publication.acknowledge(),
            }
        }

        fn begin_close(&mut self) {
            match self {
                Self::Artifact(publication) => publication.begin_close(),
                Self::Config(publication) => publication.begin_close(),
                Self::Draft(publication) => publication.begin_close(),
                Self::Presence(publication) => publication.begin_close(),
                Self::Transient(publication) => publication.begin_close(),
                Self::WindowConfig(publication) => publication.begin_close(),
                Self::WindowTransient(publication) => publication.begin_close(),
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<store::SnapshotRetirementStep, Fault> {
            let grant = store::ArtifactStoreOneItemGrant { maximum_items: maximum_items.min(1), maximum_bytes };
            match self {
                Self::Artifact(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
                Self::Config(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
                Self::Draft(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
                Self::Presence(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
                Self::Transient(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
                Self::WindowConfig(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
                Self::WindowTransient(publication) => publication.close_step(grant).map_err(|error| plugin_sdk_fault(error.into_message())),
            }
        }

        fn terminal_is_empty(&self) -> bool {
            match self {
                Self::Artifact(publication) => publication.terminal_is_empty(),
                Self::Config(publication) => publication.terminal_is_empty(),
                Self::Draft(publication) => publication.terminal_is_empty(),
                Self::Presence(publication) => publication.terminal_is_empty(),
                Self::Transient(publication) => publication.terminal_is_empty(),
                Self::WindowConfig(publication) => publication.terminal_is_empty(),
                Self::WindowTransient(publication) => publication.terminal_is_empty(),
            }
        }

        /// 🏷️ The one result lane this pending publication answers under, paired with the store label
        /// its own retirement faults are worded with.
        fn lane(&self) -> (TypedOperationResultLane, &'static str) {
            match self {
                Self::Artifact(_) => (TypedOperationResultLane::Artifact, "artifact-store"),
                Self::Config(_) => (TypedOperationResultLane::Config, "config-store"),
                Self::Draft(_) => (TypedOperationResultLane::Draft, "draft-store"),
                Self::Presence(_) => (TypedOperationResultLane::Presence, "presence-store"),
                Self::Transient(_) => (TypedOperationResultLane::Transient, "transient-store"),
                Self::WindowConfig(_) => (TypedOperationResultLane::WindowConfig, "window-config"),
                Self::WindowTransient(_) => (TypedOperationResultLane::WindowTransient, "window-transient"),
            }
        }

        /// ♻️ Whether the owning store already moved this publication into its retirement phase.
        fn is_closing(&self) -> bool {
            let phase = match self {
                Self::Artifact(publication) => publication.phase(),
                Self::Config(publication) => publication.phase(),
                Self::Draft(publication) => publication.phase(),
                Self::Presence(publication) => publication.phase(),
                Self::Transient(publication) => publication.phase(),
                Self::WindowConfig(publication) => publication.phase(),
                Self::WindowTransient(publication) => publication.phase(),
            };
            phase == store::ArtifactStoreOneItemPublicationPhase::Closing
        }

        /// 💥️ The owning store's own rejection reason, for as long as the retirement still retains it.
        fn fault(&self) -> Option<&str> {
            match self {
                Self::Artifact(publication) => publication.fault(),
                Self::Config(publication) => publication.fault(),
                Self::Draft(publication) => publication.fault(),
                Self::Presence(publication) => publication.fault(),
                Self::Transient(publication) => publication.fault(),
                Self::WindowConfig(publication) => publication.fault(),
                Self::WindowTransient(publication) => publication.fault(),
            }
        }

        /// ♻️ ONE bounded retirement turn of a publication already in `Closing`, shared verbatim by all
        /// seven store lanes.
        ///
        /// An incomplete step is [`PendingArtifactStorePublicationRetirement::Retiring`] — **never** a
        /// fault — even while [`Self::fault`] is still `Some`: a rejected authority drains its reason
        /// one scalar per turn, so answering the turn with `Err` re-raised the SAME rejection on every
        /// turn of the drain and the host saw `typed-operation failed: … is retiring a rejected
        /// authority` instead of a retiring publication
        /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️invoke-extension-rejected-authority-2026-09-11.md`).
        /// The rejection surfaces exactly once, when the retirement is terminal.
        ///
        /// Window-transient is deliberately the lenient lane: its authority is per-window ephemeral
        /// state that the very next turn re-captures against the live generation, so a superseded
        /// publication that retired cleanly owes the host no fault at all.
        fn retirement_turn(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PendingArtifactStorePublicationRetirement, Fault> {
            let (lane, label) = self.lane();
            let rejected = self.fault().is_some();
            match self.close_step(maximum_items, maximum_bytes)? {
                store::SnapshotRetirementStep::Complete if !self.terminal_is_empty() => Err(plugin_sdk_fault(format!("{label} publication closed without terminal emptiness"))),
                store::SnapshotRetirementStep::Complete if rejected && lane != TypedOperationResultLane::WindowTransient => {
                    Ok(PendingArtifactStorePublicationRetirement::Rejected(plugin_sdk_fault(format!("{label} publication rejected stale or cancelled authority"))))
                }
                store::SnapshotRetirementStep::Complete => Ok(PendingArtifactStorePublicationRetirement::Retired),
                _ => Ok(PendingArtifactStorePublicationRetirement::Retiring),
            }
        }
    }

    /// ♻️ Outcome of ONE [`PendingArtifactStorePublication::retirement_turn`].
    #[derive(Debug)]
    enum PendingArtifactStorePublicationRetirement {
        /// 🔁️ The publication owes more retirement turns; the operation keeps its slot and yields.
        Retiring,
        /// ✅️ The publication retired terminal-empty and owes the host nothing.
        Retired,
        /// 💥️ The publication retired terminal-empty after its store rejected it; the operation fails.
        Rejected(Fault),
    }

    struct MountedTypedCommandFullOperation<A: ArtifactApp> {
        verb: String,
        meta: ActionMeta,
        operation: semio_framework_job::Operation,
        canonical_revision: [u8; 32],
        artifact_generation: u64,
        config_generation: u64,
        draft_generation: u64,
        presence_generation: u64,
        transient_generation: u64,
        window_config_authority: Option<super::window_config::WindowConfigAuthority>,
        window_transient_authority: Option<super::window_transient::WindowTransientAuthority>,
        publication_lanes: &'static [ArtifactToolPublicationLane],
        session: Option<semio_framework_job::MountedWorkerJobSession<semio_framework::ErasedToolJob>>,
        session_rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<semio_framework::ErasedToolJob>>,
        completion: Option<ArtifactToolCompletion<A>>,
        raw_input: Option<ArtifactToolRawInput>,
        output_chunks: Option<ArtifactOutputChunks>,
        cancellation_lease: Option<ToolCancellationLease>,
        terminal_outcome: Option<semio_framework_job::StepOutcome>,
        terminal_seen: bool,
        publication: Option<ArtifactToolCompletionValue<A>>,
        pending_artifact_publication: Option<PendingArtifactStorePublication<A>>,
        pending_child_publication: Option<PendingChildGroupPublication<A>>,
        captured_child_content: Option<std::sync::Arc<ChildContentView>>,
        captured_child_content_generation: u64,
        result_page: Option<TypedOperationResultPage>,
        result_page_presented: bool,
        result_sequence: u32,
        /// 🧮️ The publication ladder's OWN monotone progress: how many publication units actually
        /// moved this operation's pending store publication, counted by the store's checkpoint
        /// rather than by the unit having been spent. A healthy ladder that folds one mutation per
        /// unit raises it on every unit; an owner that cannot advance never raises it at all, which
        /// is exactly the term [`Self::typed_operation_stall_witness`]'s three facts were missing.
        publication_progress: u64,
        /// 🧮️ The last checkpoint the pending publication answered with, so a unit that repeats it
        /// verbatim is recognised as no movement at all instead of as progress.
        publication_checkpoint: Option<store::ArtifactStoreOneItemCheckpoint>,
        publication_attempt: u8,
        ui_pending: bool,
        progress: Option<u64>,
        progress_pending: bool,
        user_cancel_requested: bool,
        published_artifact: bool,
        published_config: bool,
        /// 🪟 The per-window config lane published. A `View` whose only durable emission is this lane
        /// is session view state, and [`Self::record_settled_typed_operation_command`] leaves it out
        /// of the artifact command history — the same exception [`Self::dispatch_emit_inner`] makes.
        published_window_config: bool,
        command_logged: bool,
        interaction_revalidated: bool,
        terminal_fault: Option<ArtifactBoundedToolFault>,
        stage: MountedTypedCommandFullOperationStage,
    }

    impl<A: ArtifactApp> MountedTypedCommandFullOperation<A> {
        /// 🧮️ Records what the store answered for ONE publication unit. The checkpoint carries the
        /// store's own cursor, completed items and completed bytes; a unit that repeats the
        /// previous checkpoint verbatim moved nothing and raises no progress, so an owner that can
        /// never advance still runs its streak up to
        /// [`TYPED_OPERATION_STALL_FAULT_CEILING`], while a ladder folding one mutation per unit
        /// resets that streak every unit however many mutations the edit carries.
        fn note_publication_checkpoint(&mut self, checkpoint: store::ArtifactStoreOneItemCheckpoint) {
            if self.publication_checkpoint != Some(checkpoint) {
                self.publication_checkpoint = Some(checkpoint);
                self.publication_progress = self.publication_progress.saturating_add(1);
            }
        }

        /// 🚫️ A rejected worker admission never ran the job, so no completion value will ever
        /// arrive: publication would spin on `completion.take() == None` for as long as the host
        /// keeps advancing it. The operation is terminal the moment its session is refused —
        /// cancel the lease so the next publication unit mints the exact fault page.
        fn drive_worker_step(&mut self, pool: &semio_framework_async::WorkerPool, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Worker {
                return Ok(PluginCloseStep::Blocked { reason: "typed command awaits its bounded revision-validated publication or ACK turn" });
            }
            if let Some(rejected) = self.session_rejected.as_mut() {
                let step = rejected.close_step(1, maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                if rejected.terminal_is_empty() {
                    self.session_rejected = None;
                    self.stage = MountedTypedCommandFullOperationStage::Publishing;
                    self.terminal_fault.get_or_insert_with(|| {
                        ArtifactBoundedToolFault::from_fault(&Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.admission-capacity"), "typed operation worker session admission was refused by the process-wide session capacity"))
                    });
                    if let Some(lease) = self.cancellation_lease.as_ref() {
                        lease.cancel();
                    }
                }
                return Ok(match step {
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::InteractiveJobCloseStep::Blocked => PluginCloseStep::AwaitingInput { reason: "typed operation rejected-session close awaits its worker handback" },
                    semio_framework_job::InteractiveJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                });
            }
            if let Some(outcome) = self.terminal_outcome.as_mut() {
                let step = outcome.close_step(1, maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                if !outcome.terminal_is_empty() {
                    return Ok(match step {
                        semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                        semio_framework_job::JobPayloadCloseStep::Complete => PluginCloseStep::Blocked { reason: "typed command retained outcome reported false terminal" },
                    });
                }
                self.terminal_outcome = None;
                let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-session"), "typed operation lost its persistent mounted session during outcome handback"))?;
                if self.terminal_seen {
                    session.begin_close();
                } else if session.resume().is_err() {
                    return Ok(PluginCloseStep::AwaitingInput { reason: "typed operation outcome handback awaits its worker session" });
                }
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-session"), "typed operation lost its persistent worker session before publication"))?;
            if self.terminal_seen {
                let step = session.close_step(1, maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                if session.terminal_is_empty() {
                    self.session = None;
                    self.stage = MountedTypedCommandFullOperationStage::Publishing;
                }
                return Ok(match step {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::WorkerJobCloseStep::Blocked => PluginCloseStep::AwaitingInput { reason: "typed operation mounted session close awaits its worker handback" },
                    semio_framework_job::WorkerJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                });
            }
            match session.pump_one_for_interactive_turn(pool, semio_framework_async::Lane::Interactive) {
                Ok(semio_framework_job::WorkerJobPoll::Outcome | semio_framework_job::WorkerJobPoll::Terminal) => {
                    let terminal = session.checked_out_outcome().is_some_and(semio_framework_job::StepOutcome::is_terminal);
                    let Some(outcome) = session.take_checked_out_outcome() else {
                        return Ok(PluginCloseStep::Blocked { reason: "typed operation checked-out outcome changed during one mounted turn" });
                    };
                    if let semio_framework_job::StepOutcome::Fault(fault) = &outcome {
                        self.terminal_fault = Some(ArtifactBoundedToolFault::from_retained_fault(&fault.detail));
                    }
                    if matches!(outcome, semio_framework_job::StepOutcome::Cancelled | semio_framework_job::StepOutcome::Fault(_)) {
                        if let Some(lease) = self.cancellation_lease.as_ref() {
                            lease.cancel();
                        }
                    }
                    if let semio_framework_job::StepOutcome::CheckpointReady(checkpoint) = &outcome {
                        let next = self.progress.unwrap_or(0).max(checkpoint.applied_progress);
                        self.progress_pending |= self.progress != Some(next);
                        self.progress = Some(next);
                    }
                    if terminal && self.progress.is_some() {
                        self.progress_pending = true;
                    }
                    self.terminal_seen = terminal;
                    self.terminal_outcome = Some(outcome);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Ok(semio_framework_job::WorkerJobPoll::Submitted | semio_framework_job::WorkerJobPoll::Rejected) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                Ok(_) => Ok(PluginCloseStep::AwaitingInput { reason: "typed operation mounted worker awaits its next outcome" }),
                Err(semio_framework_job::MountedWorkerJobPumpFault::Submit(semio_framework_job::WorkerJobSubmitFault::Contention(_)))
                | Err(semio_framework_job::MountedWorkerJobPumpFault::Submit(semio_framework_job::WorkerJobSubmitFault::Pool(semio_framework_async::WorkerSubmitErrorKind::Contended | semio_framework_async::WorkerSubmitErrorKind::Saturated)))
                | Err(semio_framework_job::MountedWorkerJobPumpFault::Take(semio_framework_job::WorkerJobTakeFault::Pending)) => Ok(PluginCloseStep::AwaitingInput { reason: "typed operation mounted worker awaits transient scheduler authority" }),
                Err(_) => Ok(PluginCloseStep::Blocked { reason: "typed operation mounted worker failed to make structural progress" }),
            }
        }

        fn next_token(&self) -> TypedOperationResultToken {
            TypedOperationResultToken { receiver: self.meta.instance_id, operation: self.operation.operation.0, generation: self.operation.generation.0, sequence: self.result_sequence, attempt: 1 }
        }

        fn queue_page(&mut self, page: TypedOperationResultPage) -> Result<(), Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Publishing || self.result_page.is_some() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.result-page-state"), "typed operation can retain exactly one unacknowledged result page"));
            }
            self.result_page = Some(page);
            self.result_page_presented = false;
            self.stage = MountedTypedCommandFullOperationStage::AwaitingAck;
            Ok(())
        }

        fn reject_cancelled_publication(&mut self) -> Result<bool, Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Publishing {
                return Ok(false);
            }
            let lease = self.cancellation_lease.as_ref().ok_or_else(|| plugin_sdk_fault("typed-operation publication lacks its exact cancellation lease"))?;
            if !lease.handle.publication_scope.is_cancelled() && !lease.document_claim.as_ref().is_some_and(|claim| claim.is_cancelled()) && !lease.publication_claim.is_cancelled() && !lease.token.is_cancelled_now() {
                return Ok(false);
            }
            if self.publication.is_none() {
                if let Some(completion) = self.completion.as_ref() {
                    self.publication = completion.take()?;
                }
            }
            if let Some(pending) = self.pending_artifact_publication.as_mut() {
                pending.begin_close();
            }
            if let Some(pending) = self.pending_child_publication.as_mut() {
                pending.begin_close();
            }
            self.ui_pending = false;
            let page = match self.terminal_fault.as_ref() {
                Some(fault) => {
                    let mut framed = [0; TYPED_OPERATION_FAULT_PAGE_BYTES];
                    let len = fault.framed_page_bytes(&mut framed);
                    TypedOperationResultPage::try_new(self.next_token(), TypedOperationResultLane::Fault, &framed[..len])?
                }
                None => {
                    let lane = operation_progress::cancellation_result_lane(self.user_cancel_requested, false);
                    let detail: &[u8] = if lane == TypedOperationResultLane::Terminal { b"" } else { b"typed-operation cancelled before its next publication unit" };
                    TypedOperationResultPage::try_new(self.next_token(), lane, detail)?
                }
            };
            self.queue_page(page)?;
            Ok(true)
        }

        fn take_result_page(&mut self) -> Option<TypedOperationResultPage> {
            if self.result_page_presented {
                return None;
            }
            self.result_page_presented = true;
            self.result_page.clone()
        }

        fn acknowledge_result_page(&mut self, token: TypedOperationResultToken) -> Result<bool, Fault> {
            let Some(page) = self.result_page.as_ref() else { return Ok(false) };
            if page.token != token || self.stage != MountedTypedCommandFullOperationStage::AwaitingAck {
                return Ok(false);
            }
            let lane = page.lane;
            if matches!(
                lane,
                TypedOperationResultLane::Artifact
                    | TypedOperationResultLane::Config
                    | TypedOperationResultLane::Draft
                    | TypedOperationResultLane::Presence
                    | TypedOperationResultLane::Transient
                    | TypedOperationResultLane::WindowConfig
                    | TypedOperationResultLane::WindowTransient
            ) && !self.pending_artifact_publication.as_mut().is_some_and(PendingArtifactStorePublication::acknowledge)
            {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.artifact-publication-ack"), "artifact-store result ACK lost its exact pending publication authority"));
            }
            if lane == TypedOperationResultLane::Child && !self.pending_child_publication.as_mut().is_some_and(PendingChildGroupPublication::acknowledge) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-publication-ack"), "child-group result ACK lost its exact committed publication authority"));
            }
            self.result_page = None;
            self.result_page_presented = false;
            self.result_sequence = self.result_sequence.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.result-sequence"), "typed-operation result sequence exhausted"))?;
            self.stage = if matches!(lane, TypedOperationResultLane::Terminal | TypedOperationResultLane::Fault | TypedOperationResultLane::Download) {
                MountedTypedCommandFullOperationStage::Retiring
            } else {
                MountedTypedCommandFullOperationStage::Publishing
            };
            Ok(true)
        }

        fn retire_string_scalar(value: &mut String, maximum_bytes: usize) -> Option<PluginCloseStep> {
            let scalar_bytes = value.chars().next_back()?.len_utf8();
            if scalar_bytes > maximum_bytes {
                return Some(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            value.pop();
            Some(PluginCloseStep::Pending { released_items: 0, released_bytes: scalar_bytes })
        }

        fn retirement_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Retiring {
                return Ok(PluginCloseStep::Blocked { reason: "typed operation is not admitted for retirement" });
            }
            if self.result_page.is_some() {
                return Ok(PluginCloseStep::Blocked { reason: "typed operation retains an unacknowledged result page" });
            }
            if let Some(pending) = self.pending_artifact_publication.as_mut() {
                pending.begin_close();
                let step = pending.close_step(maximum_items, maximum_bytes)?;
                if step == store::SnapshotRetirementStep::Complete {
                    if !pending.terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.artifact-publication-terminal"), "artifact-store publication reported complete without terminal emptiness"));
                    }
                    self.pending_artifact_publication = None;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(match step {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "artifact-store publication close is blocked" },
                    store::SnapshotRetirementStep::Complete => unreachable!("handled terminal artifact-store publication"),
                });
            }
            if let Some(pending) = self.pending_child_publication.as_mut() {
                pending.begin_close();
                let step = pending.close_step(maximum_items, maximum_bytes);
                if step == PluginCloseStep::Complete {
                    if !pending.terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-publication-terminal"), "child-group publication reported complete without terminal emptiness"));
                    }
                    self.pending_child_publication = None;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if let Some(publication) = self.publication.as_mut() {
                match publication {
                    ArtifactToolCompletionValue::Emit(Ok(emit), ephemeral) => {
                        if let Some(step)=emit.close_child_one(maximum_items,maximum_bytes){return Ok(step);}
                        if maximum_items != 0 {
                            if emit.artifact_mutations.pop().is_some()
                                || emit.config_mutations.pop().is_some()
                                || emit.draft_mutations.pop().is_some()
                                || ephemeral.presence.pop().is_some()
                                || ephemeral.transient.pop().is_some()
                                || ephemeral.window_transient.pop().is_some()
                                || emit.effects.pop().is_some()
                                || emit.extension_invocations.pop().is_some()
                                || emit.events.pop().is_some()
                            {
                                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                            }
                            if emit.tasks.pop().is_some() {
                                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                            }
                        }
                        if maximum_items == 0 {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                    }
                    ArtifactToolCompletionValue::Download(Ok(download), ephemeral) => {
                        if maximum_items != 0 && (ephemeral.presence.pop().is_some() || ephemeral.transient.pop().is_some() || ephemeral.window_transient.pop().is_some()) {
                            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                        }
                        if download.chunks.chunks_remaining() != 0 && (maximum_items == 0 || maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES) {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                        if let Some(chunk) = download.chunks.close_take_chunk()? {
                            let bytes = chunk.len();
                            drop(chunk);
                            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
                        }
                        if !download.filename.is_empty() {
                            return Ok(Self::retire_string_scalar(&mut download.filename, maximum_bytes).expect("nonempty filename"));
                        }
                        if !download.mime_type.is_empty() {
                            return Ok(Self::retire_string_scalar(&mut download.mime_type, maximum_bytes).expect("nonempty MIME type"));
                        }
                        if let Some(encoding) = download.encoding.as_mut().filter(|value| !value.is_empty()) {
                            return Ok(Self::retire_string_scalar(encoding, maximum_bytes).expect("nonempty encoding"));
                        }
                        if maximum_items == 0 {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                    }
                    ArtifactToolCompletionValue::Emit(Err(_), _) | ArtifactToolCompletionValue::Download(Err(_), _) if maximum_items == 0 => {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    ArtifactToolCompletionValue::Emit(Err(_), _) | ArtifactToolCompletionValue::Download(Err(_), _) => {}
                }
                self.publication = None;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(raw_input) = self.raw_input.as_ref() {
                let step = raw_input.close_step(maximum_items.min(1), maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !raw_input.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.raw-page-terminal"), "typed-operation raw page owner reported Complete without terminal emptiness"));
                }
                self.raw_input = None;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(chunks) = self.output_chunks.as_ref() {
                if chunks.chunks_remaining() != 0 && (maximum_items == 0 || maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES) {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                if let Some(chunk) = chunks.close_take_chunk()? {
                    let bytes = chunk.len();
                    drop(chunk);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
                }
            }
            if maximum_items == 0 && (self.output_chunks.is_some() || self.completion.is_some() || self.cancellation_lease.is_some()) {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if self.output_chunks.take().is_some() || self.completion.take().is_some() {
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.captured_child_content.take().is_some() {
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(mut lease) = self.cancellation_lease.take() {
                lease.finish_in_place();
                drop(lease);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.stage == MountedTypedCommandFullOperationStage::Retiring
                && self.session.is_none()
                && self.session_rejected.is_none()
                && self.terminal_outcome.is_none()
                && self.publication.is_none()
                && self.pending_artifact_publication.is_none()
                && self.pending_child_publication.is_none()
                && self.captured_child_content.is_none()
                && self.result_page.is_none()
                && self.raw_input.is_none()
                && self.output_chunks.is_none()
                && self.completion.is_none()
                && self.cancellation_lease.is_none()
        }
    }

    fn bounded_json_items(value: Option<&DslValue>, maximum: usize) -> Result<usize, Fault> {
        let mut count = 1usize;
        let mut pending = value.into_iter().collect::<Vec<_>>();
        while let Some(value) = pending.pop() {
            count = count.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), "decoded item count overflowed"))?;
            if count > maximum {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), format!("decoded command contains {count} items; maximum is {maximum}")));
            }
            match value {
                semio_framework_value::DslValue::Array(values) => pending.extend(values),
                semio_framework_value::DslValue::Object(values) => {
                    count = count.checked_add(values.len()).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), "decoded item count overflowed"))?;
                    if count > maximum {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), format!("decoded command contains {count} items; maximum is {maximum}")));
                    }
                    pending.extend(values.iter().map(|(_, value)| value));
                }
                _ => {}
            }
        }
        Ok(count)
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum TypedCommandFullOperationPhase {
        Prepare,
        Reducer,
        Fault,
    }

    pub(crate) struct TypedCommandFullOperationJob<A: ArtifactApp> {
        operation: Option<semio_framework_job::Operation>,
        parent_document_id: Option<String>,
        command: Option<std::sync::Arc<A::Command>>,
        snapshot: Option<std::sync::Arc<A::Snapshot>>,
        config: Option<std::sync::Arc<A::Config>>,
        history: Option<std::sync::Arc<HistoryView>>,
        children: Option<std::sync::Arc<ChildContentView>>,
        draft: Option<std::sync::Arc<A::Draft>>,
        interaction_state: Option<std::sync::Arc<protocol::InteractionState>>,
        interaction_hover: Option<std::sync::Arc<InteractionHoverState>>,
        peer_presence: Option<std::sync::Arc<PeerPresenceRoot>>,
        presence_local: Option<store::SnapshotRead<A::Presence>>,
        presence_peers: Option<std::sync::Arc<store::PresencePeersRoot<A::Presence>>>,
        transient: Option<std::sync::Arc<A::Transient>>,
        contract: semio_framework::ToolExecutionContract,
        decoded_items: usize,
        phase: TypedCommandFullOperationPhase,
        prepare_cursor: u8,
        reducer_cursor: u8,
        output: Option<ArtifactToolCompletion<A>>,
        closing: bool,
    }

    impl<A: ArtifactApp> TypedCommandFullOperationJob<A> {
        fn checkpoint(&self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::Checkpoint {
            let state = [self.phase as u8, self.prepare_cursor, self.reducer_cursor];
            semio_framework_job::Checkpoint { state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &state), applied_progress: u64::from(self.prepare_cursor).saturating_add(u64::from(self.reducer_cursor)) }
        }

        fn fault(&mut self, cx: &mut semio_framework_job::StepContext<'_>, message: &[u8]) -> semio_framework_job::StepOutcome {
            self.phase = TypedCommandFullOperationPhase::Fault;
            semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, message) })
        }
    }

    impl<A: ArtifactApp> semio_framework_job::InteractiveJob for TypedCommandFullOperationJob<A> {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            if cx.is_cancelled() {
                return semio_framework_job::StepOutcome::Cancelled;
            }
            if cx.should_yield() || cx.fuel_remaining() == 0 {
                return semio_framework_job::StepOutcome::Yield;
            }
            if self.decoded_items > self.contract.max_decoded_items || self.contract.max_work_units_per_step == 0 || self.contract.max_output_bytes == 0 {
                return self.fault(cx, b"typed command admission exceeds its fixed item, work, or output cap");
            }
            cx.consume_fuel(1);
            let operation = self.operation.expect("tool job factory assigns operation identity");
            debug_assert_eq!(operation.operation, cx.operation());
            match self.phase {
                TypedCommandFullOperationPhase::Prepare => {
                    cx.set_stage("typed-command-prepare");
                    let present = match self.prepare_cursor {
                        0 => self.parent_document_id.is_some(),
                        1 => self.command.is_some(),
                        2 => self.snapshot.is_some(),
                        3 => self.config.is_some(),
                        4 => self.history.is_some(),
                        5 => self.children.is_some(),
                        6 => self.draft.is_some(),
                        7 => self.interaction_state.is_some(),
                        8 => self.interaction_hover.is_some(),
                        9 => self.peer_presence.is_some(),
                        10 => self.presence_local.is_some(),
                        11 => self.presence_peers.is_some(),
                        12 => self.transient.is_some(),
                        _ => {
                            self.phase = TypedCommandFullOperationPhase::Reducer;
                            return semio_framework_job::StepOutcome::CheckpointReady(self.checkpoint(cx));
                        }
                    };
                    if !present {
                        return self.fault(cx, b"typed command preparation root is absent");
                    }
                    self.prepare_cursor = self.prepare_cursor.saturating_add(1);
                    if self.prepare_cursor == 1 {
                        semio_framework_job::StepOutcome::PreviewReady(retained_job_payload(cx, semio_framework_job::JobPayloadStream::Preview, b"typed-command-prepare"))
                    } else {
                        semio_framework_job::StepOutcome::CheckpointReady(self.checkpoint(cx))
                    }
                }
                TypedCommandFullOperationPhase::Reducer => {
                    cx.set_stage("typed-command-reducer");
                    self.reducer_cursor = self.reducer_cursor.saturating_add(1);
                    self.fault(cx, b"generic bounded proof has no resumable app-owned reducer job")
                }
                TypedCommandFullOperationPhase::Fault => self.fault(cx, b"typed command remains faulted"),
            }
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if let Some(parent) = self.parent_document_id.as_ref() {
                if maximum_items == 0 || maximum_bytes < parent.len() {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                let released_bytes = parent.len();
                drop(self.parent_document_id.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes };
            }
            if self.command.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.command.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.snapshot.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.snapshot.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.config.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.config.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.history.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.history.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.children.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.children.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.draft.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.draft.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.interaction_state.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.interaction_state.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.interaction_hover.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.interaction_hover.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.peer_presence.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.peer_presence.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.presence_local.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.presence_local.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.presence_peers.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.presence_peers.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.transient.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.transient.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.output.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.output.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            self.operation = None;
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing
                && self.parent_document_id.is_none()
                && self.command.is_none()
                && self.snapshot.is_none()
                && self.config.is_none()
                && self.history.is_none()
                && self.children.is_none()
                && self.draft.is_none()
                && self.interaction_state.is_none()
                && self.interaction_hover.is_none()
                && self.peer_presence.is_none()
                && self.presence_local.is_none()
                && self.presence_peers.is_none()
                && self.transient.is_none()
                && self.output.is_none()
                && self.operation.is_none()
        }
    }

    pub(crate) struct TypedCommandFullOperationJobFactory<A: ArtifactApp> {
        keys: Vec<semio_framework::ToolFactoryKey>,
        payload_schema_id: String,
        proof: QualifiedBoundedFirstStepProof,
        marker: std::marker::PhantomData<fn() -> A>,
    }

    impl<A: ArtifactApp> TypedCommandFullOperationJobFactory<A> {
        pub(crate) fn from_proof(proof: QualifiedBoundedFirstStepProof) -> Option<Self> {
            if proof.owner != ToolOwnerWitness::of::<A>() || proof.row.owner != proof.owner || proof.row.factory != BOUNDED_FIRST_STEP_FACTORY || proof.row.factory_type_id.is_some() || proof.row.factory_type_name.is_some() {
                return None;
            }
            let keys = vec![proof.key()];
            let payload_schema_id = proof.schema_id();
            Some(Self { keys, payload_schema_id, proof, marker: std::marker::PhantomData })
        }
    }

    impl<A: ArtifactApp> semio_framework::ToolJobFactory for TypedCommandFullOperationJobFactory<A> {
        type Payload = TypedCommandFullOperationJob<A>;
        type Job = TypedCommandFullOperationJob<A>;

        fn keys(&self) -> &[semio_framework::ToolFactoryKey] {
            &self.keys
        }

        fn payload_schema_id(&self) -> &str {
            &self.payload_schema_id
        }

        fn classification(&self) -> semio_framework::InteractiveJobClassification {
            semio_framework::InteractiveJobClassification::Migrated
        }

        fn execution_contract(&self) -> semio_framework::ToolExecutionContract {
            self.proof.contract()
        }

        fn create_job(&mut self, operation: semio_framework_job::Operation, mut payload: Self::Payload) -> Result<Self::Job, semio_framework::ToolJobFactoryError> {
            payload.operation = Some(operation);
            Ok(payload)
        }
    }

    #[cfg(test)]
    pub(crate) async fn test_retained_keyed_dispatch<A: ArtifactApp + Default>(
        registry: AppActionRegistry,
        command: fn(&str, i32) -> A::Command,
        mutation: fn(i32) -> A::Mutation,
        observe: fn(&A::Snapshot) -> i32,
        clock: Option<fn() -> Option<u64>>,
    ) {
        let fixture: Value = serde_json::from_str(include_str!("🧫️fixtures/🔗️tool-latest-wins-integration.json")).unwrap();
        let pool = semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map(std::num::NonZeroUsize::get).unwrap_or(1)));
        for case in fixture["cases"].as_array().unwrap() {
            let mut app = VcsArtifactApp::<A>::with_registry(A::default(), registry.clone()).await;
            app.test_tool_clock = clock;
            app.bind_instance_id(7).await;
            let meta = ActionMeta { actor: "fixture".into(), instance_id: 7, view_state: None };
            let first = Box::new(command(case["firstTarget"].as_str().unwrap(), case["firstValue"].as_i64().unwrap() as i32));
            let wire = <A::Command as ::protocol::OpBinary>::encode_op(&first).unwrap();
            let admission = app.admit_command_wire("compositeEdit", &wire, 1).await.unwrap();
            assert!(matches!(admission.proof, QualifiedToolProof::AppOwned(_)));
            app.dispatch_typed_command_inner(first, admission, &meta).await.unwrap();
            let first_id = *app.latest_wins_order.items.front().unwrap();
            assert!(!app.can_admit_typed_operation(first_id + ARTIFACT_LIVE_OUTPUT_SLOTS as u64));
            for _ in 0..100_000 {
                if app.tool_operations.get(first_id).is_some() {
                    break;
                }
                app.advance_latest_wins_command_one().await.unwrap();
                plugin_job_yield_once().await;
            }
            let first_token = app.tool_operations.get(first_id).expect("actual registered first worker").cancellation_lease.as_ref().unwrap().token.clone();
            let next = Box::new(command(case["nextTarget"].as_str().unwrap(), case["nextValue"].as_i64().unwrap() as i32));
            let wire = <A::Command as ::protocol::OpBinary>::encode_op(&next).unwrap();
            let admission = app.admit_command_wire("compositeEdit", &wire, 1).await.unwrap();
            app.dispatch_typed_command_inner(next, admission, &meta).await.unwrap();
            let next_id = *app.latest_wins_order.items.front().unwrap();
            let old_key = app.latest_wins_commands.get(next_id).unwrap().lease.as_ref().unwrap().key.clone();
            app.store.dispatch(ArtifactCommand::Apply { mutations: vec![mutation(13)], description: None, transaction: None }).await.unwrap();
            let fresh_revision = app.store.content_revision_now();
            for _ in 0..100_000 {
                if app.tool_operations.get(next_id).is_some() {
                    break;
                }
                app.advance_latest_wins_command_one().await.unwrap();
                plugin_job_yield_once().await;
            }
            let mounted = app.tool_operations.get(next_id).expect("accepted key creates actual fresh worker");
            assert_eq!(mounted.canonical_revision, fresh_revision);
            assert_eq!(mounted.operation.generation.0, fixture["rebase"]["afterGeneration"].as_u64().unwrap());
            let fresh_key = mounted.cancellation_lease.as_ref().unwrap().key.clone();
            assert_eq!(fresh_key.generation, mounted.operation.generation);
            assert!(!app.tool_cancellations.cancel(&old_key).unwrap());
            assert_eq!(serde_json::json!(first_token.is_cancelled_now()), case["firstCancelled"]);
            let expected = 13 + case["nextValue"].as_i64().unwrap() as i32;
            for _ in 0..100_000 {
                if observe(app.store.snapshot_root().as_ref()) == expected {
                    break;
                }
                if app.tool_operations.get(next_id).unwrap().stage == MountedTypedCommandFullOperationStage::Worker {
                    app.tool_operations.get_mut(next_id).unwrap().drive_worker_step(&pool, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES).unwrap();
                } else {
                    app.advance_typed_operation_publication_one().await.unwrap();
                }
                plugin_job_yield_once().await;
            }
            let state = app.tool_operations.get(next_id).unwrap();
            eprintln!(
                "[TRACE] registered keyed dispatch progress stage={:?} terminal_seen={} pending={} completion={} result={:?}",
                state.stage,
                state.terminal_seen,
                state.pending_artifact_publication.is_some(),
                state.publication.is_some(),
                state.result_page.as_ref().map(|page| String::from_utf8_lossy(&page.bytes[..page.len]))
            );
            assert_eq!(serde_json::json!(observe(app.store.snapshot_root().as_ref())), serde_json::json!(expected));
            assert!(app.tool_cancellations.cancel(&fresh_key).unwrap());
            for _ in 0..100_000 {
                if app.close_terminal_is_empty() {
                    break;
                }
                match app.close_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES).unwrap() {
                    PluginCloseStep::Pending { released_items, released_bytes } => {
                        assert!(released_items <= 1);
                        assert!(released_bytes <= TYPED_OPERATION_RESULT_PAGE_BYTES);
                    }
                    PluginCloseStep::Complete => break,
                    PluginCloseStep::AwaitingInput { reason } => panic!("registered keyed dispatch close awaited input: {reason}"),
                    PluginCloseStep::Blocked { .. } => {}
                }
                plugin_job_yield_once().await;
            }
            assert!(app.close_terminal_is_empty());
            eprintln!("[TRACE] actual registered keyed dispatch {} preserved exact target supersession, rebased its worker, published count{expected}, and closed every retained owner", case["id"]);
        }
        for case in fixture["lostReservations"].as_array().unwrap() {
            let mut app = VcsArtifactApp::<A>::with_registry(A::default(), registry.clone()).await;
            app.bind_instance_id(7).await;
            let meta = ActionMeta { actor: "fixture".into(), instance_id: 7, view_state: None };
            let command = Box::new(command("aä🧵", 42));
            let wire = <A::Command as ::protocol::OpBinary>::encode_op(&command).unwrap();
            let admission = app.admit_command_wire("compositeEdit", &wire, 1).await.unwrap();
            app.dispatch_typed_command_inner(command, admission, &meta).await.unwrap();
            let id = *app.latest_wins_order.items.front().unwrap();
            let pending = app.latest_wins_commands.get_mut(id).unwrap();
            let copy = pending.key_copy.take();
            let key = pending.key.take();
            pending.retired_key = Some(fixture["keyRetirement"]["text"].as_str().unwrap().into());
            assert_eq!(pending.close_key_step(0, 4_096), PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            let mut retired_bytes = 0;
            for bytes in fixture["keyRetirement"]["scalarBytes"].as_array().unwrap() {
                let bytes = bytes.as_u64().unwrap() as usize;
                assert_eq!(pending.close_key_step(1, bytes - 1), PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                assert_eq!(pending.close_key_step(1, bytes), PluginCloseStep::Pending { released_items: 0, released_bytes: bytes });
                retired_bytes += bytes;
            }
            assert_eq!(serde_json::json!(retired_bytes), fixture["keyRetirement"]["utf8Bytes"]);
            assert_eq!(pending.close_key_step(1, 0), PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            pending.key_copy = copy;
            pending.key = key;
            let slot = id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let foreign = id + ARTIFACT_LIVE_OUTPUT_SLOTS as u64;
            app.typed_operation_reservations[slot] = case["foreignReservation"].as_bool().unwrap().then_some(foreign);
            for _ in 0..8 {
                app.advance_latest_wins_command_one().await.unwrap();
                assert!(app.tool_operations.get(id).is_none());
                if case["foreignReservation"].as_bool().unwrap() {
                    assert_eq!(app.typed_operation_reservations[slot], Some(foreign));
                }
            }
            app.typed_operation_reservations[slot] = None;
            for _ in 0..100_000 {
                if app.tool_operations.get(id).is_some() {
                    break;
                }
                app.advance_latest_wins_command_one().await.unwrap();
            }
            let mounted = app.tool_operations.get_mut(id).expect("vacant rejected slot receives its retained terminal result");
            assert!(mounted.session.is_none());
            let page = mounted.result_page.as_ref().unwrap();
            assert_eq!(page.lane, TypedOperationResultLane::Fault);
            assert!(mounted.acknowledge_result_page(page.token).unwrap());
            assert_eq!(observe(app.store.snapshot_root().as_ref()), 0);
            for _ in 0..100_000 {
                if app.close_terminal_is_empty() {
                    break;
                }
                let _ = app.close_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES).unwrap();
                plugin_job_yield_once().await;
            }
            assert!(app.close_terminal_is_empty());
            eprintln!("[TRACE] actual registered keyed dispatch {} preserved foreign reservation, retired seven UTF-8 bytes exactly, and delivered rejection after vacancy", case["id"]);
        }
    }

    /// 🎰️ ticket 26/09/02/PUZZLE-3D-END-TO-END wave B0: typed-operation ingress pre-admits the exact slot
    /// BEFORE it mints an operation id. Minting from the process-wide counter first and then testing that
    /// one residue class of the direct-mapped 64-slot authorities refused unrelated live actions —
    /// `suggestionsTick`, `setCamera`, `engagementAbort`, `translateSelection` all died on
    /// it in the puzzle3d browser battery — whenever a live operation happened to share the class. With 63
    /// classes held, sixty-four consecutive admissions must every time land on the one vacant slot (the
    /// mint-then-test model visits every residue class across that span, so it fails here deterministically),
    /// a real dispatch must succeed there, and only true saturation may refuse.
    #[cfg(test)]
    pub(crate) async fn test_typed_operation_slot_preadmission<A: ArtifactApp + Default>(registry: AppActionRegistry, verb: &str, command: fn(&str, i32) -> A::Command) {
        const VACANT: usize = 11;
        let mut app = VcsArtifactApp::<A>::with_registry(A::default(), registry).await;
        app.bind_instance_id(7).await;
        let meta = ActionMeta { actor: "fixture".into(), instance_id: 7, view_state: None };
        for slot in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
            app.typed_operation_reservations[slot] = (slot != VACANT).then_some((slot + 3 * ARTIFACT_LIVE_OUTPUT_SLOTS) as u64);
        }
        for _ in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
            let admitted = app.admit_typed_operation_slot().expect("one vacant residue class still pre-admits an exact operation slot");
            assert_eq!(admitted.0 as usize % ARTIFACT_LIVE_OUTPUT_SLOTS, VACANT, "ingress must mint its operation id FOR the vacant slot instead of testing whichever slot the shared counter reached");
        }
        let first = Box::new(command("aä🧵", 42));
        let wire = <A::Command as ::protocol::OpBinary>::encode_op(&first).unwrap();
        let admission = app.admit_command_wire(verb, &wire, 1).await.unwrap();
        app.dispatch_typed_command_inner(first, admission, &meta).await.expect("a typed action must dispatch while unrelated operations hold every other slot");
        let operation_id = *app.latest_wins_order.items.front().expect("the admitted operation owns the vacant slot");
        assert_eq!(operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS, VACANT);
        assert_eq!(app.typed_operation_reservations[VACANT], Some(operation_id));
        let saturated = Box::new(command("bö🧶", 43));
        let wire = <A::Command as ::protocol::OpBinary>::encode_op(&saturated).unwrap();
        let admission = app.admit_command_wire(verb, &wire, 1).await.unwrap();
        let fault = app.dispatch_typed_command_inner(saturated, admission, &meta).await.expect_err("only true saturation of every fixed slot may refuse a typed action");
        assert_eq!(fault.code.0, "interactive-job.typed-operation-capacity");
        assert!(app.admit_typed_operation_slot().is_none());
        for slot in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
            if slot != VACANT {
                app.typed_operation_reservations[slot] = None;
            }
        }
        app.latest_wins_commands.get_mut(operation_id).expect("the pending keyed command").lease.as_ref().expect("pending cancellation lease").cancel();
        for _ in 0..100_000 {
            if app.tool_operations.get(operation_id).is_some() {
                break;
            }
            app.advance_latest_wins_command_one().await.unwrap();
            plugin_job_yield_once().await;
        }
        let mounted = app.tool_operations.get_mut(operation_id).expect("the cancelled pending command lands its retained terminal result");
        let page = mounted.result_page.as_ref().expect("terminal fault page");
        assert_eq!(page.lane, TypedOperationResultLane::Fault);
        let token = page.token;
        assert!(mounted.acknowledge_result_page(token).unwrap());
        for _ in 0..100_000 {
            if app.close_terminal_is_empty() {
                break;
            }
            let _ = app.close_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES).unwrap();
