    /// 🪪️ Preflights every runtime row before factory work and publishes its allocation-bound lifecycle together.
    pub(crate) async fn plugin_open_actor_instance<PA: PluginApp>(runtime: &PluginRuntime<PA>, request: semio_framework::kernel::ActorInstanceOpenRequest, app_id: &str, actor: &str) -> Result<(), Fault> {
        let actor = RuntimeActorAuthority::new(actor)?;
        let mut lifetimes = runtime.guest_lifetimes.try_borrow_mut().map_err(|_| plugin_internal_fault("lifecycle authority busy"))?;
        let slot = lifetimes.get_mut(request.instance_id).filter(|slot| slot.cell.matches_open(request)).ok_or_else(|| plugin_internal_fault("exact opening lifecycle missing"))?;
        if slot.native_created || slot.cell.owner().is_some() {
            return Err(plugin_internal_fault("native opening already captured"));
        }
        let mut instances = runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority busy"))?;
        let mut quarantine = runtime.close_quarantine.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime quarantine authority busy"))?;
        let mut actors = runtime.instance_actors.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime actor authority busy"))?;
        let mut document_backbones = runtime.document_backbones.try_borrow_mut().map_err(|_| plugin_internal_fault("document backbone binding authority busy"))?;
        if !instances.can_insert(request.instance_id) || !quarantine.can_insert(request.instance_id) || !actors.can_insert(request.instance_id) || !document_backbones.can_insert(request.instance_id) {
            return Err(plugin_internal_fault("native opening slot collided"));
        }
        if let Some(fault) = runtime.plugin_assembly_error.try_borrow().map_err(|_| plugin_internal_fault("plugin assembly authority busy"))?.clone() {
            return Err(fault);
        }
        let program = runtime.plugin.try_borrow().map_err(|_| plugin_internal_fault("plugin factory authority busy"))?;
        let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
        let mut app = program.create_app(app_id).ok_or_else(|| plugin_internal_fault("unknown app"))?;
        ::semio_framework_async::poll::resolve_ready(app.bind_instance_id(request.instance_id));
        let cell = std::sync::Arc::new(RuntimeAppCell::new(AppInstance { id: request.instance_id, app, surface_contexts: Default::default() }));
        let lease = PluginInstanceCloseLease::from_cell(request.instance_id, &cell);
        let owner = crate::reactor::instance_lifetime::NativeLifetimeOwner::from_lease(slot.cell.lifetime(), lease).expect("preflighted exact native lifetime");
        slot.cell.install_owner(owner).unwrap_or_else(|_| panic!("preflighted opening owner slot"));
        instances.insert_admitted(request.instance_id, cell);
        actors.insert_admitted(request.instance_id, actor);
        slot.native_created = true;
        Ok(())
    }

    pub async fn plugin_create_app<PA: PluginApp>(runtime: &PluginRuntime<PA>, app_id: &str) -> Result<u32, Fault> {
        plugin_create_app_with_id(runtime, NEXT_INSTANCE_ID.fetch_add(1, Ordering::SeqCst), app_id).await
    }

    /// 🧬️ A2 (design-abi.md §2): `Event::InstanceOpen` carries a host-assigned `PluginInstanceId`
    /// (WIT `instance-id`) — the actor no longer allocates its own; it must open the app under
    /// EXACTLY the id the host names. `⚛️reactor::poll`'s `InstanceOpen` routing calls this instead
    /// of `plugin_create_app`. `plugin_create_app` (unchanged signature, still used by every
    /// pre-existing caller) now delegates here with a locally-allocated id, so nothing observing
    /// its old auto-increment behavior breaks.
    ///
    /// 🌉️ `slot.borrow()` is a `Ref` from `LocalKey::with`'s sync `FnOnce(&T) -> R` closure,
    /// which cannot itself be `async` — bridged via `resolve_ready` exactly like every other
    /// E4/E5-adjacent sync-context call in this file (`Plugin::create_app`'s body does no real
    /// awaiting; see the framework io module's `resolve_ready` doc comment).
    pub async fn plugin_create_app_with_id<PA: PluginApp>(runtime: &PluginRuntime<PA>, id: u32, app_id: &str) -> Result<u32, Fault> {
        if let Some(fault) = runtime.plugin_assembly_error.borrow().clone() {
            return Err(fault);
        }
        if !runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?.can_insert(id)
            || !runtime.close_quarantine.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime close quarantine is busy"))?.can_insert(id)
        {
            return Err(plugin_internal_fault(format!("fixed instance authority is saturated, collided, or quarantined: {id}")));
        }
        {
            let program = runtime.plugin.borrow();
            let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
            let mut app = program.create_app(app_id).ok_or_else(|| plugin_internal_fault(format!("unknown app: {app_id}")))?;
            ::semio_framework_async::poll::resolve_ready(app.bind_instance_id(id));
            ::semio_framework_async::poll::resolve_ready(with_instances_mut(runtime, |list| {
                list.insert_admitted(id, std::sync::Arc::new(RuntimeAppCell::new(AppInstance { id, app, surface_contexts: Default::default() })));
                Ok(())
            }))?;
            Ok(id)
        }
    }

    /// 🚪️ Items one app close step may retire. Priced per PAGE, not per item: the app close ladder
    /// walks FIXED slot geometry (`TOOL_CANCELLATION_SLOTS + ARTIFACT_LIVE_OUTPUT_SLOTS` = 1 088
    /// cancellation slots, then five 64-slot output cursors), and at one item per step that geometry
    /// alone cost 1 088 close steps — each one a pool pump the guest only gets 64 of per reactor turn
    /// on wasm, i.e. a browser worker round trip every 64 slots. The stages that own real per-item
    /// work (a media export's own byte budget, one download segment and one chunk) keep their own
    /// `.min(1)` grant, so this page only collapses the cursor SWEEPS.
    const RUNTIME_CLOSE_ITEMS_PER_STEP: usize = 1_024;
    /// 🚪️ Bytes one app close/maintenance step may retire — one PAGE, the same unit the reactor turn's
    /// own retirement ladder is priced in (`PATCH_RETIREMENT_BYTES_PER_UNIT`). At 4 096 it was exactly
    /// `ARTIFACT_OUTPUT_CHUNK_BYTES`, so a retained item larger than one output chunk — a tessellated
    /// preview mesh in a displaced window transient — could not be released by ANY number of steps and
    /// the ladder answered `Pending { 0, 0 }` until the structural accountant killed the close with
    /// `plugin.internal.zero-progress` (reproduced by the close-cost fixture's eight-document session,
    /// ticket 26/09/09).
    pub(crate) const RUNTIME_CLOSE_BYTES_PER_STEP: usize = 32 * 1_024;
    const RUNTIME_CLOSE_INNER_GRANT_US: u64 = 2_000;
    const RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT: u8 = 8;
    /// ⏱️ Real time a close ladder must spend making no progress before the structural accountant is
    /// allowed to call it stalled — the SECOND half of the zero-progress verdict, next to the step
    /// count above.
    ///
    /// 🐛️ The count alone was the whole rule, and a count is not a duration: eight consecutive steps
    /// that each observe an empty ladder cost microseconds, so a close that had nothing left to retire
    /// faulted with `plugin.internal.zero-progress` reporting `elapsed 0us` against an `8000us`
    /// ceiling — a stall credit judged exhausted before any time had passed (six-pane demonstrator
    /// boot, ticket 26/08/28, `📓️fix-2026-09-16-concurrent-boot-timeout-and-close-fault.md`). A ladder
    /// that is genuinely wedged still burns this credit within a few reactor turns; one that is merely
    /// finishing never does.
    const RUNTIME_CLOSE_STALL_CREDIT_US: u64 = semio_framework_trace::INTERACTIVE_STEP_CEILING_US;

    struct RuntimeLiveCleanupPump<PA: PluginApp> {
        session: Option<semio_framework_job::BatchJobSession<RuntimeLiveCleanupJob<PA>>>,
        rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RuntimeLiveCleanupJob<PA>>>,
        outcome: Option<semio_framework_job::StepOutcome>,
        terminal: bool,
        pending_status: RuntimeMaintenanceStatus,
        closing: bool,
        faulted: bool,
    }

    impl<PA: PluginApp> RuntimeLiveCleanupPump<PA> {
        fn new() -> Self {
            Self { session: None, rejected: None, outcome: None, terminal: false, pending_status: RuntimeMaintenanceStatus::Ready, closing: false, faulted: false }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if let Some(outcome) = self.outcome.as_mut() {
                let step = outcome.close_step(maximum_items, maximum_bytes);
                let retired = outcome.terminal_is_empty();
                if retired {
                    self.outcome = None;
                }
                return match step {
                    semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::JobPayloadCloseStep::Complete => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: usize::from(retired), released_bytes: 0 },
                };
            }
            if let Some(rejected) = self.rejected.as_mut() {
                let step = rejected.close_step(maximum_items, maximum_bytes);
                let retired = rejected.terminal_is_empty();
                if retired {
                    self.rejected = None;
                }
                return match step {
                    semio_framework_job::InteractiveJobCloseStep::Complete if retired => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 },
                    step => step,
                };
            }
            if let Some(session) = self.session.as_mut() {
                session.begin_close();
                let step = session.close_step(maximum_items, maximum_bytes);
                let retired = session.terminal_is_empty();
                if retired {
                    self.session = None;
                }
                return match step {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::WorkerJobCloseStep::Blocked => semio_framework_job::InteractiveJobCloseStep::Blocked,
                    semio_framework_job::WorkerJobCloseStep::Complete => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: usize::from(retired), released_bytes: 0 },
                };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.session.is_none() && self.rejected.is_none() && self.outcome.is_none()
        }
    }

    struct RuntimeCloseCleanupPump<PA: PluginApp> {
        session: Option<semio_framework_job::BatchJobSession<RuntimeCloseCleanupJob<PA>>>,
        rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RuntimeCloseCleanupJob<PA>>>,
        outcome: Option<semio_framework_job::StepOutcome>,
        terminal: bool,
        complete: bool,
        blocked: bool,
        pending_status: RuntimeCloseStatus,
        faulted: bool,
    }

    impl<PA: PluginApp> RuntimeCloseCleanupPump<PA> {
