        "outputAction" => json!({ "kind": "outputAction", "action": payload.action.as_deref().unwrap_or("") }).to_string(),
        "outputExport" => json!({ "kind": "outputExport", "format": payload.format.as_deref().unwrap_or("") }).to_string(),
