pub fn jack_content_from_children<'a>(snapshot: &JackSnapshot, children: &'a semio_framework_plugin::app::ChildContentView) -> Result<store::SnapshotReadRef<'a, SemioGraphSnapshot>, semio_framework_plugin::Fault> {
