fn split_endpoint(endpoint: &str) -> (GraphNodeId, Option<String>) {
    endpoint.split_once('@').map_or((GraphNodeId::new(endpoint), None), |(node, port)| (GraphNodeId::new(node), Some(port.to_string())))
}

