        }
        let cursor = self.cursor.take().expect("terminal artifact cursor remains present");
        drop(cursor);
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.cursor.is_none() && self.active.is_none()
    }
}

