/// 🧹️ One retired value of an explicitly bounded store owner, charged exactly one page. `ManuallyDrop`
/// because every terminal shell under `ArtifactEnvelope` asserts that its owners left through a
/// cursor rather than through `Drop`.
///
/// 🎟️ The value is freed on the first positive grant; `debt` carries the part of its page charge that
/// did not fit the caller's grant and is reported in grant-sized instalments, so no turn exceeds its
/// grant and the close still reports exactly one page per value. A sub-page grant used to answer
/// `Pending { 0, 0 }` forever while `next_close_byte_demand` published 1 — the livelock that kept a
/// neutral 1-byte close of any app with a bounded config or draft lane from finishing
/// (ticket 26/09/19/SEMIO-TECH-PLAY-GRID-WITH-EVERY-APP, `📓️flow.md` §8).
struct BoundedArtifactValueRetirement<T> {
    value: std::mem::ManuallyDrop<Option<T>>,
    debt: usize,
}

impl<T> BoundedArtifactValueRetirement<T> {
    fn new(value: T) -> Self {
        Self { value: std::mem::ManuallyDrop::new(Some(value)), debt: 0 }
    }
}

impl<T: Send + 'static> ErasedSnapshotRetirement for BoundedArtifactValueRetirement<T> {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 || maximum_bytes == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.debt > 0 {
            let paid = self.debt.min(maximum_bytes);
            self.debt -= paid;
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: paid });
        }
        if let Some(value) = self.value.take() {
            drop(value);
            let paid = ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES.min(maximum_bytes);
            self.debt = ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES - paid;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: paid });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.value.is_none() && self.debt == 0
    }
}

impl<T> Drop for BoundedArtifactValueRetirement<T> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.value.is_none() && self.debt == 0), "bounded artifact value retirement reached Drop before exact terminal emptiness");
    }
}

struct BoundedArtifactRetirementFactory<T>(PhantomData<fn() -> T>);

impl<T> BoundedArtifactRetirementFactory<T> {
    fn new() -> Self {
        Self(PhantomData)
    }
}

impl<T: Send + 'static> ArtifactOwnedValueRetirementFactory<T> for BoundedArtifactRetirementFactory<T> {
    fn retire_owned(&self, value: T) -> Box<dyn ErasedSnapshotRetirement> {
        Box::new(BoundedArtifactValueRetirement::new(value))
    }
}

impl<T: Send + Sync + 'static> SnapshotRetirementFactory<T> for BoundedArtifactRetirementFactory<T> {
    fn retire(&self, snapshot: Arc<T>) -> Box<dyn ErasedSnapshotRetirement> {
        Box::new(BoundedArtifactValueRetirement::new(snapshot))
    }
}

/// 🗃️ The exact one-page retirement catalogue for a store whose owner is the FRAMEWORK rather than a
/// plugin app: every factory releases one value per page-sized grant and the cursor disposer is the
/// store's own. `🔌️plugin`'s `bounded_config_store_owners`/`bounded_document_store_owners` are this
/// function — they delegate here rather than carrying a second copy — and
/// `ArtifactCodec::apply_ops_binary`'s throwaway reduction store installs it directly, which is the
/// only catalogue it can have: that thunk is monomorphized over `(P, Mutation)` alone, with no app
/// type in scope to ask `build_document_store_owners()` of (ticket 26/09/18 slices TC3e §7d, TC4).
pub fn bounded_artifact_store_owners<P, Mutation>() -> DocumentStoreOwners<P, Mutation>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + Sync + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    DocumentStoreOwners::new(
        Arc::new(BoundedArtifactRetirementFactory::<P>::new()),
        Arc::new(BoundedArtifactRetirementFactory::<P>::new()),
        Arc::new(BoundedArtifactRetirementFactory::<Mutation>::new()),
        Box::new(ArtifactStoreCursorDisposer::<P, Mutation>::new()),
    )
}

/// 🧺️ Runs a throwaway reduction store's close cursor to exact terminal emptiness and forgets the
/// shell, so no codec thunk can reach `ArtifactStore`'s asserting `Drop` with a live owner. Shared by
/// [`ArtifactCodec::apply_ops_binary`] and [`replay_envelopes_onto_pair`].
fn close_codec_reduction_store<P, Mutation>(mut store: ArtifactStore<P, Mutation>) -> Result<(), VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    let mut closed = Err(VcsError::ValidationFailed("artifact codec store did not reach terminal emptiness within its bounded close budget".into()));
    for _ in 0..ARTIFACT_CODEC_APPLY_CLOSE_MAXIMUM_STEPS {
        match store.close_owned_step(1, ARTIFACT_STORE_ONE_ITEM_MAXIMUM_BYTES) {
            Ok(SnapshotRetirementStep::Complete) => {
                closed = if store.close_owned_terminal_is_empty() { Ok(()) } else { Err(VcsError::ValidationFailed("artifact codec store reported close completion without terminal emptiness".into())) };
                break;
            }
            Ok(SnapshotRetirementStep::Pending { .. }) => continue,
            Ok(SnapshotRetirementStep::Blocked) => {
                closed = Err(VcsError::ValidationFailed("artifact codec store close is blocked by an outstanding snapshot read lease".into()));
                break;
            }
            Err(error) => {
                closed = Err(VcsError::ValidationFailed(error.into_message()));
                break;
            }
        }
    }
    let drop_ready = store.envelope_detached
        && store.current_detached
        && store.backbone.is_none()
        && store.dag.terminal_is_empty()
        && store.applied_edit_ids.is_empty()
        && store.redo_edit_ids.is_empty()
        && store.current_checkpoint_id.is_none()
        && store.local_actor_id.is_none()
        && store.revision_accumulator.applied.is_empty()
        && store.revision_accumulator.redo.is_empty()
        && store.tail_undo_cache.is_none()
        && store.snapshot_read_leases.terminal_is_empty()
        && store.displaced_retirements.terminal_is_empty()
        && store.owned_disposer.is_none()
        && store.owned_disposer_terminal
        && store.pending_report.edit_ids.is_none()
        && store.pending_report.messages.is_empty()
        && store.pending_report.outbound.is_empty()
        && store.pending_report.worst.is_none()
        && store.durable_group_root.is_none();
    std::mem::forget(store);
    closed?;
    if drop_ready { Ok(()) } else { Err(VcsError::ValidationFailed("artifact codec store close left a live shallow-shell owner".into())) }
}

/// 📜️ Folds an [`crate::os_spr::encode_envelopes`] ledger stream onto one authoritative pair through
/// the SAME gate every replica folds a remote envelope through ([`ArtifactStore::ingest_remote`]):
/// causal order, history transitions (undo/redo/checkpoint), edit identity and conflict quarantine are
/// exactly a replica's, so the printed pair is the one any client holding that ledger prefix holds.
/// A quarantined conflict or an envelope left waiting on an unknown dependency refuses the fold, and a
/// raw-mutation apply (`apply_ops_binary`) is never a substitute: it mints new edit ids and drops every
/// transition. A ledger that changed effective inputs is judged once, as the history it folds to
/// ([`ArtifactStore::refuse_blocking_history`]) — never at the intermediate states its envelopes pass through, so a later
/// supersession heals an earlier one. This is how a hub materializes a Check In from its own ledger.
///
/// See `🌎️hub/🗿️artifact-authority/📌️check-in` and `db::artifact_ledger_tail`.
/// 📌️ The alternative a hub Check In materializes. It is the canonical trunk of `document_id`;
/// a viewer's checkout is local and never selects it.
pub fn canonical_check_in_line(document_id: &str) -> String {
    crate::os_spr::trunk_alternative_id(&ArtifactId(document_id.to_string()))
}

pub async fn replay_envelopes_onto_pair<P, Mutation>(pack: &[u8], spr: &[u8], envelopes: &[u8], owners: impl FnOnce() -> DocumentStoreOwners<P, Mutation>) -> Result<ArtifactPackFiles, VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    if pack.is_empty() || spr.is_empty() {
        return Err(VcsError::Deserialize("replay-envelopes has no pack+spr baseline".into()));
    }
    let envelopes = crate::os_spr::decode_envelopes(envelopes).map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let parsed = parse_document_pack::<P, Mutation>(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let mut envelope = parsed.into_envelope();
    let _canonical_line = canonical_check_in_line(&envelope.id);
    envelope.active_alternative_id = None;
    envelope.viewer_checkpoint_id = None;
    project_envelope_history(&mut envelope)?;
    let (applied, redo) = match &envelope.cursor {
        Some(cursor) => (cursor.applied_edit_ids.clone(), cursor.redo_edit_ids.clone()),
        None => (envelope.vcs.edits.iter().map(|edit| edit.id.clone()).collect(), crate::os_vcs::HistoryPageStack::new()),
    };
    envelope.cursor = Some(ArtifactCursor::new(applied, redo, envelope.cursor.as_ref().and_then(|cursor| cursor.checkpoint_id.clone())));
    let mut store = ArtifactStore::new(envelope).await?;
    store.install_document_store_owners_exact(owners());
    let baseline = store.supersessions().clone();
    let mut folded = Ok(());
    for envelope in envelopes {
        match store.ingest_remote(envelope).await {
            Ok(report) if report.accepted && report.conflict.is_none() => {}
            Ok(_) => {
                folded = Err(VcsError::ValidationFailed("replay-envelopes quarantined a ledger envelope as a conflict".into()));
                break;
            }
            Err(error) => {
                folded = Err(error);
                break;
            }
        }
    }
    if folded.is_ok() && !store.dag.pending_is_empty() {
        folded = Err(VcsError::ValidationFailed("replay-envelopes left a ledger envelope waiting on an unknown dependency".into()));
    }
    if folded.is_ok() && *store.supersessions() != baseline {
        folded = store.refuse_blocking_history();
    }
    let printed = match &folded {
        Ok(()) => print_document_pack(&store.envelope).await,
        Err(_) => Err(VcsError::ValidationFailed("replay-envelopes skipped print after a refused fold".into())),
    };
    let closed = close_codec_reduction_store(store);
    folded?;
    closed?;
    printed
}
