        backbone,
        active_alternative_id: None,
        cursor: Some(ArtifactCursor::default()),
        dialect: None,
        migrated_from: None,
        owner: None,
        lanes: BTreeMap::new(),
        edit_messages: ArtifactEditMessageLedger::new(),
