    PruneDrafts,
    /// 🛤️ Text twin of `ArtifactCommand::ApplyInLane` — `lane` is a kebab token
    /// (`history_lane_to_token`/`parse_history_lane_token`), matching `Undo.policy`'s convention.
    ApplyInLane {
        description: Option<String>,
        lane: String,
        transaction: Option<String>,
        tool: Option<String>,
