    fn begin(&self, request: ArtifactEphemeralOneItemPreparationRequest<P, Mutation>) -> Result<Box<dyn ArtifactEphemeralOneItemPreparation<P, Mutation>>, ArtifactEphemeralOneItemPreparationRequest<P, Mutation>>;
